function keyboardHelpSectionHtml(section, className = '') {
  const extraClass = className ? ` ${className}` : '';
  return `
    <section class="keyboard-shortcuts-section${extraClass}">
      <h3>${esc(section.section)}</h3>
      <div class="keyboard-shortcuts-list">
        ${section.items.map(item => `
          <div class="keyboard-shortcut-row">
            <span>${esc(item.label)}</span>
            <kbd>${esc(item.keys)}</kbd>
          </div>`).join('')}
      </div>
    </section>`;
}

function keyboardLegendSectionHtml(section) {
  return `
    <section class="keyboard-shortcuts-section keyboard-legends-section">
      <h3>${esc(section.section)}</h3>
      <div class="keyboard-shortcuts-list keyboard-legends-list">
        ${section.items.map(item => `
          <div class="keyboard-legend-row">
            <span class="keyboard-legend-sample">${item.sampleHtml || ''}</span>
            <span class="keyboard-legend-text">
              <span class="keyboard-legend-label">${esc(item.label)}</span>
              <span class="keyboard-legend-detail">${esc(item.detail)}</span>
            </span>
          </div>`).join('')}
      </div>
    </section>`;
}

function keyboardShortcutsSectionWeight(section, isLegend = false) {
  const itemWeight = isLegend ? 1.35 : 1;
  return 1 + (Array.isArray(section?.items) ? section.items.length * itemWeight : 0);
}

function keyboardShortcutsHtml() {
  const sections = [
    ...keyboardShortcutCatalog().map(section => ({
      html: keyboardHelpSectionHtml(section),
      weight: keyboardShortcutsSectionWeight(section, false),
    })),
    ...keyboardLegendCatalog().map(section => ({
      html: keyboardLegendSectionHtml(section),
      weight: keyboardShortcutsSectionWeight(section, true),
    })),
  ];
  const columns = Array.from({length: 4}, () => ({html: [], weight: 0}));
  for (const section of sections) {
    const column = columns.reduce((best, current) => current.weight < best.weight ? current : best);
    column.html.push(section.html);
    column.weight += section.weight;
  }
  return columns.map(column => `
    <div class="keyboard-shortcuts-column">
      ${column.html.join('')}
    </div>`).join('');
}

function ensureKeyboardShortcutsOverlay() {
  if (keyboardShortcutsNode) return keyboardShortcutsNode;
  const node = document.createElement('div');
  node.className = 'app-modal-overlay keyboard-shortcuts-overlay';
  node.hidden = true;
  node.innerHTML = `
    <div class="keyboard-shortcuts-dialog" role="dialog" aria-modal="true" aria-label="${esc(t('common.keyboardShortcuts'))}">
      <div class="keyboard-shortcuts-head">
        <h2>${esc(t('common.keyboardShortcuts'))}</h2>
        <button type="button" class="keyboard-shortcuts-close" aria-label="${esc(t('shortcuts.close'))}">×</button>
      </div>
      <div class="keyboard-shortcuts-body"></div>
    </div>`;
  node.addEventListener('mousedown', event => {
    if (event.target === node) closeKeyboardShortcutsOverlay();
  });
  node.querySelector('.keyboard-shortcuts-close')?.addEventListener('click', closeKeyboardShortcutsOverlay);
  appOverlayRootElement().appendChild(node);
  keyboardShortcutsNode = node;
  return node;
}

function renderKeyboardShortcutsOverlay(node = keyboardShortcutsNode) {
  if (!node) return false;
  const dialog = node.querySelector('.keyboard-shortcuts-dialog');
  const heading = node.querySelector('.keyboard-shortcuts-head h2');
  const close = node.querySelector('.keyboard-shortcuts-close');
  const body = node.querySelector('.keyboard-shortcuts-body');
  if (dialog) dialog.setAttribute('aria-label', t('common.keyboardShortcuts'));
  if (heading) heading.textContent = t('common.keyboardShortcuts');
  if (close) close.setAttribute('aria-label', t('shortcuts.close'));
  if (body) body.innerHTML = keyboardShortcutsHtml();
  return true;
}

function relocalizeKeyboardShortcutsOverlay() {
  return renderKeyboardShortcutsOverlay(keyboardShortcutsNode);
}

function openKeyboardShortcutsOverlay() {
  const node = ensureKeyboardShortcutsOverlay();
  closeAppMenus();
  closeCommandPalette();
  renderKeyboardShortcutsOverlay(node);
  node.hidden = false;
  node.classList.add(CLS.open);
  node.querySelector('.keyboard-shortcuts-close')?.focus?.({preventScroll: true});
}

function closeKeyboardShortcutsOverlay() {
  if (!keyboardShortcutsNode) return;
  keyboardShortcutsNode.hidden = true;
  keyboardShortcutsNode.classList.remove(CLS.open);
}

function commandPaletteAllTabItems() {
  return Array.from(new Set([...activePaneItems(), ...backgroundTabItems(), ...inactiveTabItems()]));
}

const commandPaletteFileTabValidationInflight = new Set();

function commandPaletteFilePathKnownMissing(path) {
  const normalized = normalizeDirectoryPath(path || '');
  const state = normalized ? fileStateFor(normalized) : null;
  return Boolean(state?.externalMissing === true && state?.dirty !== true);
}

function commandPaletteFilePathValidationDue(path, now = Date.now()) {
  const state = fileStateFor(path);
  if (state?.externalMissing !== true) return true;
  const checkedAt = Math.max(0, Number(state.externalMissingCheckedAt) || 0);
  return now - checkedAt >= commandPaletteMissingPathRetryMs;
}

function commandPaletteValidateFileTabPaths(items = commandPaletteAllTabItems()) {
  if (typeof fetchFilePathInfo !== 'function') return;
  for (const item of items) {
    const path = fileItemPath(item);
    const normalized = normalizeDirectoryPath(path || '');
    if (!normalized || commandPaletteFileTabValidationInflight.has(normalized) || !commandPaletteFilePathValidationDue(normalized)) continue;
    commandPaletteFileTabValidationInflight.add(normalized);
    // Fence this validation's "missing" outcome against newer per-path state: a stale/late validation
    // (kind-mismatch or exact-path 404) that completes after a newer valid render landed must not
    // overwrite it. Same generation fence shared with the reload/poll/media producers.
    const generation = openFileContentGeneration.get(normalized) || 0;
    fetchFilePathInfo(normalized, {user: true})
      .then(async info => {
        if (info?.kind === 'file') {
          await recoverOpenFileAfterMissing(normalized, info);
        } else if (info?.kind) {
          if (openFileContentGenerationIsCurrent(normalized, generation)) markOpenFileMissing(normalized);
        }
      })
      .catch(error => {
        if (Number(error?.status) === 404 && openFileContentGenerationIsCurrent(normalized, generation)) {
          markOpenFileMissing(normalized);
          if (commandPaletteState.node && !commandPaletteState.node.hidden) renderCommandPaletteResults();
        }
      })
      .finally(() => {
        commandPaletteFileTabValidationInflight.delete(normalized);
      });
  }
}

function commandPaletteVisibleTabItems() {
  const items = commandPaletteAllTabItems();
  commandPaletteValidateFileTabPaths(items);
  return items.filter(item => {
    const path = fileItemPath(item);
    return !path || !commandPaletteFilePathKnownMissing(path);
  });
}

function commandPaletteCommandTargetsMissingFile(item) {
  const targetPath = fileItemPath(item?.targetItem || '');
  return Boolean(targetPath && commandPaletteFilePathKnownMissing(targetPath));
}

function flattenMenuCommands(items, prefix = []) {
  const result = [];
  for (const item of items || []) {
    if (item.type === 'submenu') {
      result.push(...flattenMenuCommands(item.items, [...prefix, item.label]));
    } else if (item.type === 'command' && item.action && !item.disabled) {
      result.push({
        group: t('palette.group.menu'),
        label: [...prefix, item.label].join(' / '),
        detail: item.detail || '',
        key: `menu:${[...prefix, item.label].join('/')}`,
        targetItem: item.targetItem || '',
        keybinding: commandPaletteKeybinding([...prefix, item.label].join(' / '), item.detail || ''),
        run: item.action,
      });
    }
  }
  return result;
}

function commandPaletteKeybinding(label, detail = '') {
  const text = `${label} ${detail}`;
  if (/command palette/i.test(text)) return appShortcutText('P', {shift: true});
  if (/open file/i.test(text)) return appShortcutText('P');
  if (/toggle .*file explorer|toggle .*finder/i.test(text)) return appShortcutText('B');
  if (/preferences/i.test(text)) return appShortcutText(',');
  if (/keyboard shortcuts/i.test(text)) return '?';
  if (/close menu|dialog/i.test(text)) return 'Esc';
  return /\b(?:Ctrl|Cmd|Shift|Esc|Alt)[^,;]*/.exec(detail)?.[0] || '';
}

// a short localized label for an editor/preview view mode, shown as a chip on a deduped row.
function commandPaletteViewModeLabel(mode) {
  if (mode === 'preview') return t('common.preview');
  if (mode === 'split') return t('editor.mode.split');
  if (mode === 'diff') return t('common.diff');
  return t('common.edit');
}

function commandPaletteNumericTime(value) {
  const number = Number(value || 0);
  if (!Number.isFinite(number) || number <= 0) return 0;
  if (number > 1e15) return number / 1e9;
  if (number > 1e11) return number / 1000;
  return number;
}

function commandPalettePaneMtime(item) {
  if (!isTmuxSession(item)) return 0;
  const info = sessionTranscriptInfo(item).info || {};
  return commandPaletteNumericTime(
    info.last_activity_ts || info.transcript_mtime || info.updated_ts || info.rolling_updated_ts || info.mtime || 0
  );
}

function commandPaletteCommandItems() {
  // Group FILE items by path and emit ONE row per file; non-file tabs (sessions, Finder/Info/Prefs)
  // stay one row each.
  const tabRow = (item, extra = {}) => ({
    group: t('common.tabsLabel'),
    category: 'pane',
    label: itemLabel(item),
    detail: commandPaletteTabDetail(item),
    key: `tab:${item}`,
    targetItem: item,
    mtime: commandPalettePaneMtime(item),
    searchFields: tabSearchFields(item),
    keybinding: 'Enter',
    run: () => {
      if (isFileExplorerItem(item)) return selectSession(item, {userInitiated: true});
      return activateTabInExistingPane(item, {preferFocused: true, userInitiated: true});
    },
    ...extra,
  });
  const fileGroups = new Map();   // path -> [items], in discovery order
  const tabItems = [];
  const allTabItems = commandPaletteVisibleTabItems();
  for (const item of allTabItems) {
    const path = fileItemPath(item);
    if (!path) { tabItems.push(tabRow(item)); continue; }
    if (!fileGroups.has(path)) fileGroups.set(path, []);
    fileGroups.get(path).push(item);
  }
  for (const [path, items] of fileGroups) {
    if (items.length === 1) { tabItems.push(tabRow(items[0])); continue; }
    const editorItem = items[0];
    // Each chip is clickable to jump to that exact view — carry the mode + the layout item.
    const viewModes = [];
    const seenModes = new Set();
    for (const it of items) {
      const mode = editorViewModeFor(path, it);
      if (seenModes.has(mode)) continue;
      seenModes.add(mode);
      viewModes.push({mode, label: commandPaletteViewModeLabel(mode), item: String(it)});
    }
    tabItems.push(tabRow(editorItem, {key: `file:${path}`, viewModes}));
  }
  const tabItemIds = new Set(allTabItems);
  const menuItems = appMenuTree()
    .flatMap(menu => flattenMenuCommands(menu.items, [menu.label]))
    .filter(item => !commandPaletteCommandTargetsMissingFile(item))
    .filter(item => !(item.targetItem && isVirtualItem(item.targetItem) && tabItemIds.has(item.targetItem)))
    .map(item => ({...item, category: 'command'}));
  const settingItems = preferenceSections().flatMap(section => section.items.map(item => ({
    group: t('palette.group.settings'),
    category: 'setting',
    label: `${section.title} / ${item.label}`,
    detail: item.help || item.path,
    key: `setting:${item.path}`,
    keybinding: 'Enter',
    run: () => {
      preferencesSearchText = item.label;
      collapsedPreferenceSections.delete(section.id);
      writeStoredCollapsedPreferenceSections();
      selectSession(prefsItemId);
      requestAnimationFrame(() => {
        renderPreferencesPanels({force: true});
        const control = document.querySelector(`[data-setting-path="${cssEscape(item.path)}"]`);
        control?.focus?.({preventScroll: false});
        control?.scrollIntoView?.({block: 'center', inline: 'nearest'});
      });
    },
  })));
  // A command palette row must name one thing the user can navigate to or
  // execute.  Per-file terminal actions repeat the active file once for every
  // verb and make a filename lookup look like duplicate search hits; keep
  // those actions in the file context menu instead.
  return [...tabItems, ...menuItems, ...settingItems];
}

function commandPaletteDropActionPath() {
  const activeItem = currentActiveMenuItem();
  const activeItemPath = isFileEditorItem(activeItem) ? fileItemPath(activeItem) : '';
  if (activeItemPath) return activeItemPath;
  if (activeFile) return activeFile;
  if (fileExplorerSelectionLead) return fileExplorerSelectionLead;
  return '';
}

function commandPaletteDropActionKind(path) {
  const row = path ? document.querySelector?.(`.file-tree-row[data-path="${cssEscape(path)}"]`) : null;
  return row?.dataset?.kind === 'dir' ? 'dir' : 'file';
}

function commandPaletteDropActionSession() {
  const target = currentSessionActionTarget();
  if (isTmuxSession(target)) return target;
  if (isTmuxSession(focusedTerminal)) return focusedTerminal;
  return activeSessions.find(item => isTmuxSession(item)) || '';
}

function commandPaletteDropActionItems() {
  const path = commandPaletteDropActionPath();
  if (!path) return [];
  if (commandPaletteFilePathKnownMissing(path)) return [];
  const kind = commandPaletteDropActionKind(path);
  const paths = [path];
  const category = fileDropCategory(path, kind);
  const session = commandPaletteDropActionSession();
  const agentKind = session ? sessionAgentKind(session) : '';
  return dropActionsFor(category, agentKind, paths.length, {pathInserted: false, includeShellForAgents: true})
    .map(action => {
      const needsTerminal = action.kind !== 'server';
      const label = dropActionDisplayLabel(action);
      return {
        group: t('palette.group.fileActions'),
        category: 'command',
        label,
        detail: compactHomePath(path),
        key: `drop-action:${action.id}:${path}`,
        keybinding: 'Enter',
        disabled: needsTerminal && !session,
        searchFields: [t('palette.group.fileActions'), label, path, compactHomePath(path)],
        run: () => runDropAction(action, dropActionContext(action, paths, category, agentKind, {session, kind, pathInserted: false})),
      };
    });
}

function fileQuickOpenRootForFile(path) {
  const normalized = normalizeDirectoryPath(path || '');
  if (!normalized || normalized === '/') return '';
  const rawGitRoot = fileState.get(normalized)?.gitRoot || '';
  const gitRoot = rawGitRoot ? normalizeDirectoryPath(rawGitRoot) : '';
  if (gitRoot && pathIsInsideDirectory(normalized, gitRoot)) return gitRoot;
  return dirnameOf(normalized);
}

function fileQuickOpenPathAliasSegment(query) {
  const text = String(query || '').trim();
  if (!text || text.startsWith('/') || text.startsWith('~')) return '';
  const slash = text.indexOf('/');
  return slash > 0 ? text.slice(0, slash) : '';
}

function fileQuickOpenRootMatchesPathAlias(root, query) {
  const alias = fuzzyCanonicalPrefixText(fileQuickOpenPathAliasSegment(query));
  if (alias.length < 2) return false;
  return fuzzyCanonicalPrefixText(basenameOf(root)).startsWith(alias);
}

function fileQuickOpenDoitNeedle(query = commandPaletteSearchQuery()) {
  const needle = String(fileQuickOpenSearchText(query) || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
  return needle.startsWith('doit') && needle.length >= 4 ? needle : '';
}

function fileQuickOpenRepoFamilyBase() {
  return normalizeDirectoryPath(fileQuickOpenState.root || repoRoot || '');
}

function fileQuickOpenRepoFamilyPrefix() {
  const name = basenameOf(fileQuickOpenRepoFamilyBase());
  return String(name || '').replace(/[._-]dev\d*$/i, '');
}

function fileQuickOpenPathInRepoFamily(path) {
  const base = fileQuickOpenRepoFamilyBase();
  const parent = dirnameOf(base);
  const prefix = fileQuickOpenRepoFamilyPrefix();
  const normalized = normalizeDirectoryPath(path || '');
  if (!parent || !prefix || !normalized || !pathIsInsideDirectory(normalized, parent)) return false;
  const top = childPathParts(parent, normalized)[0] || '';
  return top === prefix || top.startsWith(`${prefix}.`) || top.startsWith(`${prefix}-`);
}

function fileQuickOpenDoitCandidateAllowed(file, query = commandPaletteSearchQuery()) {
  const needle = fileQuickOpenDoitNeedle(query);
  if (!needle) return true;
  const path = String(file?.path || '');
  const name = String(file?.name || basenameOf(path));
  const stem = name.includes('.') ? name.slice(0, name.lastIndexOf('.')) : name;
  const nameText = name.toLowerCase().replace(/[^a-z0-9]+/g, '');
  const stemText = stem.toLowerCase().replace(/[^a-z0-9]+/g, '');
  if (!(stemText.startsWith(needle) || nameText.startsWith(needle) || stemText.includes(needle) || nameText.includes(needle))) return false;
  return fileQuickOpenPathInRepoFamily(path);
}

function fileQuickOpenExtraRootsForSearchQuery(query) {
  const familyRoot = fileQuickOpenDoitNeedle(query) ? dirnameOf(fileQuickOpenRepoFamilyBase()) : '';
  const aliasRoots = [repoRoot, fileQuickOpenRootForFile(activeFile)]
    .map(normalizeDirectoryPath)
    .filter(root => root && root !== '/' && fileQuickOpenRootMatchesPathAlias(root, query));
  return compactNestedPaths([...aliasRoots, familyRoot]
    .map(normalizeDirectoryPath)
    .filter(root => root && root !== '/'));
}

function fileQuickOpenRootForSearch() {
  const activeItem = currentActiveMenuItem();
  const activePath = isFileEditorItem(activeItem) ? fileItemPath(activeItem) : '';
  const activeFileRoot = fileQuickOpenRootForFile(activePath);
  if (activeFileRoot) return activeFileRoot;
  const target = currentSessionActionTarget();
  const gitRoot = isTmuxSession(target) ? sessionTranscriptInfo(target).gitRoot : '';
  if (gitRoot) return normalizeDirectoryPath(gitRoot);
  const activeTmux = activeTmuxDirectoryPath(target);
  if (activeTmux) return activeTmux;
  const fallbackFileRoot = fileQuickOpenRootForFile(activeFile);
  if (fallbackFileRoot) return fallbackFileRoot;
  if (fileExplorerRoot) return fileExplorerRoot;
  return repoRoot || homePath || '/';
}

function fileQuickOpenRootsForSearch(root = fileQuickOpenState.root || fileQuickOpenRootForSearch(), query = commandPaletteSearchQuery()) {
  return fileExplorerIndexedSearchRoots(root, fileQuickOpenExtraRootsForSearchQuery(query));
}

function fileQuickOpenScopeLabel(root = fileQuickOpenState.root || fileQuickOpenRootForSearch()) {
  const roots = fileQuickOpenRootsForSearch(root);
  if (roots.length <= 1) return compactHomePath(roots[0] || root || '/');
  return tPlural('palette.scope.indexedRoot', roots.length - 1, {path: compactHomePath(roots[0])});
}

function fileQuickOpenQueryParts(query = commandPaletteState.query) {
  const raw = String(query || '').trim();
  const match = raw.match(/^(.*?)(?::(\d+))?$/);
  return {
    query: (match?.[1] || '').trim(),
    line: match?.[2] ? Math.max(1, Number(match[2])) : null,
    commandMode: raw.startsWith('>'),
    symbolMode: raw.startsWith('@'),
  };
}

function fileQuickOpenSearchText(query = commandPaletteState.query) {
  return fileQuickOpenQueryParts(query).query.replace(/[:.]+$/g, '').trim();
}

function fileQuickOpenPathQuery(query = commandPaletteState.query) {
  const text = fileQuickOpenQueryParts(query).query;
  if (!text.startsWith('/') && !text.startsWith('~')) return {active: false, directory: '', filter: ''};
  if (text === '~') return {active: true, directory: '~', filter: ''};
  if (text.endsWith('/')) return {active: true, directory: text || '/', filter: ''};
  const slash = text.lastIndexOf('/');
  if (text.startsWith('~/') && slash <= 1) return {active: true, directory: '~', filter: text.slice(2)};
  if (slash <= 0) return {active: true, directory: '/', filter: text.slice(1)};
  return {active: true, directory: text.slice(0, slash) || '/', filter: text.slice(slash + 1)};
}

function joinDirectoryPath(directory, name) {
  if (!directory || directory === '/') return `/${name}`;
  if (directory === '~') return `~/${name}`;
  return `${directory.replace(/\/+$/, '')}/${name}`;
}

function descendFileQuickOpenDirectory(path) {
  const directory = normalizeDirectoryPath(path);
  commandPaletteState.query = `${directory}${directory.endsWith('/') ? '' : '/'}`;
  commandPaletteState.index = 0;
  const input = commandPaletteState.node?.querySelector?.('.command-palette-input');
  if (input) input.value = commandPaletteState.query;
  renderCommandPaletteResults();
  refreshFileQuickOpenCandidates(commandPaletteState.query);
}

function revealOpenFileLineSoon(path, line) {
  if (!line) return;
  requestAnimationFrame(() => {
    for (const panel of fileEditorPanelsForPath(path)) {
      if (scrollFileEditorPanelToSourceLine(panel, 'editor', line)) break;
    }
  });
}

function fileQuickOpenTargetSlot() {
  const requested = String(commandPaletteState.targetSlot || '');
  if (requested && layoutSlotKeys().includes(requested)) return requested;
  return focusedActivationSlot();
}

async function openFileQuickOpenPath(path, options = {}) {
  const label = basenameOf(path);
  let openedItem = null;
  if (options.split === true) {
    const targetSlot = largestPaneSlotForFileEditor();
    const splitBaseSlot = targetSlot || slotForSession(currentActiveMenuItem()) || largestPaneSlot();
    openedItem = await openFileInEditor(path, {name: label}, splitBaseSlot
      ? {targetSlot: splitBaseSlot, targetZone: targetSlot ? 'middle' : 'right', forceNewTab: true, userInitiated: true}
      : {forceNewTab: true, userInitiated: true});
  } else {
    const targetSlot = fileQuickOpenTargetSlot();
    openedItem = await openFileInEditor(path, {name: label}, targetSlot
      ? {targetSlot, userInitiated: true}
      : {userInitiated: true});
  }
  focusQuickOpenedFile(openedItem);
  revealOpenFileLineSoon(path, options.line || null);
}

function focusQuickOpenedFile(item) {
  if (!item) return;
  focusPanel(item, {userInitiated: true});
  renderPaneTabStrips();
  requestAnimationFrame(() => focusPanel(item, {userInitiated: true}));
}

function cursorStyleFileReference(path, options = {}) {
  const fullPath = String(path || '');
  if (!fullPath || options.kind === 'dir') return null;
  if (previewMediaKindForPath(fullPath) === 'image') {
    const index = Math.max(1, Math.floor(Number(options.imageIndex || 1)));
    return {label: `[Image #${index}]`, detail: shellQuote(fullPath)};
  }
  return null;
}

function fileQuickOpenItem(path, options = {}) {
  const label = basenameOf(path);
  const isDir = options.kind === 'dir';
  const cursorReference = cursorStyleFileReference(path, options);
  const detail = cursorReference?.detail || compactHomePath(path);
  return {
    group: options.group || t('palette.group.files'),
    category: 'file',
    label: cursorReference?.label || (isDir ? `${label}/` : label),
    detail,
    key: `file:${path}`,
    path,
    mtime: commandPaletteNumericTime(options.mtime || options.mtimeNs || 0),
    iconText: isDir ? disclosureTriangleCollapsedGlyph : fileIconFor(label),
    keybinding: isDir ? 'Enter' : `${appShortcutText('Enter')} ${t('editor.mode.split')}`,
    searchFields: [label, path, detail, options.relativePath || '', cursorReference?.label || ''],
    sortBonus: Number(options.sortBonus || 0),
    run: () => isDir ? descendFileQuickOpenDirectory(path) : openFileQuickOpenPath(path, {line: fileQuickOpenQueryParts().line}),
    splitRun: isDir ? null : () => openFileQuickOpenPath(path, {line: fileQuickOpenQueryParts().line, split: true}),
  };
}

function recentFileQuickOpenItems() {
  return Array.from(fileState.keys()).reverse()
    .filter(path => !commandPaletteFilePathKnownMissing(path))
    .map((path, index) => fileQuickOpenItem(path, {
      group: t('palette.group.recent'),
      mtime: fileState.get(path)?.mtime || 0,
      sortBonus: 120 - index,
    }));
}

function fileQuickOpenExactPathItem() {
  const pathQuery = fileQuickOpenPathQuery();
  if (!pathQuery.active || !pathQuery.filter) return null;
  const path = normalizeDirectoryPath(joinDirectoryPath(pathQuery.directory || '/', pathQuery.filter));
  const name = basenameOf(path);
  if (!name || !fileExtensionOf(name)) return null;
  return {
    ...fileQuickOpenItem(path, {group: t('palette.group.files')}),
    label: t(previewMediaKindForPath(path) === 'image' ? 'palette.openImage' : 'palette.openFile', {name}),
    detail: compactHomePath(path),
    key: `exact-file:${path}`,
    keybinding: appShortcutText('Enter'),
    pinTop: true,
    searchFields: [name, path],
  };
}

// C15 follow-up: while a directory PATH is typed in cmd-P, offer "Open <dir> in Finder" as the pinned
// top row, so Enter (the default highlight) opens that directory in the Finder/File Explorer — while
// arrowing down to a listed entry opens a file or descends into a subfolder. The target is the directory
// the input points at: the listed dir, or its `filter` subfolder when the typed name is an exact subdir.
function fileQuickOpenOpenFolderItem() {
  const pathQuery = fileQuickOpenPathQuery();
  if (!pathQuery.active) return null;
  let target = normalizeDirectoryPath(pathQuery.directory);
  if (pathQuery.filter) {
    const filter = String(pathQuery.filter).toLowerCase();
    const match = fileQuickOpenState.candidates.find(entry => entry.kind === 'dir' && String(entry.name || '').toLowerCase() === filter);
    if (match?.path) target = match.path;
  }
  if (!target) return null;
  return {
    group: t('palette.group.files'),
    label: t('palette.openFolder', {name: fileExplorerLabel()}),
    detail: compactHomePath(target),
    key: `open-folder:${target}`,
    iconText: disclosureTriangleCollapsedGlyph,
    keybinding: appShortcutText('Enter'),
    pinTop: true,
    searchFields: [t('palette.openFolder', {name: fileExplorerLabel()}), target],
    run: async () => { await openFileExplorerPane(); await openFileExplorerAt(target); },
  };
}

function fileQuickOpenExternalIndexedMatchAllowed(file, query = commandPaletteSearchQuery()) {
  const text = String(query || '').trim();
  if (!text || text.includes('/') || text.startsWith('~')) return true;
  const path = String(file?.path || '');
  const basename = String(file?.name || basenameOf(path));
  const stem = basename.includes('.') ? basename.slice(0, basename.lastIndexOf('.')) : basename;
  const relativeSegments = String(file?.relative_path || '').split('/').filter(Boolean);
  // External roots can be very long (for example an iCloud container path). Let the fuzzy matcher
  // work within a filename or one relative-path segment, but never assemble one apparent match from
  // isolated characters spread across unrelated directories and the indexed-root prefix.
  return [basename, stem, ...relativeSegments]
    .some(value => Number.isFinite(fuzzySubsequenceScore(text, value)));
}

function fileQuickOpenItems() {
  const seen = new Set();
  const items = [];
  let imageIndex = 0;
  const add = item => {
    const path = item.searchFields?.[1] || item.detail || item.label;
    if (!path || seen.has(path)) return;
    seen.add(path);
    items.push(item);
  };
  const exactPath = fileQuickOpenExactPathItem();
  if (exactPath) add(exactPath);
  const openFolder = fileQuickOpenOpenFolderItem();
  if (openFolder) items.push(openFolder);
  recentFileQuickOpenItems().forEach(add);
  for (const file of fileQuickOpenState.candidates) {
    const path = file.path || '';
    if (!path) continue;
    if (!fileQuickOpenDoitCandidateAllowed(file)) continue;
    // Only an entry that ACTUALLY came from an indexed-root search carries an indexed_root; path-mode
    // listing entries have none. Guard the empty case — normalizeStoredFileExplorerIndexedDir('') returns
    // '/' (empty -> root), which used to mislabel every path-mode directory row as "Indexed /".
    const indexedRoot = file.indexed_root ? normalizeStoredFileExplorerIndexedDir(file.indexed_root) : '';
    const baseRoot = normalizeStoredFileExplorerIndexedDir(fileQuickOpenState.root || '');
    const externalIndexed = Boolean(indexedRoot && indexedRoot !== baseRoot);
    if (externalIndexed && !fileQuickOpenExternalIndexedMatchAllowed(file)) continue;
    const isImage = (file.kind || 'file') !== 'dir' && previewMediaKindForPath(path) === 'image';
    if (isImage) imageIndex += 1;
    add(fileQuickOpenItem(path, {
      group: externalIndexed ? t('common.indexedPath', {path: compactHomePath(indexedRoot)}) : t('palette.group.files'),
      relativePath: file.relative_path || file.name || '',
      kind: file.kind || 'file',
      imageIndex,
      mtime: file.mtime || 0,
      mtimeNs: file.mtime_ns || 0,
      sortBonus: (externalIndexed ? -250 : 250) + (file.uploaded === true ? -500 : 0),
    }));
  }
  if (fileQuickOpenState.error) {
    const errorText = userMessageText(fileQuickOpenState.error, t('common.searchFailed'));
    items.push({
      group: t('palette.group.files'),
      label: t('common.searchFailed'),
      detail: errorText,
      searchFields: [t('common.searchFailed'), errorText],
      disabled: true,
      run: null,
    });
  }
  if (fileQuickOpenState.loading) {
    items.push({
      group: t('palette.group.files'),
      label: t('palette.searchingFiles'),
      detail: compactHomePath(fileQuickOpenState.root),
      loading: true,
      searchFields: ['searching'],
      disabled: true,
      run: null,
    });
  }
  return items.map(item => ({...item, category: 'file'}));
}

function commandPaletteFilePath(item) {
  return item?.path || item?.searchFields?.[1] || fileItemPath(item?.targetItem || '') || item?.detail || item?.label || '';
}

function commandPaletteMergedItems() {
  const openTabPaths = new Set(commandPaletteVisibleTabItems().map(fileItemPath).filter(Boolean));
  const dedupedFileItems = fileQuickOpenItems().filter(item => !openTabPaths.has(commandPaletteFilePath(item)));
  return [...dedupedFileItems, ...commandPaletteCommandItems()];
}

function commandPaletteCandidateItems(mode = commandPaletteMode, rawQuery = commandPaletteState.query) {
  const parts = fileQuickOpenQueryParts(rawQuery);
  if (parts.commandMode) return commandPaletteCommandItems();                          // `>` = actions only
  if (parts.symbolMode || fileQuickOpenPathQuery(rawQuery).active) return fileQuickOpenItems(); // `@` / path = files only
  // Cmd-P is a file chooser, not a broad command search.  Keeping its candidate
  // source file-only means an exact filename cannot be displaced by contextual
  // FILE ACTIONS rows. Shift-Cmd-P remains the mixed command/pane surface.
  if (mode === 'files') return fileQuickOpenItems();
  if (!commandPaletteSearchQuery(rawQuery, mode)) return commandPaletteCommandItems();
  // S2: a file that is already an open tab shows ONCE — as the deduped Tabs row
  // which carries both edit + preview chips.
  return commandPaletteMergedItems();
}

function commandPaletteItems() {
  return commandPaletteCandidateItems(commandPaletteMode, commandPaletteState.query);
}

function commandPaletteRankItems(items, query, options = {}) {
  const ranked = (items || [])
    .map((item, sortIndex) => ({...item, score: commandPaletteItemScore(item, query, options), sortIndex}))
    .filter(item => Number.isFinite(item.score))
    .sort((left, right) => query
      ? right.score - left.score || left.group.localeCompare(right.group) || left.label.localeCompare(right.label)
      : right.score - left.score || left.sortIndex - right.sortIndex);
  return commandPaletteMixFirstScreenResults(ranked, query, options);
}

function commandPaletteMixDomains(options = {}) {
  const surface = commandPaletteSurface(options);
  if (surface === 'files') return {primary: 'file', secondary: ['pane', 'command', 'setting']};
  if (surface === 'command') return {primary: 'pane', secondary: ['command', 'setting', 'file']};
  return null;
}

function commandPaletteMixFirstScreenResults(ranked, query, options = {}) {
  if (!String(query || '').trim()) return ranked;
  const domains = commandPaletteMixDomains(options);
  if (!domains) return ranked;
  const windowSize = Math.max(0, Number(searchRankWeights.mixWindow || 0));
  const maxSecondary = Math.max(0, Number(searchRankWeights.mixSecondarySlots || 0));
  if (!windowSize || !maxSecondary) return ranked;
  const hasPrimary = ranked.slice(0, windowSize).some(item => commandPaletteItemDomain(item) === domains.primary);
  const secondaryDomains = Array.isArray(domains.secondary) ? domains.secondary : [domains.secondary].filter(Boolean);
  const rowsByDomain = new Map(secondaryDomains.map(domain => [domain, ranked
    .map((item, index) => ({item, index}))
    .filter(row => commandPaletteItemDomain(row.item) === domain)]));
  const secondaryCandidates = [];
  const selectedItems = new Set();
  while (secondaryCandidates.length < maxSecondary) {
    let added = false;
    for (const domain of secondaryDomains) {
      const row = (rowsByDomain.get(domain) || []).find(candidate => !selectedItems.has(candidate.item));
      if (!row) continue;
      secondaryCandidates.push(row);
      selectedItems.add(row.item);
      added = true;
      if (secondaryCandidates.length >= maxSecondary) break;
    }
    if (!added) break;
  }
  if (!hasPrimary || !secondaryCandidates.length) return ranked;
  const selected = [];
  for (const [secondaryIndex, row] of secondaryCandidates.entries()) {
    const target = Math.min(
      windowSize - 1,
      searchRankWeights.mixFirstSecondaryIndex + secondaryIndex * searchRankWeights.mixSecondaryStep
    );
    if (row.index > target) selected.push({item: row.item, target});
  }
  if (!selected.length) return ranked;
  const selectedForMove = new Set(selected.map(row => row.item));
  const result = ranked.filter(item => !selectedForMove.has(item));
  for (const row of selected) {
    result.splice(Math.min(row.target, result.length), 0, row.item);
  }
  return result;
}

function commandPaletteMatches(item, query) {
  return Number.isFinite(commandPaletteItemScore(item, query));
}

function commandPaletteSurface(options = {}) {
  return options.surface === 'files' || options.surface === 'command' ? options.surface : commandPaletteMode;
}

function commandPaletteItemDomain(item) {
  if (item?.category === 'file') return 'file';
  if (item?.category === 'pane') return 'pane';
  if (item?.category === 'setting') return 'setting';
  return 'command';
}

function commandPaletteDomainPrior(item, options = {}) {
  const surface = commandPaletteSurface(options);
  const domain = commandPaletteItemDomain(item);
  return searchRankWeights.domainPrior[surface]?.[domain] || 0;
}

function commandPaletteNowSeconds(options = {}) {
  const explicit = Number(options.nowSeconds);
  return Number.isFinite(explicit) && explicit > 0 ? explicit : Date.now() / 1000;
}

function commandPaletteItemMtime(item) {
  return commandPaletteNumericTime(item?.mtime || item?.mtime_ns || 0);
}

function commandPaletteRecencyBonus(item, options = {}) {
  const timestamp = commandPaletteItemMtime(item);
  if (!timestamp) return 0;
  const age = Math.max(0, commandPaletteNowSeconds(options) - timestamp);
  return searchRankWeights.recencyCap * Math.pow(0.5, age / searchRankWeights.recencyHalfLifeSeconds);
}

function commandPaletteFocusedRepoRoots(options = {}) {
  if (Array.isArray(options.focusedRepoRoots)) {
    return options.focusedRepoRoots.map(normalizeDirectoryPath).filter(Boolean);
  }
  const focused = currentSessionActionTarget() || focusedPanelItem || focusedTerminal;
  const info = isTmuxSession(focused) ? sessionTranscriptInfo(focused) : null;
  const roots = [
    info?.gitRoot || '',
    focusedRepoRootForSync(info?.selectedPath || info?.gitCwd || '', sessionFilesRepoRoots()),
  ].map(normalizeDirectoryPath).filter(Boolean);
  return Array.from(new Set(roots));
}

function commandPaletteRepoAffinityBonus(item, options = {}) {
  if (item?.category !== 'file') return 0;
  const path = normalizeDirectoryPath(commandPaletteFilePath(item));
  if (!path) return 0;
  return commandPaletteFocusedRepoRoots(options).some(root => pathIsInsideDirectory(path, root))
    ? searchRankWeights.repoAffinity
    : 0;
}

function commandPaletteItemScore(item, query, options = {}) {
  if (item.disabled) return 0;
  // C15 follow-up: the path-mode "Open this folder in Finder" row always sorts to the top (and survives
  // any filter text) so it is the default Enter action while a directory path is typed.
  if (item.pinTop) return 1e9;
  const bonus = commandPaletteDomainPrior(item, options)
    + Number(item.sortBonus || 0)
    + commandPaletteRecentBonus(item)
    + commandPalettePaneExactIdentifierBonus(item, query)
    + commandPalettePaneNameContiguousBonus(item, query, options)
    + commandPaletteFinderAliasBonus(item, query, options)
    + commandPaletteFileNameBonus(item, query)
    + commandPaletteRecencyBonus(item, options)
    + commandPaletteRepoAffinityBonus(item, options);
  if (!String(query || '').trim()) return bonus;
  const base = fuzzySearchScore(query, item.searchFields || [item.label, item.detail, item.group]);
  return Number.isFinite(base) ? base + bonus : base;
}

function commandPalettePaneNameContiguousBonus(item, query, options = {}) {
  if (commandPaletteItemDomain(item) !== 'pane') return 0;
  const tokens = String(query || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
  const label = String(item.label || '').toLowerCase();
  if (!tokens.length || !label || !tokens.every(token => label.includes(token))) return 0;
  const surface = commandPaletteSurface(options);
  return searchRankWeights.paneNameContiguous[surface] || 0;
}

function commandPaletteIdentifierKey(value) {
  return String(value || '').trim().toUpperCase().replace(/^PR[\s#-]*/, '').replace(/^#/, '').replace(/[^A-Z0-9]+/g, '');
}

function commandPaletteIdentifierField(value) {
  return /^(?:#?\d{3,}|PR[\s#-]*\d{3,}|[A-Z][A-Z0-9]+-\d+)$/i.test(String(value || '').trim());
}

function commandPalettePaneExactIdentifierBonus(item, query) {
  if (commandPaletteItemDomain(item) !== 'pane') return 0;
  const needle = commandPaletteIdentifierKey(query);
  if (!needle) return 0;
  return (item.searchFields || []).some(field => commandPaletteIdentifierField(field) && commandPaletteIdentifierKey(field) === needle)
    ? searchRankWeights.paneExactIdentifier
    : 0;
}

function commandPaletteFileNameBonus(item, query) {
  if (item?.category !== 'file') return 0;
  const tokens = String(query || '').trim().split(/\s+/).filter(Boolean);
  if (!tokens.length) return 0;
  const filename = String(item.searchFields?.[0] || item.label || '');
  const canonicalName = fuzzyCanonicalPrefixText(filename);
  if (!canonicalName) return 0;
  let bonus = 0;
  for (const token of tokens) {
    const canonicalToken = fuzzyCanonicalPrefixText(token);
    if (!canonicalToken) continue;
    if (canonicalName.startsWith(canonicalToken)) bonus += searchRankWeights.fileNamePrefix;
    else if (canonicalName.includes(canonicalToken)) bonus += searchRankWeights.fileNameContains;
    else if (Number.isFinite(fuzzySubsequenceScore(token, filename))) bonus += searchRankWeights.fileNameSubsequence;
  }
  return bonus;
}

function commandPaletteFinderAliasBonus(item, query, options = {}) {
  if (item?.targetItem !== fileExplorerItemId) return 0;
  const text = String(query || '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (text.length < 3) return 0;
  const aliases = [t('palette.group.files'), fileExplorerLabel(), 'file', 'files', 'finder', 'file explorer']
    .map(alias => String(alias || '').trim().toLowerCase().replace(/\s+/g, ' '))
    .filter(Boolean);
  if (!aliases.some(alias => alias === text || alias.startsWith(text))) return 0;
  return commandPaletteSurface(options) === 'files'
    ? searchRankWeights.finderAliasFilesMode
    : searchRankWeights.finderAlias;
}

function commandPaletteRecentBonus(item) {
  const key = item.key || `${item.group}:${item.label}`;
  const sequence = commandPaletteRecentKeys.get(key);
  return sequence ? searchRankWeights.recentSelectionBase + sequence : 0;
}

function rememberCommandPaletteItem(item) {
  if (!item || item.disabled) return;
  const key = item.key || `${item.group}:${item.label}`;
  setLimitedMapEntry(commandPaletteRecentKeys, key, ++commandPaletteRecentSequence, commandPaletteRecentKeyLimit);
}

function commandPaletteEffectiveMode() {
  return commandPaletteMode === 'files' && !fileQuickOpenQueryParts().commandMode ? 'files' : 'command';
}

function commandPaletteSearchQuery(query = commandPaletteState.query, mode = commandPaletteMode) {
  if (mode !== 'files') return String(query || '').trim();
  const parts = fileQuickOpenQueryParts(query);
  if (parts.commandMode) return String(query || '').replace(/^>\s*/, '').trim();
  if (parts.symbolMode) return String(query || '').replace(/^@\s*/, '').trim();
  const pathQuery = fileQuickOpenPathQuery(query);
  if (pathQuery.active) return pathQuery.filter;
  return fileQuickOpenSearchText(query);
}

function fileQuickOpenCandidateQueryIdentity(query, root) {
  const pathQuery = fileQuickOpenPathQuery(query);
  if (pathQuery.active) return `path:${pathQuery.directory || '/'}\n${pathQuery.filter}`;
  return `search:${String(root || '')}\n${commandPaletteSearchQuery(query)}`;
}

function commandPalettePlaceholder() {
  // Identical for Cmd-P and Cmd-Shift-P — they differ only in result ordering, not in labels.
  const q = commandPaletteState.query.trim();
  if (q.startsWith('>')) return t('palette.placeholderCommand');
  if (q.startsWith('@')) return t('palette.symbolUnavailable');
  return t('palette.placeholderWithFiles');
}

function commandPaletteLabel() {
  // Identical aria label for both entry points.
  return t('palette.quickOpen');
}

// The one Quick Open freshness sentence, from the one derivation. Empty when every answering root
// vouched for its snapshot.
function commandPaletteFreshnessText() {
  return fileIndexFreshnessMessage(fileQuickOpenState.freshness);
}

function commandPaletteEmptyText() {
  if (fileQuickOpenState.loading) return t('search.searching');
  if (fileQuickOpenState.indexWarming) return t('finder.index.indexing');
  if (commandPaletteState.query.trim().startsWith('@')) return t('palette.symbolUnavailable');
  // "No matches" from a snapshot nobody is updating is a false negative. Say why instead.
  return commandPaletteFreshnessText() || t('palette.noMatches');
}

function commandPaletteStatusText() {
  return [fileQuickOpenState.loading ? t('palette.searchingFiles') : '', commandPaletteFreshnessText()]
    .filter(Boolean)
    .join(' ');
}

function commandPaletteLoadingTextHtml(text) {
  return textWithMovingEllipsisHtml(text, 'command-palette-loading-dots');
}

function commandPaletteStatusHtml() {
  const parts = [];
  if (fileQuickOpenState.loading) parts.push(commandPaletteLoadingTextHtml(t('palette.searchingFiles')));
  // Stale results stay visible and usable below; this line only tells the user what they are looking at.
  const freshness = commandPaletteFreshnessText();
  if (freshness) parts.push(`<span class="command-palette-freshness">${esc(freshness)}</span>`);
  return parts.join('');
}

function commandPaletteResultsHtml(items, query) {
  return items.map((item, index) => `
    <button type="button" class="command-palette-row${index === commandPaletteState.index ? ' active' : ''}" data-command-index="${index}" role="option" aria-selected="${index === commandPaletteState.index ? 'true' : 'false'}"${item.disabled ? ' disabled' : ''}>
      <span class="command-palette-group" title="${esc(item.group)}">${esc(item.group)}</span>
      <span class="command-palette-main"><span class="command-palette-title">${item.iconText ? `<span class="command-palette-file-icon" aria-hidden="true">${esc(item.iconText)}</span>` : ''}<span class="command-palette-label">${commandPaletteItemLabelHtml(item, query)}</span>${(item.viewModes && item.viewModes.length) ? `<span class="command-palette-views">${item.viewModes.map(v => `<span class="chip-base command-palette-view-chip" role="button" tabindex="-1" data-view-item="${esc(v.item)}" data-view-mode="${esc(v.mode)}" title="${esc(t('palette.openView', {view: v.label}))}">${esc(v.label)}</span>`).join('')}</span>` : ''}</span><span class="command-palette-detail">${fuzzyHighlightHtml(query, item.detail || '')}</span></span>
      <span class="command-palette-keybinding">${esc(item.keybinding || '')}</span>
    </button>`).join('');
}

function commandPaletteItemLabelHtml(item, query) {
  if (item?.loading === true) return commandPaletteLoadingTextHtml(item.label);
  return fuzzyHighlightHtml(query, item.label);
}

function ensureCommandPalette() {
  if (commandPaletteState.node) return commandPaletteState.node;
  const node = document.createElement('div');
  node.className = 'app-modal-overlay command-palette';
  node.hidden = true;
  node.innerHTML = `
    <div class="command-palette-dialog" role="dialog" aria-modal="true" aria-label="${esc(t('common.commandPalette'))}">
      <input type="search" class="command-palette-input" placeholder="${esc(t('palette.placeholder'))}" aria-label="${esc(t('palette.placeholder'))}">
      <div class="command-palette-status" aria-live="polite" hidden></div>
      <div class="command-palette-results" role="listbox"></div>
    </div>`;
  node.addEventListener('mousedown', event => {
    if (event.target === node) closeCommandPalette();
  });
  const input = node.querySelector('.command-palette-input');
  input.addEventListener('input', () => {
    commandPaletteState.query = input.value || '';
    commandPaletteState.index = 0;
    renderCommandPaletteResults();
    // Both entry points fetch files on type so a typed query can blend files into either ordering.
    scheduleFileQuickOpenSearch();
  });
  input.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      closeCommandPalette();
    } else if (event.key === 'ArrowDown') {
      event.preventDefault();
      commandPaletteState.index = commandPaletteState.items.length ? (commandPaletteState.index + 1) % commandPaletteState.items.length : 0;
      renderCommandPaletteResults();
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      commandPaletteState.index = commandPaletteState.items.length ? (commandPaletteState.index - 1 + commandPaletteState.items.length) % commandPaletteState.items.length : 0;
      renderCommandPaletteResults();
    } else if (event.key === 'Enter') {
      event.preventDefault();
      invokeCommandPaletteSelection(event);
    }
  });
  node.querySelector('.command-palette-results').addEventListener('click', event => {
    // follow-up: a click on a view chip jumps to THAT view (edit/preview/diff) and closes the
    // palette, instead of the row's default (focus the editor view).
    const chip = event.target.closest('[data-view-item]');
    if (chip && node.contains(chip)) {
      const viewItem = chip.dataset.viewItem;
      closeCommandPalette();
      if (viewItem) selectSession(viewItem, {userInitiated: true});
      return;
    }
    const row = event.target.closest('[data-command-index]');
    if (!row || !node.contains(row)) return;
    commandPaletteState.index = Number(row.dataset.commandIndex || 0);
    invokeCommandPaletteSelection();
  });
  appOverlayRootElement().appendChild(node);
  commandPaletteState.node = node;
  return node;
}

function renderCommandPaletteResults() {
  const node = ensureCommandPalette();
  const dialog = node.querySelector('.command-palette-dialog');
  const input = node.querySelector('.command-palette-input');
  const status = node.querySelector('.command-palette-status');
  const results = node.querySelector('.command-palette-results');
  const query = commandPaletteSearchQuery();
  dialog?.setAttribute('aria-label', commandPaletteLabel());
  if (input) {
    input.placeholder = commandPalettePlaceholder();
    input.setAttribute('aria-label', commandPaletteLabel());
    input.setAttribute('aria-busy', fileQuickOpenState.loading ? 'true' : 'false');
  }
  if (status) {
    const text = commandPaletteStatusText();
    const html = commandPaletteStatusHtml();
    status.hidden = !html;
    status.setAttribute('aria-label', text);
    // Not colour-only: the aria-live region carries the same sentence a sighted user reads, and the
    // stale marker is a class, never a bare colour swap.
    status.classList.toggle('stale', Boolean(commandPaletteFreshnessText()));
    status.innerHTML = html;
  }
  commandPaletteState.items = commandPaletteRankItems(commandPaletteItems(), query).slice(0, 60);
  commandPaletteState.index = Math.min(commandPaletteState.index, Math.max(0, commandPaletteState.items.length - 1));
  if (!commandPaletteState.items.length) {
    results.innerHTML = `<div class="command-palette-empty">${esc(commandPaletteEmptyText())}</div>`;
    return;
  }
  results.innerHTML = commandPaletteResultsHtml(commandPaletteState.items, query);
  results.querySelector('.command-palette-row.active')?.scrollIntoView?.({block: 'nearest'});
}

function openCommandPalette(options = {}) {
  const node = ensureCommandPalette();
  closeAppMenus();
  abortFileQuickOpenSearch();
  commandPaletteMode = options.mode === 'files' ? 'files' : 'command';
  commandPaletteState.targetSlot = String(options.targetSlot || '');
  commandPaletteState.query = '';
  commandPaletteState.index = 0;
  node.hidden = false;
  node.classList.add(CLS.open);
  const input = node.querySelector('.command-palette-input');
  input.value = '';
  // Reset file-search state for BOTH entry points so a typed query can blend files in either mode.
  fileQuickOpenState.root = fileQuickOpenRootForSearch();
  fileQuickOpenState.candidates = [];
  fileQuickOpenState.loading = false;
  fileQuickOpenState.freshness = null;
  fileQuickOpenState.error = '';
  // Only Cmd-P (files priority) shows files on an empty box, so only it searches immediately;
  // Cmd-Shift-P fetches files on the first keystroke (via the input handler).
  if (commandPaletteMode === 'files') scheduleFileQuickOpenSearch({immediate: true});
  renderCommandPaletteResults();
  input.focus({preventScroll: true});
}

function openFileQuickOpen() {
  openCommandPalette({mode: 'files'});
}

function closeCommandPalette() {
  if (!commandPaletteState.node) return;
  commandPaletteState.node.hidden = true;
  commandPaletteState.node.classList.remove(CLS.open);
  if (fileQuickOpenState.debounce) clearTimeout(fileQuickOpenState.debounce);
  fileQuickOpenState.debounce = null;
  abortFileQuickOpenSearch();
}

function focusCommandPaletteTarget(item) {
  const target = item?.targetItem;
  if (!isLayoutItem(target)) return;
  focusPanel(target, {userInitiated: true});
  renderPaneTabStrips();
  requestAnimationFrame(() => focusPanel(target, {userInitiated: true}));
}

async function invokeCommandPaletteSelection(event = null) {
  const item = commandPaletteState.items[commandPaletteState.index];
  if (!item || item.disabled) return;
  rememberCommandPaletteItem(item);
  closeCommandPalette();
  const action = appModifier(event) && item.splitRun ? item.splitRun : item.run;
  await Promise.resolve(action?.());
  focusCommandPaletteTarget(item);
}

function scheduleFileQuickOpenSearch(options = {}) {
  if (fileQuickOpenState.debounce) clearTimeout(fileQuickOpenState.debounce);
  const run = () => {
    fileQuickOpenState.debounce = null;
    const q = commandPaletteState.query.trim();
    if (!q.startsWith('>') && !q.startsWith('@')) refreshFileQuickOpenCandidates(commandPaletteState.query);
  };
  if (options.immediate) run();
  else fileQuickOpenState.debounce = setTimeout(run, fileQuickOpenDebounceMs);
}

function abortFileQuickOpenSearch() {
  if (fileQuickOpenState.abortController) {
    try { fileQuickOpenState.abortController.abort(); } catch (_) {}
  }
  fileQuickOpenState.abortController = null;
  fileQuickOpenState.requestId += 1;
  fileQuickOpenState.loading = false;
  fileQuickOpenState.indexWarming = false;
  fileQuickOpenState.freshness = null;
  fileQuickOpenState.candidateQueryIdentity = '';
  // Retire every cursor: bumping requestId already fences a late delta response, and clearing the map
  // guarantees a search_progress signal after close/reopen cannot pump a stream against a dead palette.
  resetFileQuickOpenDeltaCursors('');
}

// Fold TRUE duplicate file-search hits: same path, same resolved realpath (symlink / overlay
// overlap), or same basename+size (content-mirror copies kept in two repos). Genuinely-different
// same-name files (different size) both survive; unknown-size hits dedupe by path/realpath only.
function dedupeFileSearchResults(files) {
  const seen = new Set();
  const out = [];
  for (const file of Array.isArray(files) ? files : []) {
    const path = file?.path || '';
    if (!path) continue;
    const keys = [`p:${path}`, `r:${file.realpath || path}`];
    if (Number.isFinite(Number(file.size))) keys.push(`n:${basenameOf(path)}|${Number(file.size)}`);
    if (keys.some(key => seen.has(key))) continue;
    keys.forEach(key => seen.add(key));
    out.push(file);
  }
  return out;
}

function fileQuickOpenSearchPayloadResult(payload, searchRoot) {
  return {
    root: normalizeStoredFileExplorerIndexedDir(payload?.root || payload?.root_realpath || searchRoot) || searchRoot,
    searchRoot,
    files: Array.isArray(payload?.files) ? payload.files : [],
    // The opaque baseline cursor the client seeds incremental delta reads with (null when nothing is
    // committed yet — the client re-baselines from the next snapshot once the crawl publishes layer 1),
    // and the canonical realpath whose digest correlates a path-free search_progress signal to this root.
    cursor: payload?.initial_cursor ?? null,
    realpath: String(payload?.root_realpath || payload?.root || searchRoot),
    // This is deliberately data-driven. The UI must not turn an explicit in-progress
    // backend response into a completed empty search just because it has no rows yet.
    indexWarming: payload?.index_state === 'warming' || payload?.index_coverage === 'pending',
    // Same rule for the opposite failure: a snapshot served without a live producer must not read as
    // a current answer. One derivation, shared with the Finder index badge.
    freshness: fileIndexFreshnessFromPayload(payload),
  };
}

// Quick Open blends rows from several roots into one list, so the user cannot tell which row came
// from which snapshot. Report the worst freshness any answering root returned: orphaned before
// stale, then the oldest snapshot.
function fileQuickOpenWorstFreshness(records) {
  const stale = (Array.isArray(records) ? records : []).filter(record => record?.stale === true);
  const rank = record => (record.state === 'orphaned' ? 2 : 1);
  return stale
    .slice()
    .sort((left, right) => (rank(right) - rank(left))
      || ((right.ageSeconds === null ? -1 : right.ageSeconds) - (left.ageSeconds === null ? -1 : left.ageSeconds)))[0] || null;
}

async function refreshFileQuickOpenCandidates(query = '') {
  const root = fileQuickOpenState.root || fileQuickOpenRootForSearch();
  if (!root) return;
  const searchQuery = commandPaletteSearchQuery(query);
  const candidateQueryIdentity = fileQuickOpenCandidateQueryIdentity(query, root);
  const previousCandidateQueryIdentity = fileQuickOpenState.candidateQueryIdentity;
  abortFileQuickOpenSearch();
  fileQuickOpenState.candidateQueryIdentity = candidateQueryIdentity;
  const requestId = ++fileQuickOpenState.requestId;
  fileQuickOpenState.abortController = typeof AbortController === 'function' ? new AbortController() : null;
  const fetchOptions = fileQuickOpenState.abortController ? {signal: fileQuickOpenState.abortController.signal} : {};
  fileQuickOpenState.loading = true;
  fileQuickOpenState.indexWarming = false;
  fileQuickOpenState.freshness = null;
  // Rows retained across a refresh of the same query are still that query's answer, so they stay
  // visible while the reread lands. Rows retained across a changed query are not its ranked answer.
  if (candidateQueryIdentity !== previousCandidateQueryIdentity) fileQuickOpenState.candidates = [];
  // A new snapshot supersedes every prior cursor: a delta response for the old requestId can no longer
  // mutate this palette, and the roots/query it belonged to may have changed entirely.
  resetFileQuickOpenDeltaCursors(searchQuery);
  renderCommandPaletteResults();
  try {
    const pathQuery = fileQuickOpenPathQuery(query);
    if (pathQuery.active) {
      const payload = await apiFetchJson(`/api/fs/list?path=${encodeURIComponent(pathQuery.directory || '/')}`, fetchOptions);
      if (requestId !== fileQuickOpenState.requestId) return;
      fileQuickOpenState.root = payload.path || pathQuery.directory || root;
      const filter = String(pathQuery.filter || '').toLowerCase();
      fileQuickOpenState.candidates = (Array.isArray(payload.entries) ? payload.entries : [])
        .filter(entry => entry?.kind === 'file' || entry?.kind === 'dir')
        .filter(entry => !filter || String(entry.name || '').toLowerCase().includes(filter))
        .map(entry => ({
          name: entry.name || '',
          path: joinDirectoryPath(payload.path || pathQuery.directory || '/', entry.name || ''),
          relative_path: entry.name || '',
          kind: entry.kind || 'file',
          size: entry.size,
          mtime: entry.mtime,
        }));
    } else {
      const searchRoots = fileQuickOpenRootsForSearch(root, commandPaletteSearchQuery(query));
      const results = await Promise.all(searchRoots.map(async searchRoot => {
        try {
          const normalizedRoot = normalizeStoredFileExplorerIndexedDir(searchRoot);
          const recursive = normalizedRoot && fileExplorerDirectoryIsIndexed(normalizedRoot) ? '&recursive=1' : '';
          const payload = await apiFetchJson(`/api/fs/search?root=${encodeURIComponent(searchRoot)}&query=${encodeURIComponent(commandPaletteSearchQuery(query))}&limit=500${recursive}`, fetchOptions);
          return {ok: true, ...fileQuickOpenSearchPayloadResult(payload, searchRoot)};
        } catch (error) {
          return {ok: false, root: searchRoot, error};
        }
      }));
      if (requestId !== fileQuickOpenState.requestId) return;
      const successful = results.filter(result => result.ok);
      if (!successful.length) {
        const firstError = results.find(result => result.error)?.error;
        if (firstError) throw firstError;
        const fallback = t('common.searchFailed');
        fileQuickOpenState.error = userMessageSnapshot('', {key: 'common.searchFailed', params: {}, fallback});
        return;
      }
      fileQuickOpenState.root = root;
      fileQuickOpenState.candidates = dedupeFileSearchResults(
        successful.flatMap(result => result.files.map(file => ({...file, indexed_root: result.root}))),
      );
      // A new or externally indexed root can take a moment to publish its first durable snapshot.
      // The backend explicitly marks that response as warming; it is not a completed empty search.
      fileQuickOpenState.indexWarming = fileQuickOpenState.candidates.length === 0 && successful.some(result => result.indexWarming);
      // Stale rows stay in the list. What changes is that the palette now says they are stale.
      fileQuickOpenState.freshness = fileQuickOpenWorstFreshness(successful.map(result => result.freshness));
      // Seed one delta cursor per answering root so a search_progress signal can stream the crawl's
      // newly-published matches into this list without re-issuing the whole query (steps 6-7).
      seedFileQuickOpenDeltaCursors(successful, requestId);
    }
    fileQuickOpenState.error = '';
  } catch (error) {
    if (requestId !== fileQuickOpenState.requestId) return;
    if (error?.name === 'AbortError') return;
    fileQuickOpenState.candidates = [];
    fileQuickOpenState.indexWarming = false;
    fileQuickOpenState.freshness = null;
    fileQuickOpenState.error = userMessageSnapshot(error, {
      key: 'common.searchFailed',
      params: {},
      fallback: t('common.searchFailed'),
    });
  } finally {
    if (requestId === fileQuickOpenState.requestId) {
      fileQuickOpenState.abortController = null;
      fileQuickOpenState.loading = false;
      renderCommandPaletteResults();
    }
  }
}

// One bounded delta page reads at most this many committed matches per root, matching the server's
// per-response cap (yolomux_lib/filesystem/search.py). It also bounds the blended candidate array so a
// long crawl cannot grow it without limit.
const fileQuickOpenResultLimit = 500;
// A single search_progress signal can fan out to at most this many delta pages per root, so a large
// backlog drains across a few signals instead of one unbounded loop inside a push handler.
const fileQuickOpenDeltaPagesPerSignal = 8;

// Clear every cursor: a new query/root supersedes them, and delta responses for the retired requestId
// must no longer mutate the palette. `deltaQuery` records the search text the surviving cursors serve.
function resetFileQuickOpenDeltaCursors(query = '') {
  fileQuickOpenState.deltaRoots = new Map();
  fileQuickOpenState.deltaQuery = String(query || '');
}

// After a snapshot settles, register one incremental-read cursor per answering root. `cursor` is the
// opaque baseline (null until the root commits its first rows); `scopeId` is the opaque digest a
// path-free search_progress signal carries, so a signal correlates to the exact root it names.
function seedFileQuickOpenDeltaCursors(results, requestId) {
  const deltaRoots = new Map();
  for (const result of Array.isArray(results) ? results : []) {
    const searchRoot = result.searchRoot || result.root;
    if (!searchRoot) continue;
    const normalizedRoot = normalizeStoredFileExplorerIndexedDir(result.root) || String(result.root || '');
    deltaRoots.set(normalizedRoot, {
      searchRoot,
      normalizedRoot,
      cursor: result.cursor ?? null,
      realpath: String(result.realpath || result.root || searchRoot),
      scopeId: fileSearchScopeId(result.realpath || result.root || searchRoot),
      more: false,
      fetching: false,
      requestId,
    });
  }
  fileQuickOpenState.deltaRoots = deltaRoots;
}

// Fold true duplicates the way the snapshot read does, then keep only the best `limit` rows by the ONE
// shared palette score. Ranked here solely to bound the array a delta stream keeps appending to; the
// render path re-ranks for display, so a late high-rank upsert can still move above earlier rows.
function rankAndPruneFileQuickOpenCandidates(candidates, query, limit = fileQuickOpenResultLimit) {
  const deduped = dedupeFileSearchResults(candidates);
  if (deduped.length <= limit) return deduped;
  const scoreOf = file => commandPaletteItemScore(
    fileQuickOpenItem(file.path || '', {
      kind: file.kind || 'file',
      relativePath: file.relative_path || file.name || '',
      sortBonus: file.uploaded === true ? -500 : 0,
    }),
    query,
    {surface: 'files'},
  );
  return deduped
    .map((file, index) => ({file, index, score: scoreOf(file)}))
    .sort((left, right) => (right.score - left.score) || (left.index - right.index))
    .slice(0, limit)
    .map(entry => entry.file);
}

// Apply one root's committed delta page to the blended candidate set: an `upsert` replaces (or adds)
// the row for its path, a `delete` removes it. Cross-root isolation is inherent — every path is
// absolute and each change is stamped with the root that produced it, so one root's delete can never
// drop another root's row. Returns the deduped, bounded candidate array.
function mergeFileQuickOpenChanges(candidates, changes, indexedRoot) {
  const byPath = new Map();
  const order = [];
  for (const file of Array.isArray(candidates) ? candidates : []) {
    const path = file?.path || '';
    if (!path) continue;
    if (!byPath.has(path)) order.push(path);
    byPath.set(path, file);
  }
  for (const change of Array.isArray(changes) ? changes : []) {
    const path = String(change?.path || '');
    if (!path) continue;
    const operation = String(change?.operation || 'upsert');
    if (operation === 'delete') {
      if (byPath.delete(path)) {
        const at = order.indexOf(path);
        if (at >= 0) order.splice(at, 1);
      }
      continue;
    }
    if (!byPath.has(path)) order.push(path);
    byPath.set(path, {
      name: change.name || basenameOf(path),
      path,
      relative_path: change.relative_path || change.name || '',
      kind: change.kind || 'file',
      size: change.size,
      mtime: change.mtime,
      realpath: change.realpath || path,
      uploaded: change.uploaded === true,
      indexed_root: indexedRoot,
    });
  }
  return order.map(path => byPath.get(path)).filter(Boolean);
}

// Ingest one delta HTTP payload for `normalizedRoot`. A response for a superseded requestId is dropped
// (a stale query can never mutate a newer palette). A rebase_required verdict is reported to the
// caller for the one explicit snapshot-repair path; otherwise the changes merge in, dedupe, rerank
// once, prune to the limit, and the root's cursor + `more` advance. Returns the delta status.
function ingestFileQuickOpenDeltaPayload(normalizedRoot, requestId, payload) {
  if (requestId !== fileQuickOpenState.requestId) return {applied: false, stale: true};
  const deltaRoot = fileQuickOpenState.deltaRoots.get(normalizedRoot);
  if (!deltaRoot || deltaRoot.requestId !== requestId) return {applied: false, stale: true};
  if (payload?.rebase_required) {
    deltaRoot.more = false;
    return {applied: false, rebase: true, reason: String(payload.reason || '')};
  }
  const changes = Array.isArray(payload?.changes) ? payload.changes : [];
  deltaRoot.cursor = payload?.cursor ?? deltaRoot.cursor;
  deltaRoot.more = payload?.more === true;
  if (changes.length) {
    fileQuickOpenState.candidates = rankAndPruneFileQuickOpenCandidates(
      mergeFileQuickOpenChanges(fileQuickOpenState.candidates, changes, deltaRoot.normalizedRoot),
      fileQuickOpenState.deltaQuery,
    );
    // A delta that lands rows clears the transient "Indexing…" state: the palette now has committed
    // matches, so it must not keep claiming an empty warming index.
    if (fileQuickOpenState.candidates.length) fileQuickOpenState.indexWarming = false;
    renderCommandPaletteResults();
  }
  return {applied: true, more: deltaRoot.more, changed: changes.length};
}

// Incremental delta streaming is live only while a files-mode palette is open on a real search query;
// a signal that arrives after close/reopen or in command mode must pump nothing.
function fileQuickOpenDeltasActive() {
  if (!commandPaletteState.node || commandPaletteState.node.hidden) return false;
  if (commandPaletteEffectiveMode() !== 'files') return false;
  return Boolean(commandPaletteSearchQuery(commandPaletteState.query));
}

// Read ONE bounded committed-delta page for a root through the same authenticated /api/fs/search
// endpoint, appending `&cursor=`. Deltas deliberately do NOT share the snapshot's AbortController:
// they outlive the initial fetch and are fenced by requestId inside ingest instead of by abort.
async function fetchFileQuickOpenDeltaPage(deltaRoot) {
  const requestId = deltaRoot.requestId;
  const query = fileQuickOpenState.deltaQuery;
  const recursive = fileExplorerDirectoryIsIndexed(deltaRoot.normalizedRoot) ? '&recursive=1' : '';
  const url = `/api/fs/search?root=${encodeURIComponent(deltaRoot.searchRoot)}`
    + `&query=${encodeURIComponent(query)}&limit=${fileQuickOpenResultLimit}${recursive}`
    + `&cursor=${encodeURIComponent(deltaRoot.cursor)}`;
  const payload = await apiFetchJson(url);
  return ingestFileQuickOpenDeltaPayload(deltaRoot.normalizedRoot, requestId, payload);
}

// Drain a root's committed backlog after a progress signal: one in-flight request per root
// (`fetching`), bounded pages per signal, looping while the server says `more`. A root with no
// baseline cursor yet (its first layer just published) or a `rebase_required` verdict falls back to
// the ONE explicit full-snapshot repair path rather than a second incremental path.
async function pumpFileQuickOpenDeltasForRoot(normalizedRoot) {
  const deltaRoot = fileQuickOpenState.deltaRoots.get(normalizedRoot);
  if (!deltaRoot || deltaRoot.fetching) return;
  if (!fileQuickOpenDeltasActive()) return;
  if (deltaRoot.cursor === null || deltaRoot.cursor === undefined) {
    requeryOpenFileQuickOpenForIndexChange({force: true});
    return;
  }
  deltaRoot.fetching = true;
  try {
    for (let page = 0; page < fileQuickOpenDeltaPagesPerSignal; page += 1) {
      const current = fileQuickOpenState.deltaRoots.get(normalizedRoot);
      if (!current || current.requestId !== deltaRoot.requestId) return;
      if (!fileQuickOpenDeltasActive()) return;
      let status;
      try {
        status = await fetchFileQuickOpenDeltaPage(current);
      } catch (error) {
        console.warn('quick-open delta read failed', error);
        return;
      }
      if (status.stale) return;
      if (status.rebase) {
        requeryOpenFileQuickOpenForIndexChange({force: true});
        return;
      }
      if (!status.more) return;
    }
  } finally {
    const current = fileQuickOpenState.deltaRoots.get(normalizedRoot);
    if (current) current.fetching = false;
  }
}

// The search_progress bus handler: a path-free {scope_id, generation, revision, coverage} frame. Pump
// deltas only for the root whose opaque digest the frame names — a signal for any other root (or a
// closed palette) does nothing, so one client's crawl never re-queries another root's palette.
function handleFileSearchProgressSignal(payload) {
  const scopeId = String(payload?.scope_id || '');
  if (!scopeId || !fileQuickOpenDeltasActive()) return;
  for (const deltaRoot of fileQuickOpenState.deltaRoots.values()) {
    if (deltaRoot.scopeId !== scopeId) continue;
    pumpFileQuickOpenDeltasForRoot(deltaRoot.normalizedRoot)
      .catch(error => console.warn('quick-open delta pump failed', error));
  }
}

// The ONE explicit repair path for Quick Open: a full snapshot re-query that re-baselines every cursor.
// The incremental delta stream (steps 6-7) handles the ordinary crawl-advance case; this fires only for
// the cases a cursor cannot bridge — a `rebase_required` verdict, a root that has no committed baseline
// yet, or an authoritative background-refresh completion that rebuilt the index underneath the palette.
// Guarded to the open files-mode palette with a live search query. It yields to an in-flight search
// unless `force` (an authoritative completion event) is set, so a signal cannot abort a search
// mid-flight into a stuck spinner.
function requeryOpenFileQuickOpenForIndexChange({force = false} = {}) {
  if (!commandPaletteState.node || commandPaletteState.node.hidden) return;
  if (commandPaletteEffectiveMode() !== 'files') return;
  if (!commandPaletteSearchQuery(commandPaletteState.query)) return;
  if (!force && fileQuickOpenState.loading) return;
  refreshFileQuickOpenCandidates(commandPaletteState.query)
    .catch(error => console.warn('quick-open index-change refresh failed', error));
}

function shouldNotifyTransitionKey(key) {
  const defaultTransitions = [STATE_KEY.needsInput, STATE_KEY.needsApproval, STATE_KEY.blocked];
  const configured = initialSetting('notifications.notify_transitions', defaultTransitions);
  const transitions = Array.isArray(configured) ? configured : defaultTransitions;
  return transitions.includes(key);
}

function shouldNotifyState(state) {
  return shouldNotifyTransitionKey(state.key);
}

function notificationLifecycleKeys(values) {
  const source = Array.isArray(values) ? values : [values];
  return new Set(source.map(value => String(value || '').trim()).filter(Boolean));
}

function attentionNotificationLifecycleKey(key) {
  const value = String(key || '').trim();
  return value ? `attention:${value}` : '';
}

function agentTransitionNotificationLifecycleKey(session, key) {
  const target = String(session || '').trim();
  const value = String(key || '').trim();
  return target && value ? `agent-transition:${target}:${value}` : '';
}

function workingAgentTransitionNotificationCoalesceKey(session) {
  const target = String(session || '').trim();
  return target ? `agent-transition:${target}` : '';
}

function notificationLifecycleKeysIntersect(left, right) {
  for (const key of left || []) {
    if (right.has(key)) return true;
  }
  return false;
}

function dismissNotificationsForLifecycleKeys(keys) {
  const requested = notificationLifecycleKeys(keys);
  if (!requested.size) return 0;
  let dismissed = 0;
  for (const [id, record] of [...toastRecords.entries()]) {
    if (!notificationLifecycleKeysIntersect(record.lifecycleKeys, requested)) continue;
    removeAttentionAlert(id);
    dismissed += 1;
  }
  for (const notifications of browserNotificationsByTarget.values()) {
    for (const notification of [...notifications]) {
      if (!notificationLifecycleKeysIntersect(browserNotificationLifecycleKeys.get(notification), requested)) continue;
      notification.close?.();
      dismissed += 1;
    }
  }
  return dismissed;
}

function sendBrowserNotification(title, options = {}) {
  const targetItem = String(options.targetItem || options.session || '').trim();
  if (targetItem && notificationTargetIsFocused(targetItem)) return null;
  const {onClick, session, targetItem: _targetItem, url, lifecycleKeys, ...notificationOptions} = options;
  const icon = notificationOptions.icon === undefined
    ? renderBrowserAppIconDataUrl({size: 192, showBadge: false})
    : '';
  const notification = new Notification(title, icon ? {icon, ...notificationOptions} : notificationOptions);
  browserNotificationLifecycleKeys.set(notification, notificationLifecycleKeys(lifecycleKeys));
  if (targetItem) {
    if (!browserNotificationsByTarget.has(targetItem)) browserNotificationsByTarget.set(targetItem, new Set());
    browserNotificationsByTarget.get(targetItem).add(notification);
    notification.onclose = () => {
      const notifications = browserNotificationsByTarget.get(targetItem);
      notifications?.delete(notification);
      if (!notifications?.size) browserNotificationsByTarget.delete(targetItem);
    };
  }
  notification.onclick = () => {
    window.focus();
    notification.close?.();
    if (typeof onClick === 'function') onClick();
    else if (session) selectSession(session, {userInitiated: true});
    // a watched-PR notification opens the PR (no session to focus); safe blank-target open.
    else if (url) {
      try { window.open(url, '_blank', 'noopener,noreferrer'); } catch (_) {}
    }
  };
  return notification;
}

function setToastCountdown(node, durationMs) {
  if (!node) return;
  if (!Number.isFinite(durationMs)) {
    node.style.removeProperty('--toast-countdown-duration');
    return;
  }
  node.style.setProperty('--toast-countdown-duration', `${Math.max(1, durationMs)}ms`);
}

// This is the sole product-policy owner for transient notifications.  Producers supply content
// and an optional target/action; they do not decide whether an event is pane-local, global, OS
// deliverable, suppressible, or coalesced.  That separation keeps a new notification from quietly
// becoming a third routing model.
const notificationEventDefinitions = Object.freeze({
  sessionAttention: Object.freeze({scope: 'global', target: 'session', system: true, suppressFocused: true, priority: 'attention', coalesce: true}),
  agentAttention: Object.freeze({scope: 'global', target: 'session', system: true, suppressFocused: true, priority: 'attention', coalesce: true, persistent: true}),
  agentDone: Object.freeze({scope: 'global', target: 'session', system: true, suppressFocused: true, priority: 'done', coalesce: true}),
  terminalConnection: Object.freeze({scope: 'global', target: 'session', system: false, suppressFocused: true, priority: 'connection', coalesce: true}),
  chatMessage: Object.freeze({scope: 'global', target: 'chat', system: true, suppressFocused: true, priority: 'message', coalesce: true}),
  yoagentJob: Object.freeze({scope: 'global', target: 'session', system: true, suppressFocused: true, priority: 'job', coalesce: true}),
  watchedPullRequest: Object.freeze({scope: 'global', system: true, priority: 'pullRequest', coalesce: true}),
  update: Object.freeze({scope: 'global', system: false, priority: 'update', coalesce: true}),
  indexCoverage: Object.freeze({scope: 'global', system: false, priority: 'warning', coalesce: true, dismissOnly: true}),
  statsResolution: Object.freeze({scope: 'global', system: false, priority: 'warning', coalesce: true}),
  startupTip: Object.freeze({scope: 'global', system: false, priority: 'tip', coalesce: true}),
  notificationTest: Object.freeze({scope: 'global', system: true, priority: 'test', coalesce: true}),
  // Uploads retain their stacked file-result renderer, but that renderer is still dispatched
  // through this policy row so its pane scope cannot become a second routing decision.
  uploadResult: Object.freeze({scope: 'pane', target: 'session', system: false, priority: 'operation', deliver: ({target, payload}) => deliverUploadResultNotification(target, payload.uploadPayload, payload.inserted === true)}),
  fileTransfer: Object.freeze({scope: 'pane', target: 'operation', system: false, priority: 'operation'}),
  fileOpen: Object.freeze({scope: 'pane', target: 'finder', system: false, priority: 'operation'}),
  yoloRules: Object.freeze({scope: 'pane', target: 'preferences', system: false, priority: 'operation'}),
  previewOpen: Object.freeze({scope: 'pane', target: 'operation', system: false, priority: 'operation'}),
});

function notificationEventDefinition(type) {
  return notificationEventDefinitions[type] || null;
}

function notificationEventTarget(definition, payload = {}) {
  if (definition?.target === 'chat') return chatItemId;
  if (definition?.target === 'finder') return fileExplorerItemId;
  if (definition?.target === 'preferences') return prefsItemId;
  return String(payload.targetItem || payload.session || payload.item || '').trim();
}

function notificationEventContainer(definition, target) {
  return definition?.scope === 'pane' ? displayToastContainer(target) : attentionAlerts;
}

function notificationEventKey(type, definition, target, payload = {}) {
  if (payload.coalesceKey) return String(payload.coalesceKey);
  if (definition?.coalesce !== true) return '';
  return `${type}:${target || String(payload.key || '')}`;
}

function dismissCoalescedToast(key) {
  if (!key) return;
  for (const [id, record] of toastRecords.entries()) {
    if (record.node?.dataset?.toastCoalesceKey === key) removeAttentionAlert(id);
  }
}

function emitNotification(type, payload = {}) {
  const definition = notificationEventDefinition(type);
  if (!definition) throw new Error(`unknown notification event: ${type}`);
  const target = notificationEventTarget(definition, payload);
  const key = notificationEventKey(type, definition, target, payload);
  if (definition.deliver) return {inApp: definition.deliver({target, payload}), system: null, suppressed: false};
  const targetItem = definition.suppressFocused === true ? target : '';
  if (targetItem && notificationTargetIsFocused(targetItem)) {
    dismissNotificationsForTarget(targetItem);
    return {inApp: null, system: null, suppressed: true};
  }
  let inApp = null;
  if (payload.inApp !== false && notificationDeliveryEnabled('inApp')) {
    dismissCoalescedToast(key);
    inApp = showToast(payload.title || '', payload.lines || payload.body || '', {
      container: notificationEventContainer(definition, target),
      targetItem,
      onClick: payload.onClick,
      onClose: payload.onClose,
      actions: payload.actions,
      className: payload.className,
      countdownMs: definition.persistent === true ? (payload.countdownMs || 4 * 60 * 60 * 1000) : payload.countdownMs,
      persistent: definition.dismissOnly === true || payload.persistent === true,
      lifecycleKeys: payload.lifecycleKeys,
    });
    if (inApp) {
      inApp.dataset.toastEvent = type;
      inApp.dataset.toastPriority = definition.priority;
      if (target) inApp.dataset.toastTargetItem = target;
      if (key) inApp.dataset.toastCoalesceKey = key;
    }
  }
  let system = null;
  if (definition.system === true && payload.system !== false && notificationDeliveryEnabled('system') && 'Notification' in window && Notification.permission === 'granted') {
    system = sendBrowserNotification(payload.systemTitle || payload.title || '', {
      body: payload.systemBody || payload.body || toastTextLines(payload.lines || '').join('\n'),
      tag: payload.systemTag || key || `${type}:${Date.now()}`,
      renotify: payload.renotify === true,
      targetItem,
      session: payload.session,
      onClick: payload.onClick,
      url: payload.url,
      lifecycleKeys: payload.lifecycleKeys,
    });
  }
  return {inApp, system, suppressed: false};
}

// Upload and attention/status messages share this renderer. Keep visual differences out of call sites.
function ensureToastShell(node, options = {}) {
  let bodyNode = node.querySelector('.toast-body');
  if (!bodyNode) {
    node.innerHTML = `
      <div class="toast-header">
        <div class="toast-title"></div>
        <div class="toast-control-row">
          <button type="button" class="toast-keep" data-toast-keep aria-label="${esc(options.keepLabel || t('toast.keepAlert'))}">${esc(t('toast.keep'))}</button>
          <button type="button" class="toast-close" data-toast-close aria-label="${esc(options.closeLabel || t('toast.closeAlert'))}">X</button>
        </div>
      </div>
      <div class="toast-body"></div>
      <div class="toast-actions"></div>`;
    bodyNode = node.querySelector('.toast-body');
  }
  const titleNode = node.querySelector('.toast-title');
  if (titleNode) titleNode.textContent = options.title || '';
  const actionsNode = node.querySelector('.toast-actions');
  if (actionsNode) {
    actionsNode.replaceChildren(...(options.actions || []));
    actionsNode.hidden = !actionsNode.children.length;
  }
  const closeButton = node.querySelector('[data-toast-close]');
  if (closeButton) {
    closeButton.onclick = event => {
      event.stopPropagation();
      options.onClose?.();
    };
  }
  const keepButton = node.querySelector('[data-toast-keep]');
  if (keepButton) {
    keepButton.onclick = event => {
      event.stopPropagation();
      node.classList.add('kept');
      keepButton.hidden = true;
      options.onKeep?.();
    };
  }
  return bodyNode;
}

function renderToastLines(bodyNode, lines, options = {}) {
  bodyNode.replaceChildren();
  for (const item of summarizeToastLines(lines, options)) {
    const lineText = typeof item === 'object' && item !== null ? item.text : item;
    const countdownMs = typeof item === 'object' && item !== null ? item.countdownMs : options.countdownMs;
    const line = document.createElement('div');
    line.className = 'toast-line';
    setToastCountdown(line, countdownMs || toastDurationMs);
    if (typeof item?.render === 'function') item.render(line);
    else line.textContent = lineText;
    bodyNode.appendChild(line);
  }
}

function normalizeToastLine(item, options = {}) {
  const objectItem = typeof item === 'object' && item !== null;
  const text = objectItem ? item.text : item;
  return {
    text: compactToastText(text),
    countdownMs: objectItem ? item.countdownMs : options.countdownMs,
    render: objectItem && typeof item.render === 'function' ? item.render : null,
  };
}

function compactToastText(text) {
  const value = String(text || '').replace(/\s+/g, ' ').trim();
  if (value.length <= toastMaxLineChars) return value;
  return `${value.slice(0, toastMaxLineChars - 3)}...`;
}

function summarizeToastLines(lines, options = {}) {
  const normalized = (Array.isArray(lines) ? lines : toastTextLines(lines)).map(item => normalizeToastLine(item, options));
  if (normalized.length <= toastMaxLines) return normalized;
  const visible = normalized.slice(0, toastMaxLines - 1);
  const hidden = normalized.slice(toastMaxLines - 1);
  const countdownValues = hidden.map(item => item.countdownMs).filter(Number.isFinite);
  visible.push({
    text: t('common.more', {count: hidden.length}),
    countdownMs: countdownValues.length ? Math.max(...countdownValues) : options.countdownMs,
  });
  return visible;
}

function toastTextLines(text) {
  const lines = String(text || '').split('\n').map(line => line.trim()).filter(Boolean);
  return lines.length ? lines : [''];
}

function clearToastRemovalTimer(id) {
  const record = toastRecords.get(id);
  if (!record?.timer) return;
  clearTimeout(record.timer);
  record.timer = null;
}

function scheduleToastRemoval(id, node, remainingMs) {
  const delay = Math.max(1, Number(remainingMs) || 1);
  let record = toastRecords.get(id);
  if (!record) {
    record = {node, timer: null};
    toastRecords.set(id, record);
  } else {
    record.node = node;
  }
  clearToastRemovalTimer(id);
  node.dataset.toastRemainingMs = String(delay);
  node.dataset.toastRemovalStartedAt = String(Date.now());
  record.timer = window.setTimeout(() => removeAttentionAlert(id), delay);
}

function pauseToastRemoval(id, node, reason) {
  if (!node || node.classList.contains('kept')) return;
  node.dataset[`toastPause${reason}`] = 'true';
  if (node.classList.contains('toast-countdown-paused')) return;
  const remainingMs = Number(node.dataset.toastRemainingMs);
  const startedAt = Number(node.dataset.toastRemovalStartedAt);
  const elapsedMs = Number.isFinite(startedAt) ? Math.max(0, Date.now() - startedAt) : 0;
  node.dataset.toastRemainingMs = String(Math.max(1, (Number.isFinite(remainingMs) ? remainingMs : toastDurationMs) - elapsedMs));
  clearToastRemovalTimer(id);
  node.classList.add('toast-countdown-paused');
}

function resumeToastRemoval(id, node, reason) {
  if (!node || node.classList.contains('kept')) return;
  delete node.dataset[`toastPause${reason}`];
  if (node.dataset.toastPausePointer || node.dataset.toastPauseFocus || !node.classList.contains('toast-countdown-paused')) return;
  node.classList.remove('toast-countdown-paused');
  scheduleToastRemoval(id, node, Number(node.dataset.toastRemainingMs));
}

function showToast(title, lines, options = {}) {
  const targetItem = String(options.targetItem || '').trim();
  if (targetItem && notificationTargetIsFocused(targetItem)) {
    dismissNotificationsForTarget(targetItem);
    return null;
  }
  const container = options.container || attentionAlerts;
  if (!container) return null;
  const id = ++attentionAlertSequence;
  const node = document.createElement('div');
  node.className = options.className || 'attention-alert toast';
  node.dataset.alertId = String(id);
  toastRecords.set(id, {node, timer: null, lifecycleKeys: notificationLifecycleKeys(options.lifecycleKeys)});
  if (options.persistent === true) {
    node.dataset.toastPersistent = 'true';
    node.classList.add('kept');
  }
  if (targetItem) node.dataset.toastTargetItem = targetItem;
  const bodyNode = ensureToastShell(node, {
    title,
    closeLabel: options.closeLabel,
    keepLabel: options.keepLabel,
    actions: options.actions,
    onKeep: () => {
      clearToastRemovalTimer(id);
      options.onKeep?.();
    },
    onClose: () => {
      options.onClose?.();
      removeAttentionAlert(id);
    },
  });
  const toastLines = Array.isArray(lines) ? lines : (lines && typeof lines === 'object' ? [lines] : toastTextLines(lines));
  renderToastLines(bodyNode, toastLines, {
    countdownMs: options.persistent === true ? Infinity : (options.countdownMs || toastDurationMs),
  });
  if (options.persistent === true) {
    const keepButton = node.querySelector('[data-toast-keep]');
    if (keepButton) keepButton.hidden = true;
  }
  node.addEventListener('click', event => {
    if (event.target.closest('[data-toast-close], .toast-actions')) return;
    options.onClick?.();
  });
  node.addEventListener('pointerenter', () => pauseToastRemoval(id, node, 'Pointer'));
  node.addEventListener('pointerleave', () => resumeToastRemoval(id, node, 'Pointer'));
  node.addEventListener('focusin', () => pauseToastRemoval(id, node, 'Focus'));
  node.addEventListener('focusout', event => {
    if (!node.contains(event.relatedTarget)) resumeToastRemoval(id, node, 'Focus');
  });
  container.appendChild(node);
  while (container.children.length > 5) {
    const first = Array.from(container.children).find(child => child.dataset.toastPersistent !== 'true');
    if (!first) break;
    removeAttentionAlert(Number(first.dataset.alertId || 0));
  }
  // remove the toast when its countdown bar finishes — honor options.countdownMs (the
  // reconnect toast animates over that, not the fixed toastDurationMs) so the bar and removal align.
  if (options.persistent !== true) scheduleToastRemoval(id, node, options.countdownMs || toastDurationMs);
  return node;
}

function startupHelperCatalog() {
  return [
    {title: t('startupHelper.tip.dragFiles.title'), lines: [t('startupHelper.tip.dragFiles.body')]},
    {title: t('startupHelper.tip.imageDrag.title'), lines: [t('startupHelper.tip.imageDrag.body')]},
    {title: t('startupHelper.tip.yoagentQuestions.title'), lines: [t('startupHelper.tip.yoagentQuestions.body')]},
    {title: t('startupHelper.tip.yoloAutoApprove.title'), lines: [t('startupHelper.tip.yoloAutoApprove.body')]},
    {title: t('startupHelper.tip.yoloRules.title'), lines: [t('startupHelper.tip.yoloRules.body')]},
    {title: t('startupHelper.tip.diffView.title'), lines: [t('startupHelper.tip.diffView.body')]},
    {title: t('startupHelper.tip.finderSync.title'), lines: [t('startupHelper.tip.finderSync.body')]},
    {title: t('startupHelper.tip.finderReload.title'), lines: [t('startupHelper.tip.finderReload.body')]},
    {title: t('startupHelper.tip.editorDiff.title'), lines: [t('startupHelper.tip.editorDiff.body')]},
    {title: t('startupHelper.tip.notifications.title'), lines: [t('startupHelper.tip.notifications.body')]},
    {title: t('startupHelper.tip.watchedPrs.title'), lines: [t('startupHelper.tip.watchedPrs.body')]},
    {title: t('startupHelper.tip.quickOpen.title'), lines: [t('startupHelper.tip.quickOpen.body')]},
    {title: t('startupHelper.tip.markdownPreview.title'), lines: [t('startupHelper.tip.markdownPreview.body')]},
    {title: t('common.rsyncLargeFiles'), lines: [t('startupHelper.tip.largeUpload.body')]},
  ];
}

function readStartupHelperIndex(count) {
  const parsed = Number(storageGet(startupHelperIndexStorageKey, '0'));
  if (!Number.isFinite(parsed) || count <= 0) return 0;
  return Math.max(0, Math.floor(parsed)) % count;
}

function writeStartupHelperIndex(index) {
  storageSet(startupHelperIndexStorageKey, Math.max(0, Math.floor(Number(index) || 0)));
}

function startupHelperWrappedIndex(index, count) {
  if (!Number.isFinite(Number(index)) || count <= 0) return 0;
  return ((Math.floor(Number(index)) % count) + count) % count;
}

function startupHelperNavigationGroup(index, total, showRelativeTip) {
  const group = document.createElement('span');
  group.className = 'startup-helper-nav';
  group.setAttribute('role', 'group');
  group.setAttribute('aria-label', t('startupHelper.navigation'));
  group.append(
    makeButton({
      label: '<',
      className: 'startup-helper-nav-button',
      title: t('startupHelper.action.previous'),
      ariaLabel: t('startupHelper.action.previous'),
      onClick: event => {
        event.stopPropagation();
        showRelativeTip(-1);
      },
    }),
    makeButton({
      label: '>',
      className: 'startup-helper-nav-button',
      title: t('startupHelper.action.next'),
      ariaLabel: t('startupHelper.action.next'),
      onClick: event => {
        event.stopPropagation();
        showRelativeTip(1);
      },
    }),
  );
  return group;
}

function startupHelperPromptAction(title) {
  const text = String(title || '').trim();
  if (!text) return t('startupHelper.defaultAction');
  return text.charAt(0).toLowerCase() + text.slice(1);
}

function startupHelperPromptTitle(index, total, tip) {
  return t('startupHelper.titleTemplate', {
    index: index + 1,
    total,
    action: startupHelperPromptAction(tip?.title),
  });
}

function closeStartupHelperToast(node) {
  removeAttentionAlert(Number(node?.dataset?.alertId || 0));
}

function showStartupHelperTip(options = {}) {
  if (readOnlyMode || !startupHelpersEnabled) return null;
  const tips = startupHelperCatalog();
  if (!tips.length) return null;
  const index = readStartupHelperIndex(tips.length);
  const tip = tips[index];
  writeStartupHelperIndex((index + 1) % tips.length);
  let node = null;
  const showRelativeTip = delta => {
    closeStartupHelperToast(node);
    writeStartupHelperIndex(startupHelperWrappedIndex(index + delta, tips.length));
    showStartupHelperTip({manual: true});
  };
  const navAction = startupHelperNavigationGroup(index, tips.length, showRelativeTip);
  const offAction = makeButton({
    label: t('startupHelper.action.offForever'),
    onClick: event => {
      event.stopPropagation();
      startupHelpersEnabled = false;
      closeStartupHelperToast(node);
      saveSettingsPatch(settingPatch('general.startup_tips', false))
        .then(() => { statusEl.textContent = t('startupHelper.status.disabled'); })
        .catch(error => { statusErr(localizedHtml('status.settingsSaveFailed', {error: userMessageText(error, t('common.requestFailed'))})); refreshSettings({force: true}); });
    },
  });
  node = emitNotification('startupTip', {
    title: startupHelperPromptTitle(index, tips.length, tip), lines: tip.lines,
    className: 'attention-alert toast startup-helper-toast',
    actions: [navAction, offAction],
    countdownMs: 45000,
    coalesceKey: 'startup-tip',
  }).inApp;
  if (node) node.dataset.toastKind = 'startup-helper';
  return node;
}

function scheduleStartupHelperTip() {
  if (readOnlyMode || !startupHelpersEnabled) return;
  if (location.protocol === 'file:') return;
  window.setTimeout(() => {
    showStartupHelperTip();
  }, 1400);
}

function displayToastContainer(session) {
  const sessionContainer = session ? document.getElementById(`panel-toasts-${session}`) : null;
  if (sessionContainer && sessionContainer.isConnected !== false) return sessionContainer;
  const candidates = [focusedPanelItem, ...activeSessions];
  for (const item of candidates) {
    const node = item ? document.getElementById(`panel-toasts-${item}`) : null;
    if (node && node.isConnected !== false) return node;
  }
  return document.querySelector('.panel-toast-stack') || attentionAlerts;
}

function notificationTargetIsFocused(item) {
  const target = String(item || '').trim();
  if (!target || document.visibilityState !== 'visible' || !itemIsActivePaneTab(target)) return false;
  // A status render can briefly blur xterm even though the user remains on this pane. The shared
  // logical active item survives that DOM churn, so notifications about the pane being viewed are
  // already acknowledged and must not appear inside that same pane.
  return focusedPanelItem === target || focusedTerminal === target;
}

function compactNotificationTitle(scope, message, options = {}) {
  const suffix = String(message || '').trim();
  const label = String(scope || '').trim();
  const product = t('app.documentTitle');
  if (options.inApp === true) return suffix || label;
  if (!label) return suffix ? `${product} ${suffix}` : product;
  return suffix ? `${product}[${label}] ${suffix}` : `${product}[${label}]`;
}

function sessionNotificationScope(session) {
  const label = sessionLabel(session);
  const desc = sessionTabDescription(session, transcriptMetadataState.payload.sessions?.[session]);
  return desc ? `${label} ${desc}` : label;
}

function sessionNotificationTitle(session, state, options = {}) {
  return compactNotificationTitle(sessionNotificationScope(session), state?.label || '', options);
}

function hostNotificationTitle(message, options = {}) {
  return compactNotificationTitle(serverHostname, message, options);
}

function attentionToastAgent(session, state) {
  const agent = state?.attentionAgent;
  if (agentWindowIsAttentionState(agent?.state)) {
    return {agent, item: state?.attentionAgentItem || null};
  }
  const info = transcriptMetadataState.payload.sessions?.[session];
  const summary = typeof sessionAgentWindowStatusSummary === 'function'
    ? sessionAgentWindowStatusSummary(session, info, autoApproveStates.get(session))
    : null;
  return agentWindowIsAttentionState(summary?.agent?.state) ? summary : null;
}

function attentionToastReason(state, agent) {
  const reason = String(state?.reason || '').trim();
  const label = String(agent?.window_label || agent?.window || '').trim();
  const prefix = label ? `${label}:` : '';
  return prefix && reason.startsWith(prefix) ? reason.slice(prefix.length).trim() : reason;
}

function attentionToastTitle(session, state) {
  const attention = attentionToastAgent(session, state);
  const agent = attention?.agent;
  const windowLabel = String(agent?.window_label || agent?.window || '').trim();
  return windowLabel ? `[${sessionLabel(session)}] ${windowLabel}: ${state?.label || ''}` : sessionNotificationTitle(session, state, {inApp: true});
}

async function focusAgentToastTarget(session, agent) {
  await selectSession(session, {userInitiated: true});
  const windowIndex = agentWindowIndex(agent);
  if (windowIndex === null) return;
  activateTmuxWindowFromUserAction(session, windowIndex, t('terminal.window.title', {name: windowIndex}));
}

function agentToastTargetLine(session, agent, options = {}) {
  const reason = String(options.reason || '').trim();
  if (!agent || typeof tmuxWindowButtonHtml !== 'function' || typeof tmuxPaneTabTokenHtml !== 'function') return reason;
  const visibleName = String(agent.window_label || agentWindowCanonicalLabel(agent.window_index ?? agent.window, agent.kind, agent.kind)).trim();
  if (!visibleName) return reason;
  return {
    text: reason,
    render: line => {
      line.classList.add('toast-line--attention');
      const marker = document.createElement('span');
      marker.className = 'attention-toast-controls';
      const info = transcriptMetadataState.payload.sessions?.[session];
      const auto = autoApproveStates.get(session)?.enabled === true;
      const status = options.state || sessionState(session, info);
      const tabHtml = tmuxPaneTabTokenHtml(session, {
        tag: 'span',
        action: false,
        active: true,
        info,
        state: status,
        auto,
        classes: ['attention-toast-session-tab'],
      });
      const windowHtml = tmuxWindowButtonHtml({
        tag: 'span',
        visibleName,
        showNumberLabel: false,
        active: true,
        ariaPressed: false,
        attrs: ['role="img"'],
        classes: ['attention-toast-agent-button'],
        agentStatus: agent,
        agentKey: agent.kind,
        session,
        activityAnimate: false,
        activityIconHtml: agentWindowActivityIconHtml(agent.kind, agent.state, agentWindowIdleSeconds(agent), {
          ...agentWindowActivityOptionsForStatus(agent, session),
          item: options.item || undefined,
          animate: false,
          statusBeforeAgent: true,
        }),
      });
      marker.innerHTML = `${tabHtml}${windowHtml}`;
      const text = document.createElement('span');
      text.className = 'attention-toast-reason';
      text.textContent = reason;
      line.append(marker, text);
    },
  };
}

function attentionToastLine(session, state) {
  const attention = attentionToastAgent(session, state);
  return agentToastTargetLine(session, attention?.agent, {
    reason: attentionToastReason(state, attention?.agent),
    item: attention?.item,
  });
}

function workingAgentTransitionNotificationTarget(agentKey, tone, options = {}) {
  const kind = typeof agentWindowKind === 'function' ? agentWindowKind(agentKey) : String(agentKey || '').trim().toLowerCase();
  const state = tone === 'attention' ? STATE_KEY.needsInput : STATE_KEY.idle;
  return {
    ...options,
    kind,
    state,
    window_index: options.window_index ?? options.windowIndex ?? options.window,
    window_label: options.window_label || options.windowLabel || '',
  };
}

function showAttentionAlert(session, state) {
  const node = emitNotification('sessionAttention', {
    session,
    title: attentionToastTitle(session, state),
    lines: attentionToastLine(session, state),
    body: state.reason || state.label || '',
    systemTitle: sessionNotificationTitle(session, state),
    systemTag: `yolomux:session:${session}:state:${stateSignature(state)}`,
    coalesceKey: `session-attention:${session}`,
    system: false,
    onClick: () => {
      dismissSessionToasts(session);
      void focusAgentToastTarget(session, attentionToastAgent(session, state)?.agent);
    },
  }).inApp;
  if (node) {
    node.dataset.toastSession = session;
    node.dataset.toastKind = 'attention';
  }
}

function dismissNotificationsForTarget(item, options = {}) {
  const target = String(item || '').trim();
  if (!target) return;
  const kind = String(options.kind || '');
  for (const [id, record] of toastRecords.entries()) {
    const node = record.node;
    if (node.dataset.toastTargetItem !== target && node.dataset.toastSession !== target) continue;
    if (!kind || node.dataset.toastKind === kind) removeAttentionAlert(id);
  }
  const notifications = browserNotificationsByTarget.get(target);
  if (notifications) {
    for (const notification of [...notifications]) notification.close?.();
    browserNotificationsByTarget.delete(target);
  }
}

// Opening a notification's target is an acknowledgement, not merely a visual dismissal.  Producers
// own their durable cursor/state update; this shared hook keeps every route into that target aligned.
function acknowledgeNotificationTarget(item) {
  if (String(item || '').trim() === chatItemId && typeof chatAcknowledge === 'function') {
    void chatAcknowledge();
  }
}

function dismissSessionToasts(session, options = {}) {
  dismissNotificationsForTarget(session, options);
}

function dismissAttentionAlertsForSession(session) {
  dismissSessionToasts(session, {kind: 'attention'});
}

function attentionAlreadyVisible(session) {
  return notificationTargetIsFocused(session);
}

function removeAttentionAlert(id) {
  const node = toastRecords.get(id)?.node || null;
  clearToastRemovalTimer(id);
  node?.remove();
  toastRecords.delete(id);
}

function sendTestNotification(options = {}) {
  const inApp = options.inApp === true || (options.inApp === undefined && notificationDeliveryEnabled('inApp'));
  const system = options.system === true || (options.system === undefined && notificationDeliveryEnabled('system'));
  try {
    emitNotification('notificationTest', {
      title: hostNotificationTitle(t('notify.testToastTitle'), {inApp: true}),
      body: t('notify.testBody'), systemTitle: t('notify.testTitle', {host: serverHostname}),
      systemBody: t('notify.browserTestBody'), coalesceKey: 'notification-test', inApp, system,
    });
    postEvent(null, 'notification_test_sent', 'notification test sent', {hostname: serverHostname});
  } catch (error) {
    statusErr(localizedHtml('status.notificationFailed', {error}));
    postEvent(null, 'notification_error', `notification test failed: ${error}`, {hostname: serverHostname});
  }
}

function eventMessageForState(session, state) {
  return `${sessionLabel(session)} ${state.label}: ${state.reason}`;
}

function stateSignature(state) {
  return `${state.key}:${state.reason || ''}`;
}

function trackSessionStateChanges() {
  for (const session of sessions.filter(isTmuxSession)) {
    const state = sessionState(session, transcriptMetadataState.payload.sessions?.[session]);
    const record = sessionStatusRecord(session, true);
    const previous = record?.state || null;
    const signature = stateSignature(state);
    if (record) record.state = {key: state.key, reason: state.reason, signature};
    if (!stateTrackingReady || previous == null || previous.signature === signature) continue;
    postEvent(session, 'state_changed', eventMessageForState(session, state), {
      from: previous.key,
      from_reason: previous.reason,
      to: state.key,
      reason: state.reason,
    });
  }
  stateTrackingReady = true;
}

const workingAgentTransitionNotificationDescriptors = Object.freeze({
  attention: Object.freeze({settingPath: 'notifications.notify_working_attention', defaultEnabled: true, copyKey: 'attention'}),
  cooldown: Object.freeze({settingPath: 'notifications.notify_working_done', defaultEnabled: false, copyKey: 'done'}),
});
const workingAgentTransitionNotificationConfirmMs = 5000;

function workingAgentTransitionNotificationDescriptor(tone) {
  return workingAgentTransitionNotificationDescriptors[tone] || null;
}

function workingAgentTransitionNotificationEnabled(tone) {
  const descriptor = workingAgentTransitionNotificationDescriptor(tone);
  return descriptor ? boolSetting(descriptor.settingPath, descriptor.defaultEnabled) : false;
}

function workingAgentTransitionNotificationPendingMap(session, create = false) {
  return sessionStatusRecord(session, create)?.workingAgentTransitionNotificationPending || null;
}

function clearWorkingAgentTransitionNotificationPending(session, key) {
  const pendingMap = workingAgentTransitionNotificationPendingMap(session);
  const pending = pendingMap?.get(key);
  if (!pending) return false;
  clearTimeout(pending.timer);
  pendingMap.delete(key);
  return true;
}

function clearWorkingAgentTransitionNotificationSession(session) {
  const record = sessionStatusRecord(session);
  if (!record) return;
  for (const pending of record.workingAgentTransitionNotificationPending.values()) clearTimeout(pending.timer);
  record.workingAgentTransitionNotificationPending.clear();
  record.workingAgentNotificationTones.clear();
}

function confirmWorkingAgentTransitionNotification(key, pending) {
  const session = pending.session;
  const record = sessionStatusRecord(session);
  if (record?.workingAgentTransitionNotificationPending.get(key) !== pending) return false;
  record.workingAgentTransitionNotificationPending.delete(key);
  if (record.workingAgentNotificationTones.get(key) !== pending.tone) return false;
  return maybeNotifyWorkingAgentTransition(pending.session, pending.kind, pending.tone, pending.options);
}

function scheduleWorkingAgentTransitionNotification(session, kind, key, tone, options = {}) {
  const pendingMap = workingAgentTransitionNotificationPendingMap(session, true);
  if (!pendingMap) return false;
  if (!workingAgentTransitionNotificationEnabled(tone) || !notificationDeliveryEnabled()) {
    clearWorkingAgentTransitionNotificationPending(session, key);
    return false;
  }
  const existing = pendingMap.get(key);
  if (existing?.tone === tone) return false;
  clearWorkingAgentTransitionNotificationPending(session, key);
  const pending = {session, kind, tone, options: {...options}, timer: 0};
  pending.timer = setTimeout(
    () => confirmWorkingAgentTransitionNotification(key, pending),
    workingAgentTransitionNotificationConfirmMs,
  );
  pendingMap.set(key, pending);
  return true;
}

function rekeyWorkingAgentTransitionNotificationSession(oldSession, newSession) {
  const record = sessionStatusRecord(oldSession);
  if (!record) return;
  for (const pending of record.workingAgentTransitionNotificationPending.values()) pending.session = newSession;
}

function maybeNotifyWorkingAgentTransition(session, agentKey, tone, options = {}) {
  const descriptor = workingAgentTransitionNotificationDescriptor(tone);
  if (!session || !descriptor || !workingAgentTransitionNotificationEnabled(tone) || !notificationDeliveryEnabled()) return false;
  const marker = tone === 'attention'
    ? String(options.attentionKey || options.attentionSignature || '').trim()
    : String(options.stoppedAt || '').trim();
  if (!marker) return false;
  const target = workingAgentTransitionNotificationTarget(agentKey, tone, options);
  const targetKey = typeof agentWindowActivityTransitionKey === 'function'
    ? agentWindowActivityTransitionKey(agentKey, {...target, session: ''})
    : `${target.window_index ?? target.window ?? ''}:${agentKey}`;
  const key = `agent-window-transition:${targetKey}:${tone}:${marker}`;
  const coalesceKey = workingAgentTransitionNotificationCoalesceKey(session);
  const now = Date.now();
  if (notificationTargetIsFocused(session)) {
    recordSessionNotificationSent(session, key, now);
    dismissNotificationsForTarget(session);
    postEvent(session, 'agent_window_transition_notification_suppressed_visible', 'Notification suppressed because the session is visible', {agent: target.kind, tone});
    return false;
  }
  const throttleMs = Math.max(0, numberSetting('notifications.throttle_seconds', 60)) * 1000;
  const lastSent = sessionNotificationLastSentAt(session, key);
  if (now - lastSent < throttleMs) return false;
  recordSessionNotificationSent(session, key, now);
  const kind = typeof agentWindowKind === 'function' ? agentWindowKind(agentKey) : '';
  const agent = kind ? agentLabel(kind) : t('common.agentLabel');
  const title = t(`notify.working.${descriptor.copyKey}.title`);
  const body = t(`notify.working.${descriptor.copyKey}.body`, {agent, session: sessionLabel(session)});
  if (notificationDeliveryEnabled('inApp')) {
    const lifecycleKeys = [
      attentionNotificationLifecycleKey(options.acknowledgementKey),
      agentTransitionNotificationLifecycleKey(session, options.transitionKey),
    ];
    const node = emitNotification(tone === 'attention' ? 'agentAttention' : 'agentDone', {
      session, title, lines: agentToastTargetLine(session, target, {reason: body}), body,
      systemTitle: title, systemTag: `yolomux:${coalesceKey}`, renotify: true,
      coalesceKey,
      lifecycleKeys,
      onClick: () => {
        dismissSessionToasts(session);
        void focusAgentToastTarget(session, target);
      },
      system: false,
    }).inApp;
    if (node) {
      node.dataset.toastSession = session;
      node.dataset.toastKind = 'working-agent-transition';
    }
  }
  postEvent(session, 'agent_window_transition_notification', body, {agent: kind, tone});
  if (!notificationDeliveryEnabled('system') || !('Notification' in window) || Notification.permission !== 'granted') return true;
  try {
    emitNotification(tone === 'attention' ? 'agentAttention' : 'agentDone', {
      session, title, body, systemTitle: title, systemTag: `yolomux:${coalesceKey}`, renotify: true, inApp: false,
      lifecycleKeys: [
        attentionNotificationLifecycleKey(options.acknowledgementKey),
        agentTransitionNotificationLifecycleKey(session, options.transitionKey),
      ],
    });
    postEvent(session, 'notification_sent', body, {agent: kind, tone});
  } catch (error) {
    postEvent(session, 'notification_error', `notification failed: ${error}`, {agent: kind, tone});
  }
  return true;
}

function workingAgentNotificationTone(agent) {
  const state = String(agent?.state || '').trim();
  if (typeof agentWindowIsWorkingState === 'function' && agentWindowIsWorkingState(state)) return STATE_KEY.working;
  if (typeof agentWindowIsAttentionState === 'function' && agentWindowIsAttentionState(state)) return 'attention';
  const stoppedAt = Number(agent?.working_stopped_ts || agent?.workingStoppedTs || 0);
  return Number.isFinite(stoppedAt) && stoppedAt > 0 ? 'cooldown' : '';
}

function workingAgentFinishedRecently(agent, nowSeconds = Date.now() / 1000) {
  const stoppedAt = Number(agent?.working_stopped_ts || agent?.workingStoppedTs || 0);
  if (!Number.isFinite(stoppedAt) || stoppedAt <= 0) return false;
  const freshnessSeconds = Math.max(1, Number(workflowTransitionGlowSeconds) || 0);
  return nowSeconds >= stoppedAt && nowSeconds - stoppedAt <= freshnessSeconds;
}

function workingAgentTransitionSnapshot(session, agent) {
  const kind = typeof agentWindowKind === 'function' ? agentWindowKind(agent?.kind) : '';
  if (!session || !kind || typeof agentWindowActivityTransitionKey !== 'function') return null;
  const options = typeof agentWindowActivityOptionsForStatus === 'function'
    ? agentWindowActivityOptionsForStatus(agent, session, {scheduleRefresh: false})
    : {...agent, session};
  const key = agentWindowActivityTransitionKey(kind, {...options, session: ''});
  if (!key) return null;
  const tone = workingAgentNotificationTone(agent);
  const toneMap = sessionStatusRecord(session, true)?.workingAgentNotificationTones;
  return {agent, kind, options, key, tone, previousTone: toneMap?.get(key) || ''};
}

// Notifications are driven by one authoritative auto-approve payload, never by a surface renderer.
// A hidden tab, a rebuilt Info Bar, or a late popover must not change whether a live green->red/yellow
// transition notifies the user. Both exit tones share one confirmation timer so detector flicker and
// auto-approve turnarounds return to working without producing a false popup.
function reconcileWorkingAgentTransitionNotifications(session, payload = {}) {
  if (!session || typeof agentWindowActivityTransitionKey !== 'function') return 0;
  const record = sessionStatusRecord(session, true);
  const toneMap = record?.workingAgentNotificationTones;
  const pendingMap = record?.workingAgentTransitionNotificationPending;
  if (!toneMap || !pendingMap) return 0;
  const rows = typeof sessionAgentWindowStatusPayloads === 'function'
    ? sessionAgentWindowStatusPayloads(session, transcriptMetadataState.payload.sessions?.[session], payload)
    : typeof agentWindowPayloadRows === 'function'
      ? agentWindowPayloadRows(payload.agent_windows)
      : [];
  const nextKeys = new Set();
  let notified = 0;
  for (const agent of rows) {
    const transition = workingAgentTransitionSnapshot(session, agent);
    if (!transition) continue;
    const {kind, options, key, tone, previousTone} = transition;
    nextKeys.add(key);
    if (tone === STATE_KEY.working) {
      dismissNotificationsForLifecycleKeys([agentTransitionNotificationLifecycleKey(session, key)]);
    }
    const shouldNotify = (previousTone === STATE_KEY.working && (tone === 'attention' || tone === 'cooldown'))
      // `working_stopped_ts` is written by the server only after it observes working->idle. Use that
      // durable transition proof when a browser refresh missed its transient green snapshot.
      || (tone === 'cooldown' && previousTone === '' && workingAgentFinishedRecently(agent));
    if (shouldNotify) {
      const acknowledgementKey = typeof agentWindowActivityAcknowledgementKey === 'function'
        ? agentWindowActivityAcknowledgementKey(
            kind,
            tone === 'attention' ? agent.state : 'cooldown',
            options,
            tone === 'attention' ? (options.attention_signature || options.screen_text) : Number(options.working_stopped_ts || 0),
          )
        : '';
      notified += Number(scheduleWorkingAgentTransitionNotification(session, kind, key, tone, {
        ...agent,
        ...options,
        acknowledgementKey,
        attentionKey: acknowledgementKey,
        transitionKey: key,
        attentionSignature: options.attention_signature || options.screen_text,
        stoppedAt: Number(options.working_stopped_ts || 0),
      }));
    } else if (pendingMap.get(key)?.tone !== tone) {
      clearWorkingAgentTransitionNotificationPending(session, key);
    }
    toneMap.set(key, tone);
  }
  for (const key of toneMap.keys()) {
    if (nextKeys.has(key)) continue;
    toneMap.delete(key);
    clearWorkingAgentTransitionNotificationPending(session, key);
  }
  return notified;
}

// a stable snapshot of the watched-PR status dimensions we diff for notifications.
function watchedPrStatusSnapshot(pr) {
  return {
    merged: pullRequestIsMerged(pr),
    ci: pullRequestCiState(pr),
    review: pullRequestReviewDecision(pr),
  };
}

// Pure transition detector: which notifiable transitions fired between two status snapshots. Merged
// (→ merged), CI flipped into failing, review decision changed. No previous snapshot → no transition
// (first sighting only records a baseline, so a load with already-merged/failing PRs does not storm).
function watchedPrTransitionKeys(prev, next) {
  const keys = [];
  if (!prev || !next) return keys;
  if (!prev.merged && next.merged) keys.push('pr-merged');
  if (prev.ci !== 'failing' && next.ci === 'failing') keys.push('pr-ci-failing');
  if (prev.review !== next.review && next.review) keys.push('pr-review');
  return keys;
}

// Diff each watched PR's new status against the last-seen one and notify on a transition.
function notifyWatchedPrTransitions(prs) {
  for (const pr of Array.isArray(prs) ? prs : []) {
    const ref = String(pr?.ref || (pr?.number ? `#${pr.number}` : ''));
    if (!ref) continue;
    const next = watchedPrStatusSnapshot(pr);
    const record = watchedPrRecord(ref, true);
    const prev = record.lastStatus;
    record.lastStatus = next;
    for (const key of watchedPrTransitionKeys(prev, next)) {
      let message;
      if (key === 'pr-merged') message = t('notify.pr.merged', {ref});
      else if (key === 'pr-ci-failing') message = t('notify.pr.ciFailing', {ref});
      else message = t('notify.pr.review', {ref, decision: pullRequestApprovalLabel(next.review) || next.review});
      maybeNotifyWatchedPr(ref, key, message, pr.url);
    }
  }
}

// Fire a watched-PR transition through the shared notification channel: an in-page toast (clicks open
// the PR) + a browser Notification, gated by notificationsEnabled + notify_transitions, deduped and
// throttled by notifications.throttle_seconds via the bounded watched-PR record owner.
function maybeNotifyWatchedPr(ref, key, message, url) {
  if (!notificationDeliveryEnabled()) return;
  if (!shouldNotifyTransitionKey(key)) return;
  const signature = `watched-pr:${ref}:${key}`;
  const now = Date.now();
  const throttleMs = Math.max(0, (Number(initialSetting('notifications.throttle_seconds', 60)) || 0) * 1000);
  const record = watchedPrRecord(ref, true);
  const lastSent = record.notificationLastSent.get(key) || 0;
  if (now - lastSent < throttleMs) return;
  setLimitedMapEntry(record.notificationLastSent, key, now, notificationLastSentLimit);
  if (notificationDeliveryEnabled('inApp')) emitNotification('watchedPullRequest', {title: message, lines: [ref], body: ref, url, coalesceKey: signature, onClick: () => { try { window.open(url, '_blank', 'noopener,noreferrer'); } catch (_) {} }, system: false});
  postEvent(null, 'watched_pr_alert', message, {ref, transition: key});
  if (!notificationDeliveryEnabled('system') || !('Notification' in window) || Notification.permission !== 'granted') return;
  try {
    emitNotification('watchedPullRequest', {title: message, body: ref, systemTitle: hostNotificationTitle(message), systemTag: signature, renotify: true, url, inApp: false});
    postEvent(null, 'watched_pr_notification', message, {ref, transition: key});
  } catch (error) {
    postEvent(null, 'watched_pr_notification_error', `notification failed: ${error}`, {ref, transition: key});
  }
}

function updateTopbarMetrics() {
  if (!topbar) return;
  const height = Math.ceil(topbar.getBoundingClientRect().height || 38);
  document.documentElement?.style?.setProperty('--topbar-height', `${height}px`);
  scheduleTopbarActionCapacity();
}

function scheduleTopbarMetricsUpdate() {
  requestAnimationFrame(updateTopbarMetrics);
}

function bindTopbarMetrics() {
  updateTopbarMetrics();
  if (topbarResizeObserver || !topbar || !window.ResizeObserver) return;
  topbarResizeObserver = new ResizeObserver(updateTopbarMetrics);
  topbarResizeObserver.observe(topbar);
}

function flushScheduledTabStripOverflowChecks() {
  const strips = Array.from(tabStripOverflowCheckSet);
  tabStripOverflowCheckSet.clear();
  tabStripOverflowCheckFrame = null;
  for (const strip of strips) {
    if (!strip?.isConnected) continue;
    strip.classList.toggle('tabs-overflowing', strip.scrollWidth > strip.clientWidth + 1);
  }
}

function scheduleTabStripOverflowCheck(strip) {
  if (!strip) return;
  if (strip === sessionButtons || strip.classList?.contains('pane-tabs')) {
    strip.classList.remove('tabs-overflowing');
    scheduleTopbarMetricsUpdate();
    return;
  }
  strip.classList.remove('tabs-overflowing');
  tabStripOverflowCheckSet.add(strip);
  if (tabStripOverflowCheckFrame) return;
  tabStripOverflowCheckFrame = requestAnimationFrame(flushScheduledTabStripOverflowChecks);
}

function scheduleAllTabStripOverflowChecks() {
  scheduleTabStripOverflowCheck(sessionButtons);
  for (const strip of document.querySelectorAll('.pane-tabs')) {
    scheduleTabStripOverflowCheck(strip);
  }
}

function normalizedSessionOrder(nextSessions) {
  if (!Array.isArray(nextSessions)) return null;
  const next = [];
  for (const session of nextSessions) {
    if (typeof session === 'string' && session && !next.includes(session)) next.push(session);
  }
  return next;
}

function setSessionOrder(next) {
  const authoritative = normalizedSessionOrder(next) || [];
  sessions = sessionOrderIncludingPending(authoritative);
  visibleSessions = sessions.slice(0, maxSessionTabs);
  layoutItems = computeLayoutItems();
}

function updateSessionList(nextSessions, options = {}) {
  const next = normalizedSessionOrder(nextSessions);
  if (!next) return false;
  pruneExpiredPendingTmuxSessions();
  if (options.clearConfirmedPending === true) clearConfirmedPendingTmuxSessions(next);
  const effectiveNext = sessionOrderIncludingPending(next);
  const changed = effectiveNext.length !== sessions.length || effectiveNext.some((session, index) => session !== sessions[index]);
  if (!changed) {
    layoutItems = computeLayoutItems();
    return false;
  }
  const removedSessions = visibleSessions.filter(session => !effectiveNext.includes(session));
  setSessionOrder(effectiveNext);
  layoutSlots = normalizeLayoutSlotsForViewport(layoutSlots, {
    preserveRemovedItems: removedSessions,
    preserveRemovedSlots: true,
  });
  activeSessions = sessionsFromLayout();
  clearFocusForInactiveLayout();
  updateActiveSessionParam();
  return true;
}

function applyLayoutSlots(nextSlots, options = {}) {
  const previousActive = activeSessions.slice(), previousItems = new Set(paneItems(layoutSlots));
  const completionGeneration = Number(options.completionGeneration || runtimeState.layoutMutationSnapshot().pending) || 0;
  runtimeState.consumePendingLayoutMutation(completionGeneration);
  // A later layout mutation means the saved Fill workspace snapshot is no longer a valid restore
  // target. The fill/restore transaction explicitly opts out while it applies its own snapshot.
  if (options.preserveFilledWorkspaceLayout !== true) filledWorkspaceLayout = null;
  // detect a same-shape change (reorder/activate/move/replace) so we can skip the full
  // topbar + grid teardown. Compute the shape signature before and after the slot reassignment.
  const prevShape = layoutShapeSignature(layoutSlots);
  layoutSlots = normalizeLayoutSlotsForViewport(nextSlots, {
    focusSession: options.focusSession,
    preserveMissingSidePane: options.preserveMissingSidePane === true,
    preservePlaceholderSlots: options.preservePlaceholderSlots === true,
  });
  cleanupRemovedDynamicLayoutItems(previousItems, new Set(paneItems(layoutSlots)));
  activeSessions = sessionsFromLayout();
  clearFocusForInactiveLayout();
  updateActiveSessionParam();
  requestLayoutRender({
    previousActive,
    prevShape,
    nextShape: layoutShapeSignature(layoutSlots),
    options: {
      prune: options.prune,
      sessionButtons: options.sessionButtons,
      deferDockviewLoad: options.deferDockviewLoad,
      deferDockviewLoadAfterPaint: options.deferDockviewLoadAfterPaint,
      completionGeneration,
    },
    reason: 'applyLayoutSlots',
    forceFull: options.forceFull === true,
  });
  if (!dockviewLayoutActive()) {
    for (const session of activeSessions.filter(isTmuxSession)) ensureTerminalRunning(session);
  }
  // do NOT re-poll the server on a pure client-side layout change. refreshTranscripts()
  // fires 3..(3+N) network round-trips and a second full render wave gated behind their latency —
  // the bulk of the "moving a tab takes several seconds" delay. Freshness is already covered by the
  // metadata interval (50_editor_settings_runtime.js), and the session-changing mutations
  // (create/rename/kill, 70_layout_actions.js) call refreshTranscripts() at their own sites.
  const statsActivated = typeof jsDebugStatsLayoutItemsVisible === 'function'
    && !jsDebugStatsLayoutItemsVisible(previousActive)
    && jsDebugStatsLayoutItemsVisible(activeSessions);
  if (typeof syncJsDebugStatsPolling === 'function') syncJsDebugStatsPolling({pollNow: statsActivated});
  if (autoFocusCanFollowCursor() && options.focusSession && activeSessions.includes(options.focusSession)) {
    setTimeout(() => focusPanel(options.focusSession), 80);
  } else if (options.message && activeSessions.length) {
    showLayoutStatus(options.message, options.messageKind || '');
  } else {
    resetLayoutStatusSurface();
    updateStatus();
  }
  if (clientPushCanSupplyData() && typeof syncServerWatchRoots === 'function') syncServerWatchRoots();
}

function cleanupRemovedDynamicLayoutItems(previousItems, nextItems) {
  for (const item of previousItems || []) {
    if (!dynamicVirtualLayoutItems.has(item) || nextItems?.has(item)) continue;
    const panel = panelNodes.get(item);
    if (panel) removePanelForItem(item);
    else tabTypeForItem(item)?.cleanup?.(item, null);
    dynamicVirtualLayoutItems.delete(item);
    paneViewState.delete(item);
    tabLastActivatedAt.delete(item);
  }
  syncFileLayoutItems();
}

function layoutRenderRequest(request = {}) {
  return {
    previousActive: Array.isArray(request.previousActive) ? request.previousActive.slice() : [],
    prevShape: String(request.prevShape || ''),
    nextShape: String(request.nextShape || ''),
    options: request.options || {},
    reason: request.reason || '',
    forceFull: request.forceFull === true,
  };
}

function layoutCompletionGeneration(...values) {
  return values.reduce((highest, value) => {
    const generation = Number(value);
    return Number.isSafeInteger(generation) && generation > highest ? generation : highest;
  }, 0);
}

function completeLayoutMutationGeneration(value) {
  const generation = Number(value);
  const accepted = runtimeState.completeLayoutMutation(generation);
  const detail = {
    generation: Number.isSafeInteger(generation) ? generation : 0,
    accepted,
    reason: accepted ? 'completed' : Number.isSafeInteger(generation) ? 'already_settled' : 'invalid_generation',
  };
  window.dispatchEvent(new CustomEvent('yolomux:layout-mutation-complete', {detail}));
  return detail;
}

const layoutMutationCompletionDeadlineMs = 5000;

function layoutMutationCompletionError(generation, reason) {
  const error = new Error(`layout mutation ${generation} was not completed: ${reason}`);
  error.name = 'LayoutMutationCompletionError';
  error.code = 'layout_mutation_not_completed';
  error.generation = generation;
  error.reason = reason;
  return error;
}

function waitForLayoutMutationCompletion(value, options = {}) {
  const generation = Number(value);
  if (!Number.isSafeInteger(generation) || generation <= 0) {
    return Promise.reject(layoutMutationCompletionError(generation, 'invalid_generation'));
  }
  if (runtimeState.layoutMutationCompletedGeneration >= generation) {
    return Promise.resolve(generation);
  }
  let complete = null;
  const completion = new Promise((resolve, reject) => {
    complete = event => {
      if (Number(event?.detail?.generation || 0) < generation) return;
      if (event?.detail?.accepted === false && Number(event.detail.generation) === generation) {
        reject(layoutMutationCompletionError(generation, String(event.detail.reason || 'refused')));
        return;
      }
      resolve(generation);
    };
    window.addEventListener('yolomux:layout-mutation-complete', complete);
  });
  const timeoutMs = Math.max(1, Number(options.timeoutMs) || layoutMutationCompletionDeadlineMs);
  return promiseWithDeadline(completion, timeoutMs, `layout mutation ${generation}`).finally(() => {
    if (complete) window.removeEventListener('yolomux:layout-mutation-complete', complete);
  });
}

function beginLayoutMutationCompletion(state = null) {
  if (Number.isSafeInteger(state?.completionGeneration) && state.completionGeneration > 0) {
    return state.completionGeneration;
  }
  const generation = runtimeState.beginLayoutMutation();
  if (state) state.completionGeneration = generation;
  return generation;
}

function mergePendingLayoutRender(current, next) {
  if (!current) return next;
  const options = {...current.options, ...next.options};
  const completionGeneration = layoutCompletionGeneration(
    current.options.completionGeneration,
    next.options.completionGeneration,
  );
  if (completionGeneration > 0) options.completionGeneration = completionGeneration;
  else delete options.completionGeneration;
  return layoutRenderRequest({
    previousActive: current.previousActive,
    prevShape: current.prevShape,
    nextShape: next.nextShape || current.nextShape,
    options,
    reason: [current.reason, next.reason].filter(Boolean).join('+'),
    forceFull: current.forceFull || next.forceFull,
  });
}

function layoutRenderCanUseCheap(request) {
  return !request.forceFull
    && request.prevShape === request.nextShape
    && (grid.querySelector('.drop-slot[data-slot]') || dockviewLayoutActive());
}

function performLayoutRender(request = {}) {
  const renderRequest = layoutRenderRequest(request);
  const previousActive = renderRequest.previousActive;
  if (layoutRenderCanUseCheap(renderRequest)) {
    // Cheap path: the tree shape is unchanged. Swap only the slots whose active item changed and
    // reconcile the (already keyed) tab strips — no innerHTML='', no topbar rebuild.
    syncActivePanelsInPlace(previousActive);
    // Dockview's in-place sync already refreshes its tab renderers and mounted panels. Running the
    // generic strip pass again repeats that same work during every active-tab adoption.
    if (!dockviewLayoutActive()) {
      renderPaneTabStrips();
      syncPanelVisibility(previousActive);
      renderAutoApproveButtons();
    }
    completeLayoutMutationGeneration(renderRequest.options.completionGeneration);
    return;
  }
  if (renderRequest.options.sessionButtons !== false) renderSessionButtons();
  renderPanels(previousActive, {
    prune: renderRequest.options.prune,
    deferDockviewLoad: renderRequest.options.deferDockviewLoad,
    deferDockviewLoadAfterPaint: renderRequest.options.deferDockviewLoadAfterPaint,
    completionGeneration: renderRequest.options.completionGeneration,
  });
}

function requestLayoutRender(request = {}) {
  const renderRequest = layoutRenderRequest(request);
  if (dragState.item != null || pendingLayoutRenderFrame) {
    pendingLayoutRender = mergePendingLayoutRender(pendingLayoutRender, renderRequest);
    return;
  }
  performLayoutRender(renderRequest);
}

function flushPendingLayoutRender(reason = 'drag-flush') {
  if (!pendingLayoutRender || pendingLayoutRenderFrame) return;
  const flush = () => {
    pendingLayoutRenderFrame = 0;
    const renderRequest = pendingLayoutRender;
    pendingLayoutRender = null;
    if (renderRequest) requestLayoutRender({...renderRequest, reason});
  };
  if (typeof requestAnimationFrame !== 'function') {
    flush();
    return;
  }
  pendingLayoutRenderFrame = requestAnimationFrame(flush);
}

function updateActiveSessionParam() {
  const params = new URLSearchParams(location.search);
  params.delete('active');
  params.delete('sessions');
  params.delete('layout');
  params.delete('tabs');
  params.delete('finder');
  params.delete('state');
  const queryParts = [];
  const inactiveItems = inactiveTabItems();
  if (activeSessions.length || inactiveItems.length) {
    if (activeSessions.length) {
      queryParts.push(`sessions=${activeSessions.map(readableItemParam).join(',')}`);
    }
    queryParts.push(`layout=${layoutParamValue(layoutSlots)}`);
    const tabs = layoutTabsParamValue(layoutSlots);
    if (tabs) queryParts.push(`tabs=${tabs}`);
    const state = layoutUrlStateParamValue();
    if (state) queryParts.push(`state=${state}`);
  }
  const remaining = params.toString();
  if (remaining) queryParts.push(remaining);
  const query = queryParts.join('&');
  const nextUrl = `${location.pathname}${query ? `?${query}` : ''}${location.hash}`;
  history.replaceState(null, '', nextUrl);
  return nextUrl;
}

function syncInitialLayoutUrl() {
  schedulePendingLayoutUrlStateApply();
  updateActiveSessionParam();
}
function menuCommand(label, action, options = {}) {
  // Checked is presentation state, not a request to keep a menu mounted. Navigation commands such
  // as File -> Finder may be checked yet must still dismiss the menu after they act; real repeated
  // toggles opt into keepOpen explicitly at their definition.
  return {type: 'command', label, action, ...options};
}

// A paired row keeps closely related choices on one compact line while preserving independent buttons,
// keyboard navigation, disabled state, and accessibility for each action.
function menuCommandPair(primary, secondary, options = {}) {
  return {type: 'command-pair', primary, secondary, ...options};
}

function menuCommandRow(items, options = {}) {
  return {type: 'command-row', items, ...options};
}

function menuSubmenu(label, items, options = {}) {
  return {type: 'submenu', label, items, ...options};
}

function menuSeparator() {
  return {type: 'separator'};
}

function menuNumberSetting(path, label, options = {}) {
  return {type: 'number-setting', path, label, ...options};
}

function menuGroups(...groups) {
  const items = [];
  for (const group of groups) {
    const commands = (Array.isArray(group) ? group : [group]).filter(Boolean);
    if (!commands.length) continue;
    if (items.length) items.push(menuSeparator());
    items.push(...commands);
  }
  return items;
}

function compareLocalizedMenuLabels(left, right) {
  return String(left || '').localeCompare(String(right || ''), undefined, {
    numeric: true,
    sensitivity: 'base',
  });
}

function sortMenuCommandsByLabel(commands) {
  return [...commands].sort((left, right) => compareLocalizedMenuLabels(left?.label, right?.label));
}

function layoutMenuCommand(mode, options = {}) {
  const normalized = normalizeLayoutMode(mode);
  const defaultDetail = normalized === 'single'
    ? t('menu.view.layout.single.detail', {name: fileExplorerLabel()})
    : normalized === 'split'
      ? t('menu.view.layout.split.detail', {name: fileExplorerLabel()})
      : '';
  return menuCommand(t(`menu.view.layout.${normalized}`), () => applyLayoutMode(normalized), {
    detail: options.detail ?? defaultDetail,
    disabled: options.disabled === true,
    keepOpen: true,
  });
}

function layoutMenuCommands() {
  const unavailable = narrowSingleColumnMode();
  const options = unavailable
    ? {disabled: true, detail: t('menu.view.layout.narrow.detail')}
    : {};
  // Keep normal modes visible when the measured viewport must use one column. The disabled rows
  // share the active command owner, so a resize cannot leave an enabled split command behind.
  return layoutModeValues.map(mode => layoutMenuCommand(mode, options));
}

const aboutLinkedInUrl = 'https://www.linkedin.com/in/keiven/';
const aboutProjectUrl = 'https://github.com/keivenchang/yolomux';
const aboutLicenseUrl = 'https://polyformproject.org/licenses/noncommercial/1.0.0';

function aboutDateTimeText() {
  if (bootstrap.versionCommitTime) return bootstrap.versionCommitTime;
  return localizedDateTimeFormat(Date.now() / 1000, {
    year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit',
  });
}

function aboutCommitShaText() {
  return bootstrap.versionCommit || bootstrap.commitSha || bootstrap.commit_sha || bootstrap.gitSha || bootstrap.git_sha || '';
}

function topbarVersionTitle() {
  const sha = aboutCommitShaText();
  const commitCount = Number(bootstrap.versionCommitCount);
  const lines = [];
  if (sha) lines.push(t('menu.help.about.sha', {sha}));
  if (bootstrap.versionCommitTime) lines.push(t('menu.help.lastCommit', {time: bootstrap.versionCommitTime}));
  if (Number.isFinite(commitCount) && commitCount > 0) lines.push(t('menu.help.about.commits', {count: commitCount}));
  return lines.join('\n') || t('menu.help.about.shaUnknown');
}

function topbarServerStartedAtMs() {
  const explicitMs = Number(bootstrap.serverStartedAtMs);
  if (Number.isFinite(explicitMs) && explicitMs > 0) return explicitMs;
  const seconds = Number(bootstrap.serverStartedAt);
  return Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : 0;
}

function topbarDurationText(seconds) {
  const remaining = Math.max(0, Math.floor(Number(seconds) || 0));
  if (remaining < 1) return t('duration.underOneSecond');
  const units = [
    ['day', 86400],
    ['hour', 3600],
    ['minute', 60],
    ['second', 1],
  ];
  const parts = [];
  let rest = remaining;
  for (const [name, size] of units) {
    const value = Math.floor(rest / size);
    if (!value) continue;
    parts.push(tPlural(`duration.${name}`, value));
    rest -= value * size;
    if (parts.length >= 2) break;
  }
  return parts.join(', ');
}

function topbarServerUptimeTitle() {
  const startedAtMs = topbarServerStartedAtMs();
  if (!startedAtMs) return t('server.uptimeUnknown');
  return t('server.uptimeRunning', {duration: topbarDurationText((Date.now() - startedAtMs) / 1000)});
}

function updateBrandTitles() {
  for (const brand of document.querySelectorAll('.brand-title')) {
    brand.title = topbarServerUptimeTitle();
    brand.onpointerenter = updateBrandTitles;
  }
  for (const version of document.querySelectorAll('.brand-title .brand-version')) {
    version.title = topbarVersionTitle();
    version.onpointerenter = updateBrandTitles;
  }
}

function aboutBrandHtml() {
  return `<span class="about-brand-yo">${esc(t('brand.marker'))}</span><span class="about-brand-lo">${esc(t('brand.wordmark.lo'))}</span><span class="about-brand-m">m</span><span class="about-brand-u">u</span><span class="about-brand-x">x</span>`;
}

function showAboutModal() {
  const modal = document.getElementById('modal');
  const title = document.getElementById('modalTitle');
  const body = document.getElementById('modalBody');
  if (!modal || !title || !body) return;
  title.textContent = t('menu.help.about');
  relocalizeModalChrome({content: false});
  modal.classList.add('about-open');
  const version = bootstrap.version || '';
  const sha = aboutCommitShaText();
  body.innerHTML = `<div class="about-modal">
    <div class="about-brand-row">${aboutBrandHtml()}${version ? `<span class="about-version">${esc(version)}</span>` : ''}</div>
    <dl class="about-details">
      <div><dt>${esc(t('menu.help.about.datetime'))}</dt><dd>${esc(aboutDateTimeText())}</dd></div>
      <div><dt>SHA</dt><dd>${esc(sha || t('common.unknown'))}</dd></div>
      <div><dt>${esc(t('menu.help.about.version'))}</dt><dd>${esc(version || t('common.unknown'))}</dd></div>
    </dl>
    <div class="about-links"><a class="about-author" href="${esc(aboutLinkedInUrl)}" target="_blank" rel="noopener noreferrer">${esc(t('menu.help.about.author'))}</a><span> - </span><a class="about-author about-github" href="${esc(aboutProjectUrl)}" target="_blank" rel="noopener noreferrer">${esc(t('menu.help.about.github'))}</a></div>
    <div class="about-license"><a class="about-author about-license-link" href="${esc(aboutLicenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(t('menu.help.about.license'))}</a></div>
  </div>`;
  modal.classList.add(CLS.open);
}

function currentActiveMenuItem() {
  if (focusedPanelItem && itemIsActivePaneTab(focusedPanelItem)) return focusedPanelItem;
  if (focusedTerminal && itemIsActivePaneTab(focusedTerminal)) return focusedTerminal;
  return activePaneItems()[0] || null;
}

function currentSessionActionTarget() {
  const current = currentActiveMenuItem();
  if (isTmuxSession(current)) return current;
  if (isTmuxSession(lastFocusedTmuxSession) && activeSessions.includes(lastFocusedTmuxSession)) return lastFocusedTmuxSession;
  const activeTmuxSessions = activeSessions.filter(isTmuxSession);
  return activeTmuxSessions.length === 1 ? activeTmuxSessions[0] : null;
}

function currentTmuxMenuTarget() {
  // All pane-aware surfaces share this explicit click/type state. Hover and auto-focus stay
  // visual-only, so opening tmux cannot retarget an action to a pane merely under the cursor.
  return explicitTmuxPaneFocusSession() || currentSessionActionTarget();
}

function orderedPaneItems(items = activePaneItems()) {
  const unique = [];
  for (const group of [
    items.filter(isTmuxSession),
    items.filter(isFileEditorItem),
    items.filter(item => !isTmuxSession(item) && !isFileEditorItem(item)),
  ]) {
    for (const item of group) {
      if (!unique.includes(item)) unique.push(item);
    }
  }
  return unique;
}

function menuTabDetail(item) {
  const type = tabTypeForItem(item);
  if (type?.detail) return type.detail(item);
  return tabMenuDetailText(item, transcriptMetadataState.payload.sessions?.[item]);
}

function commandPaletteTabDetail(item) {
  const detail = menuTabDetail(item);
  const info = transcriptMetadataState.payload.sessions?.[item];
  const summary = sessionWorkSummary(item, info);
  if (summary.graphBacked && summary.pullRequests.length > 1) {
    const aggregate = pullRequestAggregateLabel(summary.pullRequests);
    return detail.includes(aggregate) ? detail : [aggregate, detail].filter(Boolean).join(' · ');
  }
  const pr = displayPullRequest(info);
  if (!pr?.number) return detail;
  const bareNumber = `#${pr.number}`;
  const visibleNumber = `PR ${bareNumber}`;
  const rest = detail
    .replace(visibleNumber, '')
    .replace(bareNumber, '')
    .replace(/\s*·\s*·\s*/g, ' · ')
    .replace(/^\s*·\s*|\s*·\s*$/g, '')
    .trim();
  return rest ? `${visibleNumber} · ${rest}` : visibleNumber;
}

function menuTabRowHtml(item, options = {}) {
  const type = tabTypeForItem(item);
  if (type?.rowHtml) return type.rowHtml(item, options);
  const info = transcriptMetadataState.payload.sessions?.[item];
  const auto = autoApproveStates.get(item)?.enabled === true;
  const state = sessionState(item, info);
  const pr = displayPullRequest(info);
  const desc = sessionTabDescription(item, info);
  const detailHtml = desc ? `<span class="session-button-dir tab-inline-detail">${esc(desc)}</span>` : '';
  return `<span class="pane-tab-core">${sessionTabLeadingActivityContainerHtml(item, info, auto, {enabledOnly: false, toggle: options.toggleYolo === true && !readOnlyMode, state})}<span class="session-button-prefix">${sessionNumberNameHtml(item)}</span>
    <span class="session-button-text">${state ? sessionStateHtml(state) : ''}${defaultBranchBadgeHtml(item, info)}${pullRequestSummaryBadgesHtml(item, info)}${detailHtml}</span></span>`;
}

function menuTabCommand(item, options = {}) {
  const slot = slotForSession(item);
  const visible = itemIsActivePaneTab(item);
  const active = item === currentActiveMenuItem();
  const detail = options.detail || (visible ? menuTabDetail(item) : (itemIsBackgroundPaneTab(item) ? t('menu.tabs.minimizedDetail') : t('menu.tabs.inactiveDetail')));
  return menuCommand(itemLabel(item), () => {
    if (slot && visible && !options.openAsPane) return activatePaneTab(slot, item, {userInitiated: true});
    return selectSession(item, {userInitiated: true});
  }, {
    checked: options.checked ?? active,
    detail: '',
    ariaLabel: [itemLabel(item), detail].filter(Boolean).join(' - '),
    html: stripTitleAttrs(menuTabRowHtml(item, {...options, menu: true})),
    className: 'app-menu-tab-command',
    targetItem: item,
  });
}

function tmuxSessionActionCommands(session, options = {}) {
  const hasSession = isTmuxSession(session);
  const autoPayload = hasSession ? autoApproveStates.get(session) : null;
  const autoHere = hasSession ? autoApproveEnabledHere(autoPayload) : false;
  const includeYolo = options.includeYolo !== false;
  const includeKill = options.includeKill !== false;
  const readonlyDetail = t('menu.common.adminOnly');
  const focusDetail = hasSession ? menuTabDetail(session) : t('menu.tmux.focusSessionFirst');
  const visibleDetail = readOnlyMode ? readonlyDetail : (hasSession ? '' : t('menu.tmux.noTabFocused'));
  const yoloLabel = hasSession
    ? t(autoHere ? 'menu.tmux.yolo.disableFor' : 'menu.tmux.yolo.enableFor', {session})
    : t(autoHere ? 'menu.tmux.yolo.disable' : 'menu.tmux.yolo.enable');
  const renameLabel = hasSession ? t('menu.tmux.rename.for', {session}) : t('common.renameTmuxSession');
  const renameAction = options.renameAction || (() => renameTmuxSession(session));
  const commands = [];
  if (includeYolo) commands.push(menuCommand(yoloLabel, async () => {
      if (!hasSession) return;
      await toggleAutoApprove(session);
      renderSessionButtons();
      renderPaneTabStrips();
    }, {
      checked: autoHere,
      disabled: readOnlyMode || !hasSession,
      detail: visibleDetail,
      iconHtml: hasSession ? yoloMarkerHtml(session, autoHere, {enabledOnly: false, yoloWorking: sessionYoloIsWorking(session)}) : '',
      ariaLabel: [yoloLabel, hasSession ? focusDetail : t('menu.tmux.focusSessionFirst')].filter(Boolean).join(' - '),
    }));
  commands.push(
    menuCommand(renameLabel, renameAction, {
      disabled: readOnlyMode || !hasSession,
      detail: visibleDetail,
      ariaLabel: [renameLabel, focusDetail].filter(Boolean).join(' - '),
    })
  );
  if (includeKill) commands.push(tmuxSessionKillCommand(session));
  return commands;
}

function tmuxSessionKillCommand(session) {
  const hasSession = isTmuxSession(session);
  const readonlyDetail = t('menu.common.adminOnly');
  const focusDetail = hasSession ? menuTabDetail(session) : t('menu.tmux.focusSessionFirst');
  const visibleDetail = readOnlyMode ? readonlyDetail : (hasSession ? '' : t('menu.tmux.noTabFocused'));
  const label = hasSession ? t('menu.tmux.kill.for', {session}) : t('menu.tmux.kill');
  return menuCommand(label, () => killTmuxSession(session), {
    disabled: readOnlyMode || !hasSession,
    detail: visibleDetail,
    ariaLabel: [label, focusDetail].filter(Boolean).join(' - '),
  });
}

function yoloRulePath() {
  return yoloRulesPayload.path
    || nestedSetting(clientSettings, 'yolo.rule_file_path', nestedSetting(clientSettingsDefaults, 'yolo.rule_file_path', '~/.config/yolomux/yolo-rules.yaml'));
}

function settingsConfigPath() {
  return clientSettingsPayload.path || clientSettingsPayload.display_path || '~/.config/yolomux/settings.yaml';
}

// Map the global theme mode to the terminal_theme setting value for the lockstep View -> Theme toggle.
function terminalThemeSettingForGlobalMode(mode) {
  if (mode === 'system') return 'follow-app';
  if (mode === 'light') return 'light';
  return 'dark';
}

// Apply a resolved global theme mode live and persist it — shared by the one-click Theme submenu
// (setGlobalThemeMode) and the View cycle shortcut (cycleGlobalThemeSetting). #258: APPLY live (the menu
// used to only save the patch, so body.theme-* never flipped). #261: do NOT pin appearance.terminal_theme
// — the terminal keeps its own setting (default follow-app/System) and follows the app on its own.
function applyAndSaveGlobalTheme(next) {
  globalThemeMode = next;
  applyGlobalThemeMode({updateEditor: true, updateTerminals: true});
  renderSessionButtons();  // rebuild the menu bar so the View -> Theme active marker tracks the new mode
  return saveSettingsPatch(settingPatch('appearance.theme', next))
    .then(() => {
      statusEl.textContent = t('status.themeChanged', {theme: globalThemeLabel(next)});
    })
    .catch(error => {
      statusErr(localizedHtml('status.themeSaveFailed', {error: userMessageText(error, t('common.requestFailed'))}));
      refreshSettings({force: true});
    });
}

// One-click from the Theme submenu: any target (system/dark/light) applies in one click, both directions.
function setGlobalThemeMode(mode) {
  return applyAndSaveGlobalTheme(normalizeGlobalThemeMode(mode));
}

function cycleGlobalThemeSetting() {
  return applyAndSaveGlobalTheme(nextGlobalThemeMode());
}

function yoloRuleStatusDetail() {
  const source = structuredMessageText(yoloRulesPayload, 'source', t('common.unknown'));
  const count = Number(yoloRulesPayload.rule_count || 0);
  const countText = tPlural('menu.yolo.ruleCount', count);
  const dryRun = yoloRulesPayload.dry_run ? t('menu.yolo.dryRunSuffix') : '';
  return yoloRulesPayload.error
    ? t('common.errorDetail', {error: userMessageText(yoloRulesPayload, yoloRulesPayload.error)})
    : t('menu.yolo.statusDetail', {source, rules: countText, dryRun});
}

async function openYoloRuleFile() {
  if (readOnlyMode) {
    statusErr(localizedHtml('status.yoloReadOnlyCreateRules'));
    return;
  }
  try {
    const payload = await apiFetchJson('/api/yolo-rules/open', {method: 'POST'});
    yoloRulesPayload = payload;
    renderPreferencesPanels();
    await openFileInEditor(payload.path || yoloRulePath(), {name: basenameOf(payload.path || yoloRulePath())});
    statusEl.textContent = t('status.openedYoloRule');
  } catch (error) {
    statusErr(localizedHtml('status.yoloOpenRuleFailed', {error}));
  }
}

async function reloadYoloRules() {
  try {
    const payload = await apiFetchJson('/api/yolo-rules/reload', {method: 'POST'});
    yoloRulesPayload = payload;
    renderPreferencesPanels();
    const level = payload.error ? 'error' : '';
    const errorText = userMessageText(payload, payload.error || '');
    statusEl.innerHTML = payload.error
      ? `<span class="err">${localizedHtml('status.yoloReloadFailed', {error: errorText})}</span>`
      : `<span class="ok">${localizedHtml('status.yoloReloaded')}</span>`;
    emitNotification('yoloRules', {title: t('brand.yoloRules'), lines: errorText || yoloRuleStatusDetail(), className: level ? 'attention-alert toast' : ''});
  } catch (error) {
    statusErr(localizedHtml('status.yoloReloadRequestFailed', {error}));
  }
}

async function refreshYoloRulesStatus(options = {}) {
  try {
    const payload = await apiFetchJson('/api/yolo-rules');
    yoloRulesPayload = payload;
    renderPreferencesPanels();
    return payload;
  } catch (error) {
    if (!options.silent) statusErr(localizedHtml('status.yoloStatusFailed', {error}));
    return null;
  }
}

function tmuxYoloMenuItems() {
  return [
    menuCommand(t('menu.yolo.openRuleFile'), openYoloRuleFile, {
      disabled: readOnlyMode,
      detail: compactHomePath(yoloRulePath()),
    }),
    menuCommand(t('menu.yolo.reloadRules'), reloadYoloRules, {
      detail: yoloRuleStatusDetail(),
    }),
  ];
}

function tmuxCurrentYoloCommand(session) {
  const hasSession = isTmuxSession(session);
  const payload = hasSession ? autoApproveStates.get(session) : null;
  const enabled = hasSession ? autoApproveEnabledHere(payload) : false;
  const elsewhere = hasSession ? autoApproveEnabledElsewhere(payload) : false;
  const label = t('menu.tmux.yo.on');
  return menuCommand(label, async () => {
    if (!hasSession) return;
    await toggleAutoApprove(session);
    renderSessionButtons({force: true});
    renderPaneTabStrips();
  }, {
    disabled: readOnlyMode || !hasSession,
    detail: hasSession ? t('menu.tmux.sessionLabel', {session}) : t('menu.tmux.focusTabFirst'),
    iconHtml: hasSession ? yoloMarkerHtml(session, enabled, {enabledOnly: false, yoloWorking: sessionYoloIsWorking(session)}) : '',
    keepOpen: true,
    ariaLabel: hasSession ? t(enabled ? 'menu.tmux.yolo.disableFor' : 'menu.tmux.yolo.enableFor', {session}) : t('menu.tmux.focusTabFirst'),
  });
}

function tmuxSessionViewCommands(session, options = {}) {
  const hasSession = isTmuxSession(session);
  const active = hasSession && activeSessions.includes(session);
  const focusDetail = hasSession ? menuTabDetail(session) : t('menu.tmux.focusSessionFirst');
  const disabledDetail = hasSession ? t('menu.tmux.openInPaneFirst') : t('menu.tmux.noTabFocused');
  const viewLabel = sessionLabel(session);
  const transcriptName = t('menu.tmux.transcript', {session: viewLabel});
  const summaryName = t('menu.tmux.aiTranscript', {session: viewLabel});
  const eventLogName = t('menu.tmux.eventLog', {session: viewLabel});
  const statusMode = hasSession ? tmuxStatusModeForSession(session) : 'none';
  const statusName = t('pref.appearance.tmux_status_bar.label');
  return [
    menuCommand(transcriptName, () => {
      if (active) activateTab(session, 'transcript');
    }, {
      disabled: !active,
      detail: active ? '' : disabledDetail,
      checked: active && panelActiveTabName(session) === 'transcript',
      ariaLabel: [transcriptName, focusDetail].filter(Boolean).join(' - '),
    }),
    menuCommand(summaryName, () => {
      if (active) activateTab(session, 'summary');
    }, {
      disabled: readOnlyMode || !active,
      detail: readOnlyMode ? t('menu.common.adminOnly') : (active ? '' : disabledDetail),
      checked: active && panelActiveTabName(session) === 'summary',
      ariaLabel: [summaryName, focusDetail].filter(Boolean).join(' - '),
    }),
    menuCommand(eventLogName, () => {
      if (active) activateTab(session, 'events');
    }, {
      disabled: !active,
      detail: active ? '' : disabledDetail,
      checked: active && panelActiveTabName(session) === 'events',
      ariaLabel: [eventLogName, focusDetail].filter(Boolean).join(' - '),
    }),
    menuCommand(t('menu.tmux.paneDetails'), () => {
      if (!active) return;
      const panel = document.getElementById(panelDomId(session));
      if (panel) setPanelDetailsCollapsed(panel, !panel.classList.contains('details-collapsed'));
    }, {
      disabled: !active,
      detail: active ? '' : disabledDetail,
      ariaLabel: [t('menu.tmux.paneDetails'), focusDetail].filter(Boolean).join(' - '),
    }),
    ...(options.includeStatus === false ? [] : [menuCommand(statusName, async () => {
        if (hasSession) await cycleTmuxStatusMode(session);
      }, {
        checked: statusMode !== 'none',
        disabled: readOnlyMode || !hasSession,
        detail: hasSession ? t('menu.tmux.statusBarCycle') : disabledDetail,
        keepOpen: true,
        ariaLabel: [statusName, focusDetail].filter(Boolean).join(' - '),
      })]),
  ];
}

// The server owns the two launch commands. The dangerous-auto-approve row exposes its exact
// --dangerously-* flags so that choosing it is deliberate; normal rows remain clean one-click starts.
function agentLaunchCommand(agent, dangerouslyYolo = false) {
  const commands = agentLaunchCommands[agent];
  if (commands && typeof commands === 'object') return String(commands[dangerouslyYolo ? 'full_access' : 'normal'] || '').trim();
  return String(commands || '').trim(); // Compatibility with an older server during a rolling restart.
}

function agentLaunchParams(agent, dangerouslyYolo = false) {
  const command = agentLaunchCommand(agent, dangerouslyYolo);
  if (!command) return '';
  const space = command.indexOf(' ');
  return space >= 0 ? command.slice(space + 1).trim() : command;
}

function agentUnavailableDetail(agent) {
  if (agentUnavailableReason(agent) === 'not-on-path') return t('menu.tmux.agentUnavailablePath');
  return t('menu.tmux.agentUnavailable', {name: agentName(agent)});
}

function newTmuxSessionLabel(agent, dangerouslyYolo = false) {
  return dangerouslyYolo
    ? t('menu.tmux.newSession.fullAccess', {name: agentName(agent)})
    : t('menu.tmux.newSession', {name: agentName(agent)});
}

function shellLaunchLabel(terminal) {
  return `Shell: ${terminal}`;
}

function newTmuxSessionFullAccessFlags(agent) {
  const flags = agentLaunchParams(agent, true);
  return flags ? `+ ${flags}` : '';
}

function terminalLaunchNames() {
  return Array.from(new Set(terminalCommands
    .map(command => String(command || '').trim())
    .filter(command => /^[A-Za-z0-9][A-Za-z0-9_.+-]*$/.test(command))))
    .sort((left, right) => left.localeCompare(right, undefined, {numeric: true, sensitivity: 'base'}));
}

function newTmuxSessionIcon(agent) {
  return agent === 'term' ? appMenuUiIcon('shell') : agentIcon(agent);
}

function newTmuxSessionItems() {
  return ['claude', 'codex', 'term'].map(agent => {
    const available = availableAgents.has(agent);
    const capped = visibleSessions.length >= maxSessionTabs;
    // #39: an installed agent that is not logged in is greyed with its login command, instead of
    // silently starting a session that the CLI will reject for auth.
    const loggedOut = available && !agentLoggedIn(agent);
    const unavailableDetail = readOnlyMode
      ? t('menu.common.adminOnly')
      : (!available
        ? agentUnavailableDetail(agent)
        : (loggedOut
          ? t('menu.tmux.runLogin', {command: agentLoginCommand(agent)})
          : (capped ? t('menu.tmux.limitReached') : '')));
    const launch = (dangerouslyYolo, terminal = '') => {
      const fullAccessFlags = dangerouslyYolo ? newTmuxSessionFullAccessFlags(agent) : '';
      return menuCommand(
        terminal || (dangerouslyYolo ? newTmuxSessionLabel(agent, true) : newTmuxSessionLabel(agent)),
        () => createNextSession(agent, {dangerouslyYolo, terminal}), {
          iconHtml: dangerouslyYolo || terminal ? '' : newTmuxSessionIcon(agent),
          disabled: readOnlyMode || !available || loggedOut || capped,
          detail: unavailableDetail,
          title: fullAccessFlags,
          ariaLabel: dangerouslyYolo
            ? [t('menu.tmux.newSession.fullAccess', {name: agentName(agent)}), agentLaunchParams(agent, true)].filter(Boolean).join(' - ')
            : (terminal ? shellLaunchLabel(terminal) : newTmuxSessionLabel(agent)),
        });
    };
    const terminals = terminalLaunchNames();
    return agent === 'term'
      ? (terminals.length
        ? menuCommandRow(terminals.map(terminal => launch(false, terminal)), {
          className: 'app-menu-command-row app-menu-command-row--shells',
          label: 'Shell:',
          iconHtml: newTmuxSessionIcon(agent),
          separator: false,
        })
        // Do not guess a shell. A terminal launch is valid only when the server supplied an
        // explicit, validated command for the user to choose.
        : null)
      : (fullAccessAgentLaunchesEnabled
        ? menuCommandPair(launch(false), launch(true), {className: 'app-menu-command-pair'})
        : launch(false));
  });
}

function tabCommandsForItems(items, options) {
  return items.map(item => menuTabCommand(item, options));
}

// a PR number in any of the forms a user types (#N, PR#N, PR N, N).
function prNumberSearchForms(number) {
  if (!number) return [];
  return [`#${number}`, `PR#${number}`, `PR ${number}`, String(number)];
}

function linearSearchFields(linear) {
  if (!Array.isArray(linear)) return [];
  return linear.flatMap(item => {
    if (!item) return [];
    if (typeof item === 'string') return [item];
    return [item.identifier, item.title, item.state, item.url];
  }).filter(Boolean);
}

function pullRequestSearchFields(pr) {
  if (!pr) return [];
  return [
    pr.title,
    pr.description,
    pr.url,
    pr.state,
    pr.status_label,
    pr.review_decision,
    pr.author_login,
    pr.number ? 'PR' : '',
    ...prNumberSearchForms(pr.number),
    // Normalized graph PRs own canonical `linear_issue_ids`; older view models exposed the
    // same relationship as `linear_ids`. Search must index both shapes while metadata is
    // rendered directly from the graph, otherwise an other-branch PR becomes invisible to
    // Cmd-P despite being visible in YO!info.
    ...linearSearchFields(pr.linear_issue_ids || pr.linear_ids),
  ].filter(Boolean);
}

function finderSearchAliases(item) {
  const isSurface = typeof isFileSurfaceItem === 'function'
    ? isFileSurfaceItem(item)
    : isFileExplorerItem(item);
  if (!isSurface) return [];
  return ['Finder', 'Differ', 'Tabber', 'File Explorer', t('finder.label.finder'), t('finder.label.explorer'), t('brand.tab.changes'), t('tabber.title')];
}

function tabSearchFields(item) {
  const info = transcriptMetadataState.payload.sessions?.[item] || {};
  const summary = sessionWorkSummary(item, info);
  const filePath = fileItemPath(item) || '';
  // Also index the touched repos' branch/PR/Linear metadata (the same data YO!info shows), so a
  // session is findable by any related branch even when it is not the currently checked-out branch.
  const primaryRoot = summary.git?.root || summary.git?.cwd || '';
  const repositories = summary.graphBacked ? summary.repositories : [
    ...(summary.git ? [{...summary.git, root: summary.git.root || summary.git.cwd || ''}] : []),
    ...summary.repositories,
  ];
  const branchSources = [
    ...repositories
      .filter(repo => (repo?.root || repo?.cwd || '') === primaryRoot || !primaryRoot || summary.graphBacked)
      .flatMap(repo => repo?.other_branches?.branches || []),
  ];
  const pr = displayPullRequest(info);
  return [
    item,
    itemLabel(item),
    sessionLabel(item),
    menuTabDetail(item),
    filePath,
    compactHomePath(filePath),
    info.cwd,
    info.branch,
    info.status,
    info.description,
    info.goal,
    ...finderSearchAliases(item),
    ...pullRequestSearchFields(pr),
    ...linearSearchFields(info.linear),
    ...linearSearchFields(summary.linearIssues),
    ...branchSources.flatMap(branch => [
      branch.name,
      branch.subject,
      ...pullRequestSearchFields(branch.pull_request || branch.pull_requests?.[0]),
      ...(branch.pull_requests || []).flatMap(pullRequestSearchFields),
      ...linearSearchFields(branch.linear_ids),
      ...linearSearchFields(branch.linear),
    ]),
  ].filter(Boolean);
}

function tabSearchScore(item, query = tabsMenuSearchText) {
  if (!String(query || '').trim()) return 0;
  return fuzzySearchScore(query, tabSearchFields(item));
}

function filterTabItemsForSearch(items, query = tabsMenuSearchText) {
  if (!String(query || '').trim()) return items;
  return items
    .map((item, index) => ({item, index, score: tabSearchScore(item, query)}))
    .filter(entry => Number.isFinite(entry.score))
    .sort((left, right) => right.score - left.score || left.index - right.index)
    .map(entry => entry.item);
}

function backgroundTabMenuItems() {
  return tabCommandsForItems(filterTabItemsForSearch(backgroundTabItems()), {
    checked: false,
    detail: t('menu.tabs.minimized'),
    openAsPane: true,
    toggleYolo: true,
  });
}

function inactiveTabMenuItems() {
  return tabCommandsForItems(filterTabItemsForSearch(inactiveTabItems()), {
    checked: false,
    detail: t('menu.tabs.notInPane'),
    openAsPane: true,
    toggleYolo: true,
  });
}

function sortTabItemsForMenu(items) {
  const unique = Array.from(new Set(items.filter(isLayoutItem)));
  const compare = (left, right) => compareLocalizedMenuLabels(itemLabel(left), itemLabel(right))
    || compareLocalizedMenuLabels(left, right);
  // Tabs is a navigator, not a status dashboard: tmux sessions always form the first simple,
  // naturally sorted group; every YOLOmux-owned/file tab follows in the same stable label order.
  return [
    ...unique.filter(isTmuxSession).sort(compare),
    ...unique.filter(item => !isTmuxSession(item)).sort(compare),
  ];
}

function tabMenuItems(openItems = orderedPaneItems(activePaneItems())) {
  const query = tabsMenuSearchText.trim();
  const allItems = Array.from(new Set([...openItems, ...paneItems(), ...allTabItems()]));
  const sortedItems = sortTabItemsForMenu(filterTabItemsForSearch(allItems, query));
  const tmuxItems = sortedItems.filter(isTmuxSession);
  const yoloItems = sortedItems.filter(item => !isTmuxSession(item));
  const groupedItems = menuGroups(
    tmuxItems.map(item => menuTabCommand(item, {toggleYolo: true})),
    yoloItems.map(item => menuTabCommand(item, {toggleYolo: true}))
  );
  const resultItems = groupedItems.length ? groupedItems : [menuCommand(t('menu.tabs.noMatch'), null, {disabled: true})];
  return resultItems;
}

function appMenuCommandIdentity(command) {
  return String(command?.dataset?.menuTargetItem || command?.getAttribute?.('aria-label') || '');
}

function refreshOpenTabsMenuRows() {
  const wrapper = Array.from(sessionButtons?.querySelectorAll?.('.app-menu') || [])
    .find(menu => menu.dataset.appMenu === 'tabs' && menu.classList.contains(CLS.open));
  if (!wrapper) return false;
  const popover = wrapper.querySelector(':scope > .app-menu-popover');
  if (!popover) return false;
  const tabsMenu = appMenuTree().find(menu => menu.id === 'tabs');
  if (!tabsMenu) return false;
  const focusedCommand = document.activeElement?.closest?.('.app-menu-command');
  const focusedCommandKey = popover.contains(focusedCommand) ? appMenuCommandIdentity(focusedCommand) : '';
  popover.replaceChildren(...tabsMenu.items.map(createAppMenuItem));
  for (const command of popover.querySelectorAll('.app-menu-command')) {
    const commandKey = appMenuCommandIdentity(command);
    if (focusedCommandKey && commandKey === focusedCommandKey) {
      command.focus({preventScroll: true});
    }
  }
  fitAppMenuPopover(popover);
  return true;
}

function refreshTabsMenuMetadataOnOpen() {
  // Opening Tabs must be instant: render the last accepted metadata snapshot first. A fresh
  // forced request then performs tmux list-sessions in the background and refreshes only this
  // open menu when names/descriptions arrive. The metadata request record coalesces repeats.
  if (typeof refreshSessionMetadata !== 'function') return;
  void refreshSessionMetadata({force: true, refreshAuto: false, refreshActivity: false, refreshContext: false});
}

function fileMenuVirtualCommand(item, detail) {
  return menuCommand(itemLabel(item), () => selectSession(item, {userInitiated: true}), {
    checked: itemInLayout(item),
    detail,
    iconHtml: tabTypeIconHtml(item, {menu: true}),
    targetItem: item,
  });
}

function fileSurfaceMenuItems() {
  // Placement belongs to the layout owner. This menu only asks it to activate an existing surface
  // or insert the missing one, so menu actions cannot recreate a second placement algorithm.
  const finder = typeof finderItemId !== 'undefined' ? finderItemId : fileExplorerItemId;
  const differ = typeof differItemId !== 'undefined' ? differItemId : '';
  const tabber = typeof tabberItemId !== 'undefined' ? tabberItemId : '';
  const items = Array.isArray(fileSurfaceItems) ? fileSurfaceItems : [finder];
  const detailFor = item => {
    if (item === finder) return t('menu.file.browseFiles');
    if (item === differ) return t('changes.show');
    if (item === tabber) return t('tabber.description');
    return tabTypeForItem(item)?.detail?.() || '';
  };
  return items.map(item => menuCommand(itemLabel(item), () => openFileSurfaceFromMenu(item), {
    checked: itemInLayout(item),
    disabled: typeof openFileSurfaceFromMenu !== 'function',
    detail: item === finder ? `${detailFor(item)} · ${appShortcutText('B')}` : detailFor(item),
    iconHtml: tabTypeIconHtml(item, {menu: true}),
    targetItem: item,
    className: 'app-menu-file-destination',
  }));
}

function fileMenuPanelCommands() {
  const virtualCommands = FILE_MENU_PANEL_DEFINITIONS
    .filter(({itemId}) => itemId !== fileExplorerItemId)
    .map(({itemId}) => fileMenuVirtualCommand(itemId, tabTypeForItem(itemId)?.detail?.() || ''));
  const fileSurfaces = fileSurfaceMenuItems();
  if (fileSurfaces.length) {
    if (narrowSingleColumnMode()) {
      // A narrow touch layout displays one chosen surface, so its three direct commands remain
      // distinct instead of implying all three can be visible at once.
      virtualCommands.unshift(...fileSurfaces);
    } else {
      virtualCommands.unshift(menuCommand(t('yoagent.capability.finderDifferTabber.name'), () => openFileSurfaceFromMenu(finderItemId), {
        checked: fileSurfaceItems.every(item => itemInLayout(item)),
        partial: fileSurfaceItems.some(item => itemInLayout(item)) && !fileSurfaceItems.every(item => itemInLayout(item)),
        disabled: typeof openFileSurfaceFromMenu !== 'function',
        detail: t('menu.file.browseFiles'),
        iconHtml: tabTypeIconHtml(finderItemId, {menu: true}),
        targetItem: finderItemId,
        className: 'app-menu-file-destination',
      }));
    }
  }
  return virtualCommands;
}

function appMenuTree() {
  const activeTmux = currentTmuxMenuTarget();
  const openItems = orderedPaneItems(activePaneItems());
  const fileDestinationCommands = sortMenuCommandsByLabel([
    menuCommand(t('common.openFile'), openFileQuickOpen, {
      detail: appShortcutText('P'),
      iconHtml: appMenuUiIcon('document'),
    }),
    ...fileMenuPanelCommands(),
    menuCommand(t('common.preferences'), () => selectSession(prefsItemId, {userInitiated: true}), {
      checked: itemInLayout(prefsItemId),
      detail: compactHomePath(settingsConfigPath()),
      iconHtml: tabTypeIconHtml(prefsItemId, {menu: true}),
      targetItem: prefsItemId,
    }),
  ]);
  return [
    {
      id: 'file',
      label: t('menu.file'),
      items: menuGroups(
        newTmuxSessionItems(),
        fileDestinationCommands,
        [
          menuCommand(t('menu.file.logout'), logOut, {
            detail: t('menu.file.logout.detail'),
            iconHtml: appMenuUiIcon('logout'),
          }),
        ]
      ),
    },
    {
      id: 'view',
      label: t('menu.view'),
      items: [
        menuCommand(tabMetaVisible ? t('menu.view.tabMeta.hide') : t('menu.view.tabMeta.show'), toggleTabMetadata, {
          checked: tabMetaVisible,
          keepOpen: true,
          detail: t('menu.view.tabMeta.detail'),
          iconHtml: appMenuUiIcon('tab-meta', tabMetaVisible),
        }),
        menuSubmenu(t('menu.view.alert'), notificationDeliveryItems(), {
          iconHtml: appMenuUiIcon('notify', notificationDeliveryEnabled()),
          keepOpen: true,
        }),
        menuCommand(t('common.refresh'), refreshAll, {
          iconHtml: appMenuUiIcon('refresh'),
        }),
        menuSubmenu(t('menu.view.theme'), [
          menuCommand(t('common.theme.system'), () => setGlobalThemeMode('system'), {checked: normalizeGlobalThemeMode() === 'system', keepOpen: true, detail: t('menu.view.theme.system.detail', {mode: t('common.theme.' + resolvedGlobalThemeMode())})}),
          menuCommand(t('common.theme.dark'), () => setGlobalThemeMode('dark'), {checked: normalizeGlobalThemeMode() === 'dark', keepOpen: true}),
          menuCommand(t('common.theme.light'), () => setGlobalThemeMode('light'), {checked: normalizeGlobalThemeMode() === 'light', keepOpen: true}),
        ]),
        menuSubmenu(t('menu.view.layout'), layoutMenuCommands()),
      ],
    },
    {
      id: 'tmux',
      label: 'tmux',
      items: menuGroups(
        [tmuxCurrentYoloCommand(activeTmux)],
        tmuxSessionViewCommands(activeTmux),
        [
          ...tmuxSessionActionCommands(activeTmux, {includeYolo: false}),
          menuCommand(t('menu.tmux.resume'), null, {
            disabled: true,
            detail: t('menu.common.comingSoon'),
          }),
        ],
        [
          menuSubmenu(t('brand.yolo'), tmuxYoloMenuItems()),
        ]
      ),
    },
    {
      id: 'tabs',
      label: t('common.tabsLabel'),
      items: tabMenuItems(openItems),
    },
    {
      id: 'help',
      label: t('menu.help'),
      items: menuGroups(
        [menuCommand(t('common.commandPalette'), openCommandPalette, {
          detail: appShortcutText('P', {shift: true}),
        })],
        [
          menuCommand(t('brand.version', {version: bootstrap.version || ''}).trim(), null, {
            disabled: true,
            detail: bootstrap.versionCommitTime ? t('menu.help.lastCommit', {time: bootstrap.versionCommitTime}) : '',
          }),
          menuCommand(t('common.keyboardShortcuts'), openKeyboardShortcutsOverlay, {
            detail: '?',
          }),
          menuCommand(t('menu.help.openReadme'), openProjectReadme, {
            disabled: !projectReadmePath(),
            detail: t('menu.help.localReadme'),
          }),
        ],
        [
          menuCommand(t('menu.help.about'), showAboutModal),
        ]
      ),
    },
  ];
}

let topbarNavigationCompact = null;
let topbarPackingFrame = 0;
let topbarPackingObserver = null;
let topbarPackingStepsApplied = [];
let topbarPackingIsApplying = false;

// The sequence is user-facing priority, not a viewport policy. Start complete, reduce only on
// actual overflow. Every pass restarts from this full representation so resize direction and prior
// compact state cannot change which controls fit.
const topbarPackingStepOrder = Object.freeze([
  'hide-version',
  'compact-brand',
  'hide-owner',
  'compact-search',
  'compact-activity',
  'hide-latency',
  'hide-logout',
  'hide-notify',
  'hide-language',
  'hide-nav',
  'icon-search',
  'compact-menu',
]);
const topbarPackingVisualItemSelectors = Object.freeze([
  '.brand-cell',
  '.app-menu-bar',
  '.topbar-nav',
  '.topbar-search',
  '.topbar-language-menu',
  '#backendHealthIndicator',
  '#topbarOwnerStatus',
  '#topbarActivity',
  '.actions > :not(#topbarActivity):not(#status)',
]);
const topbarPackingMinGapPx = 2;

function topbarPackingTargets() {
  return [document.body, appRootElement()].filter(Boolean);
}

function topbarPackingHasStep(step) {
  return document.body?.classList?.contains(`topbar-pack-${step}`) === true;
}

function setTopbarPackingSteps(steps = []) {
  const active = new Set(steps);
  for (const target of topbarPackingTargets()) {
    for (const step of topbarPackingStepOrder) {
      target.classList?.toggle(`topbar-pack-${step}`, active.has(step));
    }
  }
}

// Packing changes that affect markup must be rendered before the next measurement. In particular,
// compact activity moves into the actions rail and compact menus replace five roots with one. If we
// measured the old markup, the packer could unnecessarily remove buttons or oscillate on resize.
function applyTopbarPackingSteps(steps = []) {
  const activityWasCompact = topbarPackingHasStep('compact-activity');
  setTopbarPackingSteps(steps);
  const navigationChanged = topbarPackingSyncNavigation(steps);
  if (!navigationChanged && activityWasCompact !== topbarPackingHasStep('compact-activity')) {
    updateTopbarActivityStatus();
  }
}

function topbarPackingVisualItems() {
  const seen = new Set();
  return topbarPackingVisualItemSelectors.flatMap(selector => Array.from(document.querySelectorAll(selector)))
    .filter(node => {
      if (seen.has(node)) return false;
      seen.add(node);
      const style = getComputedStyle(node);
      const rect = node.getBoundingClientRect();
      return !node.hidden && style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
    });
}

function topbarPackingLayoutState() {
  const bar = document.querySelector('.topbar');
  if (!bar) return {overflow: false, outside: [], collisions: [], clipped: []};
  const barRect = bar.getBoundingClientRect();
  const items = topbarPackingVisualItems()
    .map(node => ({node, rect: node.getBoundingClientRect()}))
    .sort((a, b) => a.rect.left - b.rect.left || a.rect.right - b.rect.right);
  const outside = items.filter(item => item.rect.left < barRect.left - 1 || item.rect.right > barRect.right + 1);
  const collisions = [];
  for (let index = 1; index < items.length; index += 1) {
    const previous = items[index - 1];
    const current = items[index];
    if (current.rect.left - previous.rect.right < topbarPackingMinGapPx) collisions.push([previous.node, current.node]);
  }
  const compactActivity = document.querySelector('#topbarActivity.topbar-activity--mobile-count-balls');
  const compactActivityRect = compactActivity?.getBoundingClientRect();
  const activityBalls = compactActivity
    ? Array.from(compactActivity.querySelectorAll('.topbar-activity-count.active .topbar-activity-ball'))
      .filter(node => getComputedStyle(node).display !== 'none')
      .map(node => ({node, rect: node.getBoundingClientRect()}))
      .sort((a, b) => a.rect.left - b.rect.left)
    : [];
  if (compactActivityRect) {
    outside.push(...activityBalls.filter(item => item.rect.left < compactActivityRect.left - 1 || item.rect.right > compactActivityRect.right + 1));
  }
  for (let index = 1; index < activityBalls.length; index += 1) {
    const previous = activityBalls[index - 1];
    const current = activityBalls[index];
    if (current.rect.left - previous.rect.right < topbarPackingMinGapPx) collisions.push([previous.node, current.node]);
  }
  const searchLabel = document.querySelector('.topbar-search-label');
  const compactSearchLabel = document.querySelector('.topbar-search-label-short');
  const searchLabelRect = searchLabel?.getBoundingClientRect();
  const compactSearchLabelRect = compactSearchLabel?.getBoundingClientRect();
  const compactSearchClipped = Boolean(searchLabel && compactSearchLabel && getComputedStyle(compactSearchLabel).display !== 'none' && (
    searchLabel.scrollWidth > searchLabel.clientWidth + 1
    || compactSearchLabelRect.left < searchLabelRect.left - 1
    || compactSearchLabelRect.right > searchLabelRect.right + 1
  ));
  const clipped = compactSearchClipped
    ? [searchLabel]
    : [];
  return {
    // scrollWidth includes clipped/focused descendants and stale popover geometry, so it can stay
    // wider after expansion even when every painted control fits. Visible control rectangles are
    // the layout contract and make the result independent of resize direction.
    overflow: outside.length > 0 || collisions.length > 0 || clipped.length > 0,
    outside,
    collisions,
    clipped,
  };
}

function topbarPackingOverflows() {
  return topbarPackingLayoutState().overflow;
}

function topbarPackingSyncNavigation(steps) {
  const compact = steps.includes('compact-menu');
  setTopbarNavigationCompactClass(compact);
  if (topbarNavigationCompact === compact) return false;
  topbarNavigationCompact = compact;
  renderSessionButtons({force: true});
  return true;
}

function syncTopbarPacking() {
  if (appMenuIsOpen()) return topbarPackingStepsApplied.slice();
  if (topbarPackingIsApplying) return topbarPackingStepsApplied.slice();
  topbarPackingIsApplying = true;
  try {
    // Every measurement starts from the same full presentation. Restoring one compact tier at a
    // time made the result depend on the previous viewport: a menu subtree rebuilt while expanding
    // could be measured before its next layout pass and leave most narrow-width steps stuck on.
    const applied = [];
    applyTopbarPackingSteps(applied);
    while (topbarPackingOverflows() && applied.length < topbarPackingStepOrder.length) {
      applied.push(topbarPackingStepOrder[applied.length]);
      applyTopbarPackingSteps(applied);
    }
    topbarPackingStepsApplied = applied.slice();
    return applied;
  } finally {
    topbarPackingIsApplying = false;
  }
}

function scheduleTopbarPacking() {
  if (topbarPackingIsApplying || topbarPackingFrame) return;
  topbarPackingFrame = requestAnimationFrame(() => {
    topbarPackingFrame = 0;
    syncTopbarPacking();
  });
}

// Pure geometry helper retained for responsive test coverage. It deliberately does not choose the
// rendered menu state: that decision must not depend on the current compact/full DOM shape.
function topbarFullMenuFitsAvailableSpace(areaWidth, fullMenuWidth, otherWidths = [], gap = 0) {
  const reservedWidth = otherWidths.reduce((sum, width) => sum + Math.max(0, Number(width) || 0), 0)
    + (Math.max(0, Number(gap) || 0) * otherWidths.length);
  return fullMenuWidth > 0 && fullMenuWidth <= Math.max(0, areaWidth - reservedWidth);
}

function topbarFullNavigationFits() {
  return null;
}

function setTopbarNavigationCompactClass(compact) {
  for (const target of [document.body, appRootElement()].filter(Boolean)) {
    target.classList?.toggle('app-topbar-menu-compact', compact);
  }
}

function topbarNavigationShouldBeCompact() {
  return topbarPackingHasStep('compact-menu');
}

function scheduleTopbarNavigationFitCheck() {
  scheduleTopbarPacking();
}

function installTopbarNavigationFitObserver() {
  const bar = document.querySelector('.topbar');
  if (topbarPackingObserver || !bar || typeof ResizeObserver !== 'function') return;
  topbarPackingObserver = new ResizeObserver(() => scheduleTopbarPacking());
  topbarPackingObserver.observe(bar);
}

function topbarMenuTree() {
  const menus = appMenuTree();
  const compact = topbarNavigationShouldBeCompact();
  topbarNavigationCompact = compact;
  setTopbarNavigationCompactClass(compact);
  if (!compact) return menus;
  return [{
    id: 'application-menu',
    // Translator context: this is a compact application-navigation control (File/View/tmux/Tabs/Help),
    // never a restaurant/food menu. Keep the local software-UI term short enough for the top bar.
    label: t('menu.compact.label'),
    nestedRoot: true,
    items: menus.map(menu => menuSubmenu(menu.label, menu.items)),
  }];
}

function syncTopbarNavigationPresentation() {
  const compact = topbarNavigationShouldBeCompact();
  setTopbarNavigationCompactClass(compact);
  if (topbarNavigationCompact === null || topbarNavigationCompact === compact) return false;
  topbarNavigationCompact = compact;
  closeAppMenus();
  renderSessionButtons({force: true});
  return true;
}

function appMenuIsOpen() {
  return Boolean(sessionButtons?.querySelector('.app-menu.open'));
}

function topbarControlIsActive() {
  const active = document.activeElement;
  return Boolean(active && sessionButtons?.contains(active) && active.matches?.('select, input, .topbar-language, .app-menu-button'));
}

function flushPendingSessionButtonsRender() {
  if (!pendingSessionButtonsRender || topbarControlIsActive()) return;
  pendingSessionButtonsRender = false;
  renderSessionButtons();
}

function renderSessionButtons(options = {}) {
  const perf = clientPerfStart('renderSessionButtons');
  try {
    return renderSessionButtonsMeasured(options);
  } finally {
    clientPerfEnd(perf, {nodes: sessionButtons?.childElementCount || 0});
  }
}

function renderSessionButtonsMeasured(options = {}) {
  if (!sessionButtons) return;
  // An SSE/locale/status repaint can otherwise detach a touch target after pointerdown but before
  // the browser emits click. An open menu is an explicit interaction, so defer every repaint until
  // it closes; the existing pending render path preserves the newest requested chrome state.
  if (appMenuIsOpen()) {
    if (options.force) pendingSessionButtonsRender = true;
    scheduleTopbarMetricsUpdate();
    return;
  }
  if (!options.force && topbarControlIsActive()) {
    pendingSessionButtonsRender = true;
    scheduleTopbarMetricsUpdate();
    return;
  }
  pendingSessionButtonsRender = false;
  const openMenu = sessionButtons.querySelector('.app-menu.open');
  if (openMenu) {
    openAppMenuId = openMenu.dataset.appMenu || null;
  } else {
    openAppMenuId = null;
    openAppMenuPinned = false;
    openAppMenuOpenedAt = 0;
  }
  // In compact mode the activity control is temporarily reparented before the action rail. Remove that
  // prior rendered instance before replacing the menu subtree, or each chrome refresh leaves a
  // duplicate button in the actions rail.
  document.querySelectorAll('.actions > #topbarActivity').forEach(activity => activity.remove());
  sessionButtons.innerHTML = '';
  sessionButtons.ondragover = event => {
    const payload = dragPayload(event);
    if (!payload?.session || !itemInLayout(payload.session)) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
    clearDropPreview();
    sessionButtons.classList.add(CLS.dragOver);
  };
  sessionButtons.ondragleave = event => {
    if (!sessionButtons.contains(event.relatedTarget)) sessionButtons.classList.remove(CLS.dragOver);
  };
  sessionButtons.ondrop = event => {
    const payload = dragPayload(event);
    sessionButtons.classList.remove(CLS.dragOver);
    if (!payload?.session) return;
    event.preventDefault();
    event.stopPropagation();
    removeSessionFromLayout(payload.session);
  };
  sessionButtons.classList.remove(CLS.dragOver);
  sessionButtons.appendChild(createAppMenuBar());
  sessionButtons.appendChild(createTopbarCenterTools());
  updateEditorNavButtons();   // sync ←/→ disabled state to the global editorNav stack after (re)assembly
  // Topbar right group: Language | Activity (activity pinned far-right). #257: the theme switcher was
  // removed as redundant — theme is set via View -> Theme and the Preferences Global color theme.
  sessionButtons.appendChild(createTopbarRightTools());
  updateTopbarOwnerStatus();
  updateTopbarActivityStatus();
  scheduleTopbarMetricsUpdate();
  installTopbarNavigationFitObserver();
  scheduleTopbarNavigationFitCheck();
}

// #52: the wordmark is server-rendered (YO/LO/m/u/x); localize the YO/LO glyphs client-side so a
// Chinese locale shows 優樂mux / 优乐mux (優/优 boxed-green, 樂/乐 green) and updates on a language switch
// without a reload. The m/u/x colorful spans and the version are untouched.
function renderBrandWordmark() {
  for (const yo of document.querySelectorAll('.brand-title .brand-yolo')) yo.textContent = t('brand.marker');
  for (const lo of document.querySelectorAll('.brand-title .brand-lo')) lo.textContent = t('brand.wordmark.lo');
  for (const brand of document.querySelectorAll('.brand-title')) {
    brand.setAttribute('aria-label', t('brand.version', {version: bootstrap.version || ''}));
  }
  updateBrandTitles();
}

function renderTopbarStaticChrome() {
  sessionButtons?.setAttribute('aria-label', t('app.menusAria'));
  if (latencyMeter) latencyMeter.title = t('app.latencyTitle');
  if (logoutButton) {
    const label = t('menu.file.logout');
    logoutButton.textContent = label;
    logoutButton.title = label;
    logoutButton.setAttribute('aria-label', label);
  }
}

function createAppMenuBar() {
  const bar = document.createElement('nav');
  bar.className = 'app-menu-bar';
  bar.setAttribute('aria-label', t('app.menusAria'));
  bar.setAttribute('role', 'menubar');
  for (const menu of topbarMenuTree()) bar.appendChild(createAppMenu(menu));
  return bar;
}

// the editor back/forward history control lives in the GLOBAL topbar (left of the search
// box), not per editor pane — it's one file-history control for the whole window, like a browser's.
// Buttons are always visible; updateEditorNavButtons() toggles their disabled state from editorNav.
function createTopbarNav() {
  const group = document.createElement('div');
  group.className = 'topbar-nav';
  group.setAttribute('role', 'group');
  group.setAttribute('aria-label', t('editor.nav.aria'));
  const back = makeButton({
    id: 'topbarNavBack',
    className: 'topbar-nav-button',
    title: t('editor.nav.back'),
    ariaLabel: t('editor.nav.back'),
    disabled: true,
    label: '←',
    onClick: event => { event.preventDefault(); editorNavBack(); },
  });
  const forward = makeButton({
    id: 'topbarNavForward',
    className: 'topbar-nav-button',
    title: t('editor.nav.forward'),
    ariaLabel: t('editor.nav.forward'),
    disabled: true,
    label: '→',
    onClick: event => { event.preventDefault(); editorNavForward(); },
  });
  group.append(back, forward);
  return group;
}

// Universal search affordance in the topbar's empty middle gap: a launcher that
// opens the existing unified palette (files/tabs/settings by default, `>` for
// commands) — it reuses openFileQuickOpen, it does not fork the palette logic.
function createTopbarSearch() {
  const isMac = /Mac|iP(hone|ad|od)/.test(navigator.platform || navigator.userAgent || '');
  const mod = isMac ? 'Cmd' : 'Ctrl';
  const button = makeButton({
    id: 'topbarSearch',
    className: 'topbar-search',
    ariaLabel: t('topbar.search.aria'),
    title: t('topbar.search.title', {mod}),
  });
  const icon = document.createElement('span');
  icon.className = 'topbar-search-icon';
  icon.setAttribute('aria-hidden', 'true');
  icon.textContent = '⌕';
  const label = document.createElement('span');
  label.className = 'topbar-search-label';
  const longLabel = document.createElement('span');
  longLabel.className = 'topbar-search-label-long';
  longLabel.textContent = t('topbar.search.label');
  const compactLabel = document.createElement('span');
  compactLabel.className = 'topbar-search-label-short';
  compactLabel.setAttribute('aria-hidden', 'true');
  compactLabel.textContent = t('common.search');
  label.append(longLabel, compactLabel);
  const hint = document.createElement('kbd');
  hint.className = 'topbar-search-hint';
  hint.textContent = isMac ? '⌘P' : 'Ctrl+P';
  button.append(icon, label, hint);
  button.addEventListener('click', () => openFileQuickOpen());
  return button;
}

function createTopbarCenterTools() {
  const group = document.createElement('div');
  group.className = 'topbar-center-tools';
  group.append(createTopbarNav(), createTopbarSearch());
  return group;
}

function createTopbarRightTools() {
  const group = document.createElement('div');
  group.className = 'topbar-right-tools';
  // GUI.md invariant: the backend-health control is the ONE permanently mounted, fixed icon-sized
  // shell in .topbar-right-tools, built once HERE and first in the row so it holds a stable slot
  // while healthy (data-backend-health=""). It is never inserted or removed on a health transition;
  // syncBackendHealthIndicator only repaints THIS same node (and its fallback re-mounts one solely
  // if this host is torn down and rebuilt at runtime). That keeps one permanent mount owner.
  // Order contract (#257) for the switchers follows: Language, Ownership, Activity.
  group.append(createBackendHealthIndicator());
  group.append(createTopbarLanguageSwitcher(), createTopbarOwnerStatus(), createTopbarActivityStatus());
  return group;
}

// Phase 1: a top-right language switcher (entry point #2). It writes the SAME general.language
// setting as the Preferences picker and applies the locale optimistically (no settings-poll round-trip).
// The app-menu popup owner keeps this control consistent with the rest of the topbar.
function createTopbarLanguageSwitcher() {
  const pref = String(initialSetting('general.language', 'system'));
  const choices = i18nLocaleChoices();
  const active = choices.find(choice => choice.value === pref) || choices[0] || {value: 'system', label: t('pref.general.language.system')};
  const wrapper = createAppMenu({
    id: 'language',
    label: active.label,
    items: choices.map(choice => ({
      label: choice.label,
      detail: '',
      checked: choice.value === pref,
      action: () => {
        const value = choice.value;
        applyLocale(resolveLocalePref(value));
        if (readOnlyMode) return;
        saveSettingsPatch(settingPatch('general.language', value))
          .catch(error => { statusErr(localizedHtml('status.settingsSaveFailed', {error: userMessageText(error, t('common.requestFailed'))})); refreshSettings({force: true}); });
      },
    })),
  });
  wrapper.classList.add('topbar-language-menu');
  const button = wrapper.querySelector(':scope > .app-menu-button');
  if (button) {
    button.classList.add('topbar-language');
    button.title = t('common.language');
    button.setAttribute('aria-label', t('common.language'));
    button.addEventListener('blur', flushPendingSessionButtonsRender);
  }
  wrapper.querySelector(':scope > .app-menu-popover')?.classList.add('topbar-language-popover');
  return wrapper;
}

function appMenuAnchorInlineSize(popover) {
  const anchor = popover?.parentElement?.querySelector?.(':scope > .app-menu-button, :scope > .app-menu-command');
  return Math.ceil(anchor?.getBoundingClientRect?.().width || 0);
}

function measureAppMenuContentWidth(popover) {
  if (!popover?.cloneNode || !document.body) return null;
  const clone = popover.cloneNode(true);
  clone.style.position = 'fixed';
  clone.style.insetInlineStart = '0';
  clone.style.insetBlockStart = '0';
  clone.style.transform = 'translateX(-100%)';
  clone.style.visibility = 'hidden';
  clone.style.pointerEvents = 'none';
  clone.style.opacity = '0';
  clone.style.width = 'max-content';
  clone.style.minWidth = '0';
  clone.style.maxWidth = 'none';
  clone.style.maxHeight = 'none';
  clone.style.removeProperty('--app-menu-fit-width');
  clone.style.removeProperty('--app-menu-fit-offset');
  // C14: a standalone submenu popover (measured on its own, with no .open parent) matches the base
  // `.app-submenu-popover { display:none }` rule and would measure 0 — force it visible for measurement.
  if (clone.classList?.contains('app-submenu-popover')) clone.style.display = 'block';
  clone.querySelectorAll('.app-submenu-popover').forEach(submenu => {
    submenu.style.display = 'block';
    submenu.style.width = 'max-content';
    submenu.style.minWidth = '0';
    submenu.style.maxWidth = 'none';
  });
  clone.querySelectorAll('.app-menu-command').forEach(command => {
    command.style.width = 'max-content';
    command.style.minWidth = '0';
    command.style.maxWidth = 'none';
  });
  clone.querySelectorAll('.app-menu-rich, .pane-tab-core, .session-button-text, .session-button-name, .session-button-dir, .session-button-detail, .tab-inline-detail, .pane-tab-info-label').forEach(node => {
    node.style.maxWidth = 'none';
    node.style.overflow = 'visible';
    node.style.textOverflow = 'clip';
    node.style.whiteSpace = 'nowrap';
  });
  // C14: the command label + detail spans were OMITTED above, so their truncation CSS (overflow:hidden,
  // nowrap, min-width:0 / max-width:42ch) collapsed them in max-content sizing and the menu was measured
  // to the LABELS — ellipsizing the longer detail sub-lines. Un-clip them so each command's full one-line
  // width is counted. Keep the detail's 42ch cap so a genuinely longer detail still ellipsizes by design.
  clone.querySelectorAll('.app-menu-label').forEach(node => {
    node.style.maxWidth = 'none';
    node.style.minWidth = 'auto';
    node.style.overflow = 'visible';
    node.style.textOverflow = 'clip';
    node.style.whiteSpace = 'nowrap';
  });
  clone.querySelectorAll('.app-menu-detail').forEach(node => {
    node.style.minWidth = 'auto';
    node.style.overflow = 'visible';
    node.style.textOverflow = 'clip';
    node.style.whiteSpace = 'nowrap';
  });
  document.body.appendChild(clone);
  const width = Math.ceil(clone.getBoundingClientRect().width || clone.scrollWidth || 0);
  clone.remove();
  return width || null;
}

function fitAppMenuPopover(popover) {
  if (!popover) return;
  popover.style.setProperty('--app-menu-fit-offset', '0px');
  popover.style.removeProperty('--app-menu-fit-width');
  const measured = measureAppMenuContentWidth(popover);
  const anchorWidth = appMenuAnchorInlineSize(popover);
  const desiredWidth = Math.max(anchorWidth, measured || 0);
  if (desiredWidth > 0) popover.style.setProperty('--app-menu-fit-width', `${desiredWidth}px`);

  const rect = popover.getBoundingClientRect();
  const viewportRight = viewportBounds(popoverEdgeGapPx()).right;
  if (!rect.width || !viewportRight) return;
  const overflow = Math.max(0, rect.right - viewportRight);
  if (!overflow) return;
  const maxShift = Math.max(0, rect.width - anchorWidth);
  popover.style.setProperty('--app-menu-fit-offset', `${-Math.min(overflow, maxShift)}px`);
  // C14: a cold first measurement taken before web fonts settle sizes with fallback-font metrics and can
  // come out too narrow. Re-fit ONCE when fonts are ready (guarded so it schedules a single time) so the
  // very first menu open is corrected without waiting for a reopen.
  if (document.fonts?.ready && !popover._appMenuFontsRefit) {
    popover._appMenuFontsRefit = true;
    document.fonts.ready.then(() => { if (popover.isConnected) fitAppMenuPopover(popover); }).catch(() => {});
  }
}

function createAppMenu(menu) {
  const wrapper = document.createElement('div');
  wrapper.className = `app-menu${menu.nestedRoot ? ' app-menu--nested-root' : ''}`;
  wrapper.dataset.appMenu = menu.id;
  const popover = document.createElement('div');
  popover.className = 'app-menu-popover';
  popover.setAttribute('role', 'menu');
  popover.setAttribute('aria-label', menu.label);
  for (const item of menu.items) popover.appendChild(createAppMenuItem(item));
  fitAppMenuPopover(popover);
  const activateMenu = event => {
    event.preventDefault();
    event.stopPropagation();
    if (wrapper.classList.contains(CLS.open)) {
      const openMs = Date.now() - openAppMenuOpenedAt;
      // Every coarse-pointer top-level menu is a disclosure: its next tap must collapse the
      // currently open sheet immediately. Cursor-driven roots keep the short grace period that
      // prevents one physical pointer interaction from being interpreted as open then close.
      if (browserUsesCoarsePointer() || wrapper.classList.contains('app-menu--nested-root') || (openAppMenuPinned && openMs >= menuClickCloseGraceMs)) closeAppMenus();
      else openAppMenu(wrapper, {focusFirst: false, pinned: true});
      return;
    }
    openAppMenu(wrapper, {focusFirst: false, pinned: true});
  };
  const button = makeButton({
    className: 'app-menu-button',
    role: 'menuitem',
    html: `${esc(menu.label)}${menu.badgeText ? `<span class="badge-base app-menu-button-badge" title="${esc(menu.badgeTitle || '')}">${esc(menu.badgeText)}</span>` : ''}`,
    attributes: {'aria-haspopup': 'true', 'aria-expanded': openAppMenuId === menu.id ? 'true' : 'false'},
    onClick: event => {
      if (button.dataset.pointerActionHandled === '1') {
        delete button.dataset.pointerActionHandled;
        return;
      }
      activateMenu(event);
    },
    events: {
      keydown: event => handleAppMenuButtonKeydown(event, wrapper),
      pointerdown: event => {
        if (event.button !== 0) return;
        // Open before a browser turns the tap into click, so an async chrome repaint cannot make
        // the compact Menus target disappear under the user's finger.
        button.dataset.pointerActionHandled = '1';
        activateMenu(event);
      },
    },
  });
  wrapper.append(button, popover);
  button.addEventListener('blur', flushPendingSessionButtonsRender);
  if (openAppMenuId === menu.id) wrapper.classList.add(CLS.open);
  bindAppMenuHover(wrapper);
  return wrapper;
}

function createAppMenuItem(item) {
  if (item.type === 'separator') {
    const node = document.createElement('div');
    node.className = 'app-menu-separator';
    node.role = 'separator';
    return node;
  }
  if (item.type === 'section') {
    const node = document.createElement('div');
    node.className = 'app-menu-section';
    node.textContent = item.label;
    return node;
  }
  if (item.type === 'number-setting') return createAppMenuNumberSetting(item);
  if (item.type === 'command-pair') return createAppMenuCommandPair(item);
  if (item.type === 'command-row') return createAppMenuCommandRow(item);
  if (item.type === 'submenu') return createAppSubmenu(item);
  return createAppMenuCommand(item);
}

function createAppMenuCommandPair(item) {
  return createAppMenuCommandGroup([item.primary, item.secondary], item.className, [item.primary?.label, item.secondary?.ariaLabel || item.secondary?.label], {separator: true});
}

function createAppMenuCommandRow(item) {
  return createAppMenuCommandGroup(item.items || [], item.className, [item.label, ...(item.items || []).map(command => command?.ariaLabel || command?.label)], {
    separator: item.separator ?? Boolean(item.label),
    prefixLabel: item.label,
    prefixIconHtml: item.iconHtml,
  });
}

function createAppMenuCommandGroup(items, className, labels, options = {}) {
  const row = document.createElement('div');
  row.className = ['app-menu-command-group', className || ''].filter(Boolean).join(' ');
  row.setAttribute('role', 'group');
  row.setAttribute('aria-label', labels.filter(Boolean).join(' / '));
  for (const [index, command] of items.entries()) {
    if (index === 0 && options.prefixLabel) {
      const prefix = document.createElement('span');
      prefix.className = 'app-menu-command-row-label';
      const iconHtml = options.prefixIconHtml ? `<span class="app-menu-icon">${stripTitleAttrs(options.prefixIconHtml)}</span>` : '';
      prefix.innerHTML = `${iconHtml}<span>${esc(options.prefixLabel)}</span>`;
      row.appendChild(prefix);
    }
    if (options.separator === true && (index > 0 || options.prefixLabel)) {
      const separator = document.createElement('span');
      separator.className = 'app-menu-command-separator';
      separator.setAttribute('aria-hidden', 'true');
      separator.textContent = '|';
      row.appendChild(separator);
    }
    row.appendChild(createAppMenuCommand(command));
  }
  return row;
}

function clampAppMenuNumberSetting(item, rawValue) {
  const fallback = Number.isFinite(Number(item.fallback)) ? Number(item.fallback) : 0;
  let value = Number(rawValue);
  if (!Number.isFinite(value)) value = fallback;
  if (Number.isFinite(Number(item.min))) value = Math.max(Number(item.min), value);
  if (Number.isFinite(Number(item.max))) value = Math.min(Number(item.max), value);
  return Number.isInteger(value) ? Math.round(value) : value;
}

function applyAppMenuNumberSettingPreview(path, value) {
  void path;
  void value;
}

function createAppMenuNumberSetting(item) {
  const row = document.createElement('label');
  row.className = ['app-menu-setting-row', 'app-menu-number-setting', item.className || ''].filter(Boolean).join(' ');
  row.setAttribute('role', 'none');
  row.dataset.settingPath = item.path || '';
  const label = document.createElement('span');
  label.className = 'app-menu-setting-label';
  label.textContent = item.label || item.path || '';
  const control = document.createElement('span');
  control.className = 'app-menu-setting-control';
  const input = document.createElement('input');
  input.type = 'number';
  input.inputMode = 'decimal';
  input.dataset.settingPath = item.path || '';
  input.min = String(item.min ?? '');
  input.max = String(item.max ?? '');
  input.step = String(item.step || 1);
  input.value = String(clampAppMenuNumberSetting(item, numberSetting(item.path, item.fallback ?? 0)));
  input.disabled = readOnlyMode || item.disabled === true;
  if (item.detail) input.title = item.detail;
  input.setAttribute('aria-label', item.label || item.path || '');
  input.addEventListener('click', event => event.stopPropagation());
  input.addEventListener('keydown', event => event.stopPropagation());
  input.addEventListener('input', event => {
    event.stopPropagation();
    const next = clampAppMenuNumberSetting(item, input.value);
    applyAppMenuNumberSettingPreview(item.path, next);
  });
  input.addEventListener('change', event => {
    event.preventDefault();
    event.stopPropagation();
    const next = clampAppMenuNumberSetting(item, input.value);
    input.value = String(next);
    applyAppMenuNumberSettingPreview(item.path, next);
    saveSettingsPatch(settingPatch(item.path, next))
      .then(() => {
        renderPreferencesPanels();
        statusEl.textContent = t('status.settingSaved', {path: item.path});
      })
      .catch(error => {
        statusErr(localizedHtml('status.settingsSaveFailed', {error: userMessageText(error, t('common.requestFailed'))}));
        refreshSettings({force: true});
      });
  });
  control.appendChild(input);
  if (item.suffix) {
    const suffix = document.createElement('span');
    suffix.className = 'app-menu-setting-suffix';
    suffix.textContent = item.suffix;
    control.appendChild(suffix);
  }
  row.append(label, control);
  return row;
}

function createAppSubmenu(item) {
  const wrapper = document.createElement('div');
  wrapper.className = ['app-menu-submenu-wrap', item.className || ''].filter(Boolean).join(' ');
  const button = createAppMenuCommand({
    label: item.label,
    disabled: item.disabled,
    detail: item.detail,
    className: ['app-menu-submenu-button', item.className || ''].filter(Boolean).join(' '),
  }, {asSubmenu: true});
  const submenu = document.createElement('div');
  submenu.className = 'app-submenu-popover';
  submenu.setAttribute('role', 'menu');
  submenu.setAttribute('aria-label', item.label);
  for (const child of item.items || []) submenu.appendChild(createAppMenuItem(child));
  fitAppMenuPopover(submenu);
  const setOpen = open => {
    wrapper.classList.toggle(CLS.open, open);
    button.setAttribute('aria-expanded', open ? 'true' : 'false');
  };
  const compactRoot = () => {
    const root = wrapper.closest('.app-menu--nested-root');
    return root?.querySelector(':scope > .app-menu-popover') === wrapper.parentElement ? root : null;
  };
  const open = () => {
    const root = compactRoot();
    // File/View/tmux/Tabs/Help share one phone Menus layer: switch categories or collapse the
    // current category without forcing the user to close and reopen the Menus root.
    root?.querySelectorAll(':scope > .app-menu-popover > .app-menu-submenu-wrap.open').forEach(sibling => {
      if (sibling !== wrapper) {
        sibling.classList.remove(CLS.open);
        sibling.querySelector(':scope > .app-menu-command')?.setAttribute('aria-expanded', 'false');
      }
    });
    setOpen(true);
  };
  const toggle = () => {
    if (button.disabled) return false;
    if (compactRoot() && wrapper.classList.contains(CLS.open)) {
      setOpen(false);
      return true;
    }
    open();
    return true;
  };
  button.addEventListener('pointerdown', event => {
    // Touch browsers can retain the synthetic click after the nested popover has reflowed. Toggle
    // on the original physical press so File/View/tmux/Tabs/Help always collapse on their next tap.
    if (event.button !== 0 || !compactRoot()) return;
    button.dataset.pointerActionHandled = '1';
    event.preventDefault();
    event.stopPropagation();
    toggle();
  });
  button.addEventListener('click', event => {
    event.preventDefault();
    event.stopPropagation();
    if (button.dataset.pointerActionHandled === '1') {
      delete button.dataset.pointerActionHandled;
      return;
    }
    toggle();
  });
  button.addEventListener('keydown', event => {
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      open();
      focusFirstAppMenuCommand(submenu);
    }
  });
  button.setAttribute('aria-haspopup', 'true');
  button.setAttribute('aria-expanded', 'false');
  wrapper.append(button, submenu);
  return wrapper;
}

function createAppMenuCommand(item, options = {}) {
  const ariaLabel = item.ariaLabel || [item.label, item.detail].filter(Boolean).join(' - ');
  const richHtml = item.html ? stripTitleAttrs(item.html) : '';
  const iconHtml = item.iconHtml ? stripTitleAttrs(item.iconHtml) : '';
  const contentHtml = richHtml
    ? `<span class="app-menu-rich">${richHtml}</span>`
    : `<span class="app-menu-line">${iconHtml ? `<span class="app-menu-icon">${iconHtml}</span>` : ''}<span class="app-menu-label">${esc(item.label)}</span></span>`;
  const detailClass = ['app-menu-detail', item.className === 'app-menu-file-destination' ? 'app-menu-label' : ''].filter(Boolean).join(' ');
  const detailHtml = item.detail ? `<span class="${detailClass}" title="${esc(item.detail)}">${esc(item.detail)}</span>` : '';
  const button = makeButton({
    className: ['app-menu-command', item.className || '', item.partial === true ? 'partially-checked' : '', options.asSubmenu ? 'has-submenu' : ''].filter(Boolean).join(' '),
    role: item.checked !== undefined ? 'menuitemcheckbox' : 'menuitem',
    checked: item.checked,
    disabled: item.disabled,
    ariaLabel,
    title: item.title,
    dataset: (item.checked !== undefined || item.partial === true || item.targetItem) ? {
      ...(item.checked !== undefined || item.partial === true ? {checked: item.checked ? 'true' : 'false', partial: item.partial === true ? 'true' : 'false'} : {}),
      ...(item.targetItem ? {menuTargetItem: item.targetItem} : {}),
    } : undefined,
    html: `<span class="app-menu-check" aria-hidden="true"></span><span class="app-menu-content">${contentHtml}${detailHtml}</span>${options.asSubmenu ? '<span class="app-menu-submenu-arrow" aria-hidden="true">&gt;</span>' : ''}`,
  });
  if (!options.asSubmenu) {
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      const autoTarget = event.target.closest('[data-auto-session]');
      if (autoTarget && button.contains(autoTarget)) {
        if (readOnlyMode) {
          statusEl.textContent = t('status.yoloAdminRequired');
          return;
        }
        toggleAutoApprove(autoTarget.dataset.autoSession).then(() => {
          renderSessionButtons({force: true});
          renderPaneTabStrips();
        });
        return;
      }
      runAppMenuCommand(item);
    });
  }
  button.addEventListener('keydown', event => handleAppMenuCommandKeydown(event, button, item, options));
  return button;
}

function runAppMenuCommand(item) {
  if (item.disabled || typeof item.action !== 'function') return;
  const keepOpen = item.keepOpen === true;
  if (!keepOpen) closeAppMenus();
  try {
    Promise.resolve(item.action())
      .then(() => {
        if (keepOpen && item.renderMenu !== false) renderSessionButtons({force: true});
      })
      .catch(error => {
        statusErr(localizedHtml('status.menuCommandFailed', {error}));
        if (keepOpen && item.renderMenu !== false) renderSessionButtons({force: true});
      });
  } catch (error) {
    statusErr(localizedHtml('status.menuCommandFailed', {error}));
    if (keepOpen) renderSessionButtons({force: true});
  }
}

function appMenuCommands(container) {
  const scope = container.classList?.contains('app-menu')
    ? container.querySelector(':scope > .app-menu-popover')
    : container;
  if (!scope) return [];
  return Array.from(scope.querySelectorAll('.app-menu-command'))
    .filter(button => !button.disabled && button.closest('.app-menu-popover, .app-submenu-popover') === scope);
}

function focusFirstAppMenuCommand(container) {
  appMenuCommands(container)[0]?.focus();
}

function focusAdjacentAppMenuCommand(button, direction) {
  const popover = button.closest('.app-menu-popover, .app-submenu-popover');
  if (!popover) return;
  const commands = appMenuCommands(popover);
  const index = commands.indexOf(button);
  if (!commands.length || index < 0) return;
  const next = commands[(index + direction + commands.length) % commands.length];
  next.focus();
}

function focusAdjacentTopMenu(wrapper, direction) {
  const menus = Array.from(sessionButtons.querySelectorAll('.app-menu'));
  const index = menus.indexOf(wrapper);
  if (index < 0 || !menus.length) return;
  const next = menus[(index + direction + menus.length) % menus.length];
  openAppMenu(next, {focusFirst: false});
  next.querySelector('.app-menu-button')?.focus();
}

function handleAppMenuButtonKeydown(event, wrapper) {
  if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
    event.preventDefault();
    openAppMenu(wrapper, {focusFirst: true, pinned: true});
  } else if (event.key === 'ArrowRight') {
    event.preventDefault();
    focusAdjacentTopMenu(wrapper, 1);
  } else if (event.key === 'ArrowLeft') {
    event.preventDefault();
    focusAdjacentTopMenu(wrapper, -1);
  } else if (event.key === 'Escape') {
    closeAppMenus();
  }
}

function handleAppMenuCommandKeydown(event, button, item, options = {}) {
  if (event.key === 'ArrowDown') {
    event.preventDefault();
    focusAdjacentAppMenuCommand(button, 1);
  } else if (event.key === 'ArrowUp') {
    event.preventDefault();
    focusAdjacentAppMenuCommand(button, -1);
  } else if (event.key === 'Escape') {
    event.preventDefault();
    closeAppMenus();
    button.closest('.app-menu')?.querySelector('.app-menu-button')?.focus();
  } else if (event.key === 'ArrowLeft') {
    event.preventDefault();
    const submenu = button.closest('.app-submenu-popover');
    if (submenu) {
      submenu.closest('.app-menu-submenu-wrap')?.querySelector(':scope > .app-menu-command')?.focus();
      return;
    }
    const wrapper = button.closest('.app-menu');
    if (wrapper) focusAdjacentTopMenu(wrapper, -1);
  } else if (event.key === 'ArrowRight') {
    event.preventDefault();
    const submenu = button.closest('.app-menu-submenu-wrap')?.querySelector(':scope > .app-submenu-popover');
    if (submenu && options.asSubmenu) {
      focusFirstAppMenuCommand(submenu);
      return;
    }
    const wrapper = button.closest('.app-menu');
    if (wrapper) focusAdjacentTopMenu(wrapper, 1);
  } else if (!options.asSubmenu && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault();
    runAppMenuCommand(item);
  }
}

function bindAppMenuHover(wrapper) {
  createHoverPopover({
    anchor: wrapper,
    popover: () => wrapper.querySelector(':scope > .app-menu-popover'),
    stateClass: '',
    canOpen: event => autoFocusCanFollowCursor(event) || appMenuIsOpen(),
    showDelay: () => (appMenuIsOpen() ? popoverHideDelayMs : popoverShowDelayMs),
    hideDelay: () => popoverHideDelayMs,
    stillActive: () => (
      (openAppMenuPinned && openAppMenuId === wrapper.dataset.appMenu)
      || popoverStillActive(wrapper, wrapper.querySelector(':scope > .app-menu-popover'))
    ),
    onOpen: () => {
      const menuId = wrapper.dataset.appMenu || '';
      const currentWrapper = document.querySelector(`.app-menu[data-app-menu="${cssEscape(menuId)}"]`) || wrapper;
      if (!currentWrapper.classList.contains(CLS.open)) openAppMenu(currentWrapper, {focusFirst: false, pinned: false});
    },
    onClose: () => {
      const menuId = wrapper.dataset.appMenu || '';
      if (!wrapper.matches?.(':hover') && openAppMenuId === menuId && !document.querySelector('.app-menu:hover')) closeAppMenus();
    },
  });
}

function openAppMenu(wrapper, options = {}) {
  if (!wrapper) return;
  closeContextMenus();
  closeOtherSessionPopovers(null, {force: true});
  closeFileImagePreview();
  closeAppMenus(wrapper);
  fitAppMenuPopover(wrapper.querySelector(':scope > .app-menu-popover'));
  wrapper.querySelectorAll(':scope > .app-menu-popover .app-submenu-popover').forEach(fitAppMenuPopover);
  wrapper.classList.add(CLS.open);
  if (!wrapper.classList.contains('app-menu--nested-root')) {
    wrapper.querySelectorAll('.app-menu-submenu-wrap').forEach(submenu => {
      submenu.classList.add(CLS.open);
      submenu.querySelector(':scope > .app-menu-command')?.setAttribute('aria-expanded', 'true');
    });
  }
  openAppMenuId = wrapper.dataset.appMenu || null;
  openAppMenuPinned = options.pinned === true;
  openAppMenuOpenedAt = Date.now();
  wrapper.querySelector('.app-menu-button')?.setAttribute('aria-expanded', 'true');
  if (openAppMenuId === 'tabs') refreshTabsMenuMetadataOnOpen();
  if (options.focusFirst) requestAnimationFrame(() => focusFirstAppMenuCommand(wrapper));
}

function closeAppMenus(keepOpen = null) {
  for (const menu of document.querySelectorAll('.app-menu.open')) {
    if (menu === keepOpen) continue;
    menu.classList.remove(CLS.open);
    menu.querySelector('.app-menu-button')?.setAttribute('aria-expanded', 'false');
  }
  for (const submenu of document.querySelectorAll('.app-menu-submenu-wrap.open')) {
    if (keepOpen?.contains(submenu)) continue;
    submenu.classList.remove(CLS.open);
    submenu.querySelector(':scope > .app-menu-command')?.setAttribute('aria-expanded', 'false');
  }
  openAppMenuId = keepOpen?.dataset?.appMenu || null;
  if (!openAppMenuId) {
    openAppMenuPinned = false;
    openAppMenuOpenedAt = 0;
  }
}
